create function private.official_bank_tax_cm223(p_action text)
returns text language plpgsql security invoker set search_path = '' as $official_bank$
declare
  v_bank jsonb := $official_bank_source${"code":"TAX-CM223","courseId":"b7bba625-d122-5afa-8b13-127d96411059","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":396,"shell":{"contentKey":"business-taxation-2","titles":["Business Taxation II"],"level":"200-level","semesters":["second-semester"]},"audited":[],"keep":[],"retire":[],"add":[{"itemId":"6706bf70-3c73-5e0a-a58b-f56c57dd627b","questionId":"6426d599-a7f9-5289-933c-da986ed9e212","sourceKey":"bank:TAX-CM223:PQ-002-a","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025, which statement best describes withholding tax?","options":["It is tax the recipient pays to the tax authority after receiving the gross amount","It is a separate final tax on the payer's own profits","It is a consumption tax added on top of the invoice amount, like VAT","It is tax deducted by the payer when a payment is made and credited as an advance payment against the recipient's income tax"],"correctOption":3,"section":"Withholding Tax","explanation":"Withholding tax is a collection mechanism, not a separate tax: the payer acts as agent, deducts tax at the date of payment or settlement and remits it, and the recipient later uses the deduction as a credit against its final income tax. Option B wrongly treats it as a tax on the payer. Option A reverses the roles, and option C confuses it with VAT, which is added to the price rather than deducted from it."}},{"itemId":"46e8cba1-fa99-53b2-9c8b-7592f34a808d","questionId":"16d3d882-abdf-5d6f-a1d5-439ac84ed4ee","sourceKey":"bank:TAX-CM223:PQ-002-b","payload":{"prompt":"Under section 51(1) of the Nigeria Tax Administration Act 2025, where are the specific withholding tax rates found?","options":["In the annual Appropriation Act","In regulations on deduction of tax at the time of payment, not in the text of the NTA 2025 or NTAA 2025","In circulars issued separately by each State Internal Revenue Service","In a rate table in the Nigeria Tax Act 2025 itself"],"correctOption":1,"section":"Withholding Tax","explanation":"Section 51(1) NTAA 2025 requires the payer to deduct tax at the rate prescribed in regulations relating to deduction of tax, so the detailed rate table sits in subsidiary legislation. This lets rates be adjusted without amending the Acts. Option D is the tempting wrong choice, but neither 2025 Act contains the withholding rate table. Options A and C are not the legal home of the rates."}},{"itemId":"105061ec-9416-5f1f-a5d4-2445f6c54dca","questionId":"786291b3-0715-5b46-8650-684d859759d2","sourceKey":"bank:TAX-CM223:PQ-002-c","payload":{"prompt":"Withholding tax regulations made under repealed laws, such as the 2024 Withholding Tax Regulations made under the old income tax Acts, still apply under the 2025 framework mainly because","options":["the Nigeria Revenue Service re-issues them every year as a circular","the repealed Companies Income Tax Act remains in force until 2030","the savings provisions keep subsidiary legislation made under repealed Acts in force, so far as it is not inconsistent with the new Acts","regulations always survive the repeal of their parent Act, whatever the new law says"],"correctOption":2,"section":"Withholding Tax","explanation":"When the 2025 Acts repealed the old income tax laws, savings provisions preserved existing subsidiary legislation to the extent it is consistent with the new Acts, which is why the existing withholding rates continue to apply. Option B is wrong because the old Acts were repealed. Option D overstates the position, since the regulations survive only because of the savings provisions and only where not inconsistent."}},{"itemId":"d79ec367-2ef0-5a74-b1ff-bca5d9f78e71","questionId":"80191962-4389-5ff3-aa38-d8d55b0cf673","sourceKey":"bank:TAX-CM223:PQ-002-d","payload":{"prompt":"Under the 2025 framework, a Nigerian company receives a dividend from another Nigerian company after 10% withholding tax has been deducted. How is the dividend treated in the recipient's hands?","options":["As exempt income only if it is reinvested within one year","As franked investment income, which is not subject to further income tax","As a chargeable gain taxed at 30%","As part of its total profits, taxed again at 30% with credit for the withholding tax"],"correctOption":1,"section":"Withholding Tax","explanation":"A dividend that has suffered withholding tax is franked investment income in the hands of a Nigerian company, so the withholding deduction is the final tax on it. Option D would tax the same dividend twice. Option C confuses dividends with gains on disposal of assets, and option A adds a condition that does not exist."}},{"itemId":"82a4cc9c-e880-53af-ba21-f0e04fcea8d0","questionId":"e0f6fcb3-2379-5afb-8574-e1f33e893f22","sourceKey":"bank:TAX-CM223:PQ-003-a","payload":{"prompt":"Under section 105 of the Nigeria Tax Administration Act 2025, a person who fails to deduct or withhold tax is liable to an administrative penalty of","options":["N100,000 for the first month and N50,000 for each later month","10% of the amount not deducted","10% per annum of the amount not deducted","40% of the amount not deducted"],"correctOption":3,"section":"Withholding Tax","explanation":"Section 105 NTAA 2025 imposes an administrative penalty of 40% of the tax that should have been deducted, a strong deterrent aimed at the withholding agent. Option C is the rate for failing to remit tax that was deducted, which is a different offence. Option B reflects the old regime, and option A is the style of penalty used for late filing of returns."}},{"itemId":"18ff8b1d-c1e1-543b-baa1-a9d7a3d1a59e","questionId":"139e4cc4-6f45-5a2e-ac51-ca39d9cb17e7","sourceKey":"bank:TAX-CM223:PQ-003-b","payload":{"prompt":"Under section 107(1) of the Nigeria Tax Administration Act 2025, a person who deducts tax but fails to remit it by the due date is liable to","options":["a flat fine of N1,000,000","interest at a fixed rate of 10% per annum only","an administrative penalty of 10% per annum of the tax not remitted, plus interest at the prevailing CBN monetary policy rate","a penalty of 40% of the tax not remitted, with no interest"],"correctOption":2,"section":"Withholding Tax","explanation":"For tax deducted but not remitted, section 107(1) NTAA 2025 charges a penalty of 10% per annum on the unremitted amount plus interest at the prevailing CBN monetary policy rate, on top of the tax itself. Option D is the penalty for failing to deduct, not failing to remit. Option B is wrong because interest now follows the CBN monetary policy rate rather than a fixed rate."}},{"itemId":"b9f3d737-7321-51ff-83fa-e5c104a4e605","questionId":"e5b65048-21a7-53fa-9d6b-83658e032807","sourceKey":"bank:TAX-CM223:PQ-003-d","payload":{"prompt":"Under section 107(3) of the Nigeria Tax Administration Act 2025, a person convicted of failing to remit tax deducted is liable to a fine, imprisonment, or both. What is the maximum term of imprisonment?","options":["Three years","Ten years","Life imprisonment","Six months"],"correctOption":0,"section":"Withholding Tax","explanation":"Section 107(3) NTAA 2025 provides for imprisonment of up to three years, a fine, or both on conviction for failure to remit tax deducted, because the agent is holding money that belongs to the government. Options D, B and C state terms that do not appear in the provision."}},{"itemId":"0232fb80-7a84-580c-90aa-f7cb18c2a0da","questionId":"454bb16c-068e-5c58-bc2c-ee98e59b94f6","sourceKey":"bank:TAX-CM223:PQ-007-a","payload":{"prompt":"Under section 41(2)(a) of the Nigeria Tax Administration Act 2025, within what period must a taxpayer deliver a notice of objection to a disputed assessment?","options":["90 days from the date of service","14 days from the date of service","30 days from the date of service of the notice of assessment","12 months from the end of the year of assessment"],"correctOption":2,"section":"Withholding Tax","explanation":"The objection must reach the relevant tax authority within 30 days of service of the disputed assessment, although the authority may extend the time for good cause. Option A is the time the tax authority has to respond, not the time to object. Options B and D are not the statutory period."}},{"itemId":"c07b9842-5460-5baf-a657-d5a69634e37c","questionId":"fcfacb98-5958-5fe8-bb19-ac13107d4701","sourceKey":"bank:TAX-CM223:PQ-007-b","payload":{"prompt":"Under section 41(6) of the Nigeria Tax Administration Act 2025, what happens if the tax authority does not respond to a valid notice of objection within the prescribed time?","options":["Nothing; the authority may respond at any time","After 90 days without a response, the assessment becomes final and conclusive","After 90 days without a response, the taxpayer's objection is upheld","After 30 days without a response, the taxpayer must appeal to the Federal High Court"],"correctOption":2,"section":"Withholding Tax","explanation":"The authority must respond within 90 days, and if it stays silent the taxpayer's objection is upheld, which protects taxpayers from indefinite delay. Option B reverses the consequence. Option D gives the wrong period and the wrong forum, and option A ignores the deadline."}},{"itemId":"b86c2e18-eac7-5772-8ebb-8affeee8154b","questionId":"06ecdb34-bdda-51dc-b113-62b8a316a073","sourceKey":"bank:TAX-CM223:PQ-007-c","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025, if the tax authority refuses a taxpayer's objection, what is the taxpayer's next step?","options":["Appeal directly to the Supreme Court","Nothing; refusal of the objection is final","Appeal to the Tax Appeal Tribunal","Petition the National Assembly for a review"],"correctOption":2,"section":"Withholding Tax","explanation":"A taxpayer whose objection is refused can exercise the right of appeal, starting at the Tax Appeal Tribunal, with further appeals on points of law going to the regular courts. Option A skips every step of the appeal ladder. Option D is not part of the dispute process, and option B is wrong because refusal opens the right of appeal."}},{"itemId":"b0d84522-ed38-5541-98c1-151144d35b71","questionId":"83d134da-0e3a-5cc5-a9f8-be62fa91c8fe","sourceKey":"bank:TAX-CM223:PQ-008-a","payload":{"prompt":"Coronet Engineering Ltd, a Nigerian resident company, makes payments in March 2026. Apply the withholding tax rates in force under the Nigeria Tax Administration Act 2025 and the 2024 Withholding Tax Regulations. It pays dividends of N60,000,000: N40,000,000 to corporate shareholders and N20,000,000 to individual shareholders, with withholding tax at 10% on both. What is the total withholding tax, and what net dividend do the shareholders receive?","options":["WHT N4,000,000; net dividends N56,000,000","WHT N12,000,000; net dividends N48,000,000","WHT N3,000,000; net dividends N57,000,000","WHT N6,000,000; net dividends N54,000,000"],"correctOption":3,"section":"Withholding Tax","explanation":"Dividends to both corporate and individual shareholders bear 10% withholding tax, so N60,000,000 x 10% = N6,000,000 is withheld and the shareholders receive N54,000,000. Option A wrongly withholds only on the corporate shareholders. Option C uses 5%, and option B uses 20%."}},{"itemId":"7ac7ce14-b75c-5603-8f24-66d8afed9237","questionId":"5e7516d9-bc04-5217-8f8b-4737cac57425","sourceKey":"bank:TAX-CM223:PQ-008-b","payload":{"prompt":"Coronet Engineering Ltd, a Nigerian resident company, makes payments in March 2026. Apply the withholding tax rates in force under the Nigeria Tax Administration Act 2025 and the 2024 Withholding Tax Regulations. Coronet deducted withholding tax on dividends paid to corporate shareholders during March 2026. Under section 107(1) of the NTAA 2025, by what date must the tax be remitted?","options":["21 April 2026","21 March 2026","21 days after each dividend payment date","30 April 2026"],"correctOption":0,"section":"Withholding Tax","explanation":"Section 107(1) NTAA 2025 requires tax deducted to be remitted by the 21st day of the month after the month of deduction, so March deductions are due by 21 April 2026. Option C reflects the old 21-days-from-payment practice. Option B falls in the month of deduction itself, and option D is not the statutory date."}},{"itemId":"5c964dd3-79ba-5881-a9b3-49faabaaeffe","questionId":"83aec229-b305-58aa-bab5-4b218b517aa0","sourceKey":"bank:TAX-CM223:PQ-008-c","payload":{"prompt":"Coronet Engineering Ltd, a Nigerian resident company, makes payments in March 2026. Apply the withholding tax rates in force under the Nigeria Tax Administration Act 2025 and the 2024 Withholding Tax Regulations. Prestige Insurance Plc pays Coronet professional fees of N9,000,000. The withholding tax rate on professional fees paid to a resident company is 5%. How much does Prestige deduct, and how much does Coronet receive?","options":["Prestige deducts N180,000; Coronet receives N8,820,000","Prestige deducts N450,000; Coronet receives N8,550,000","Prestige deducts N900,000; Coronet receives N8,100,000","Prestige deducts N450,000; Coronet receives N9,000,000"],"correctOption":1,"section":"Withholding Tax","explanation":"Prestige, as the payer, is the withholding agent: N9,000,000 x 5% = N450,000 is withheld and Coronet receives N8,550,000, using the N450,000 as a credit against its own tax. Option C applies the older 10% rate for resident companies. Option A uses the 2% rate for general services, and option D forgets that the tax comes out of the payment."}},{"itemId":"679ef396-7019-5670-b9ef-80612aceeb5a","questionId":"2e158723-d37d-52ab-aa25-e044e9dc201d","sourceKey":"bank:TAX-CM223:PQ-008-d","payload":{"prompt":"Coronet Engineering Ltd, a Nigerian resident company, makes payments in March 2026. Apply the withholding tax rates in force under the Nigeria Tax Administration Act 2025 and the 2024 Withholding Tax Regulations. Coronet pays rent of N5,000,000 to a property company (withholding rate 10%) and N30,000,000 to Solo Builders Ltd, a resident company, for construction of a building (withholding rate 2%). What total withholding tax should Coronet deduct on these two payments?","options":["N3,500,000","N1,100,000","N2,000,000","N600,000"],"correctOption":1,"section":"Withholding Tax","explanation":"Each payment uses its own rate: rent N5,000,000 x 10% = N500,000 and building construction N30,000,000 x 2% = N600,000, giving N1,100,000. Option A applies 10% to both payments. Option C applies 5% to the construction payment, and option D leaves out the rent."}},{"itemId":"e86394f6-fd7e-599e-bec9-41d2a2eb4ea8","questionId":"d8ba0c84-fce9-51d2-b786-fe73e1e5d391","sourceKey":"bank:TAX-CM223:PQ-008-e","payload":{"prompt":"Coronet Engineering Ltd, a Nigerian resident company, makes payments in March 2026. Apply the withholding tax rates in force under the Nigeria Tax Administration Act 2025 and the 2024 Withholding Tax Regulations. Coronet failed to deduct withholding tax at 10% on rent of N5,000,000 paid to a property company. What administrative penalty applies under section 105 of the NTAA 2025?","options":["N2,000,000","N200,000","N500,000","N50,000"],"correctOption":1,"section":"Withholding Tax","explanation":"The tax that should have been deducted is N5,000,000 x 10% = N500,000, and section 105 imposes a penalty of 40% of the amount not deducted, so 40% x N500,000 = N200,000, payable on top of the N500,000. Option D uses the old 10% penalty rate. Option A wrongly applies 40% to the rent itself, and option C is the tax, not the penalty."}},{"itemId":"d79b0211-91f9-5196-91ae-ed8eff6c8e6d","questionId":"c7c0268c-cfff-53f9-9456-7f17d5e4b7b8","sourceKey":"bank:TAX-CM223:WHT-001","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025 (NTAA), s.51, and the withholding regulations, Lekki Foods Ltd pays a dividend of N40,000,000 to its corporate shareholder, Orile Holdings Ltd. The WHT rate on dividends is 10%. How much WHT must Lekki Foods deduct?","options":["N2,000,000","N4,000,000","N36,000,000","N6,000,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT = gross dividend x rate = N40,000,000 x 10% = N4,000,000, deducted by the paying company before the dividend is paid. Option C is the net dividend the shareholder actually receives, not the tax, while A and D apply rates that are not the dividend rate."}},{"itemId":"b148501d-1294-5bf6-b75f-d03373b9aa23","questionId":"24b3f826-6a2c-5fd4-8a3d-80e0a0ddedd9","sourceKey":"bank:TAX-CM223:WHT-002","payload":{"prompt":"Ikeja Paints Plc declares a dividend of N18,000,000 to its individual shareholders. Under the NTAA 2025 and the withholding regulations, WHT on dividends is 10%. What net amount will the shareholders receive in total?","options":["N17,100,000","N18,000,000","N1,800,000","N16,200,000"],"correctOption":3,"section":"Withholding Tax","explanation":"Net dividend = gross - WHT = N18,000,000 - (10% x N18,000,000) = N18,000,000 - N1,800,000 = N16,200,000. Option C is only the tax deducted, B ignores the deduction altogether, and A wrongly uses 5%."}},{"itemId":"d70d6762-58d7-5e7a-bc9a-358e42e74dc3","questionId":"3d9fdd0e-35c1-5186-bdfc-491e1cfd69f1","sourceKey":"bank:TAX-CM223:WHT-003","payload":{"prompt":"Under the NTAA 2025 and the withholding regulations, rent paid to a resident company attracts WHT at 10%. Surulere Logistics Ltd pays annual warehouse rent of N6,500,000 to Ojota Properties Ltd. How much WHT should Surulere Logistics deduct?","options":["N975,000","N650,000","N325,000","N130,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT on rent = N6,500,000 x 10% = N650,000, and the tenant (the payer) deducts it when paying the rent. Options C and A use rates meant for other types of payment, such as professional fees and general services, so they understate the tax."}},{"itemId":"8d3989a5-9a79-5d9b-8dc8-b9d1a671e2e6","questionId":"6efe42dd-ab50-518b-a750-649ecfa6818e","sourceKey":"bank:TAX-CM223:WHT-004","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, professional fees paid to a resident company attract WHT at 5%. Marina Bank Plc pays legal fees of N9,000,000 to Adeyemi & Co Ltd, a resident company. How much WHT should the bank deduct?","options":["N450,000","N180,000","N900,000","N8,550,000"],"correctOption":0,"section":"Withholding Tax","explanation":"WHT = N9,000,000 x 5% = N450,000. Option C uses 10%, the higher rate that applies to non-resident recipients (and the rate many older examples used for residents), while D is the net fee paid after the deduction rather than the tax."}},{"itemId":"64dbba19-ca9a-56fa-afd6-844d89c57681","questionId":"eec3449e-9d81-562c-826d-4cb5f46dc1bd","sourceKey":"bank:TAX-CM223:WHT-005","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, consultancy and technical fees paid to a non-resident company attract WHT at 10%, which is the recipient's final tax. Apapa Refinery Ltd pays N20,000,000 to a German engineering firm for technical services. How much WHT should be deducted?","options":["N400,000","N3,000,000","N2,000,000","N1,000,000"],"correctOption":2,"section":"Withholding Tax","explanation":"WHT = N20,000,000 x 10% = N2,000,000, and for a non-resident company this deduction is the final Nigerian tax on that income. Option D applies the 5% resident rate, which is wrong because the higher rate exists precisely because the non-resident will not file a Nigerian return."}},{"itemId":"68c02adc-d2d9-5ce5-86ea-521dbbd239dc","questionId":"abd10ff5-2ee2-55ff-bfec-e18fecbdcbb1","sourceKey":"bank:TAX-CM223:WHT-006","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, supply of goods by a person other than the manufacturer or producer attracts WHT at 2%. Yaba Stores Ltd buys office furniture worth N15,000,000 from a resident trading company that did not make the furniture. How much WHT should Yaba Stores deduct?","options":["N300,000","N1,500,000","N750,000","N1,125,000"],"correctOption":0,"section":"Withholding Tax","explanation":"WHT = N15,000,000 x 2% = N300,000. The low 2% rate reflects the thin margins of traders. Option D wrongly applies the 7.5% VAT rate, and options C and B use rates for other payment types."}},{"itemId":"277f7386-40f5-5043-ac9c-ff8cd2414de6","questionId":"31603827-17c7-5c60-aeee-f5c7772b2da5","sourceKey":"bank:TAX-CM223:WHT-007","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, construction of roads, bridges, buildings and power plants by a resident company attracts WHT at 2%, while other construction and related activities attract 5%. Ogun State pays Ibadan Builders Ltd N50,000,000 for building a bridge. How much WHT is deductible?","options":["N5,000,000","N1,250,000","N1,000,000","N2,500,000"],"correctOption":2,"section":"Withholding Tax","explanation":"Bridge building falls in the reduced 2% class, so WHT = N50,000,000 x 2% = N1,000,000. Option D uses the 5% rate for 'any other form of construction', which does not apply to roads, bridges, buildings or power plants."}},{"itemId":"a9b38de0-29c8-5385-b836-0b05d4d3f259","questionId":"8cff5ed6-97e5-53bc-b1bc-e18409c6a746","sourceKey":"bank:TAX-CM223:WHT-008","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, 'any other form of construction and related activities' (outside roads, bridges, buildings and power plants) carried out by a resident company attracts WHT at 5%. Ikoyi Towers Ltd pays N12,000,000 to a resident company for installing lifts and fire-escape systems. How much WHT should be deducted?","options":["N600,000","N240,000","N1,200,000","N11,400,000"],"correctOption":0,"section":"Withholding Tax","explanation":"Lift and fire-escape installation is construction-related work outside the 2% class, so WHT = N12,000,000 x 5% = N600,000. Option B applies the 2% rate meant only for roads, bridges, buildings and power plants, and D is the net payment, not the tax."}},{"itemId":"1363f81f-e0bd-5815-855e-e69bae6c9810","questionId":"da6868d5-bf43-5956-bc71-ea635f1bab72","sourceKey":"bank:TAX-CM223:WHT-009","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, directors' fees paid to a resident individual attract WHT at 15%. Sango Cement Plc pays a resident non-executive director fees of N4,000,000 for the year. How much WHT should the company deduct?","options":["N200,000","N600,000","N800,000","N400,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT = N4,000,000 x 15% = N600,000; the 15% rate is set high to reflect the marginal personal income tax rate of directors. Option C uses the 20% rate that applies to non-resident directors."}},{"itemId":"f9530aad-43b1-598d-8a56-80d069e6b4d9","questionId":"789e2abf-9edb-5c5e-8a9f-901f234fe0cb","sourceKey":"bank:TAX-CM223:WHT-010","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, directors' fees paid to a non-resident individual attract WHT at 20%. Lagos Breweries Plc pays N5,000,000 in fees to a director who lives in the United Kingdom. How much WHT is deductible?","options":["N500,000","N4,000,000","N750,000","N1,000,000"],"correctOption":3,"section":"Withholding Tax","explanation":"WHT = N5,000,000 x 20% = N1,000,000. Option C uses the 15% resident-director rate, and B is the net fee remitted to the director, not the tax withheld."}},{"itemId":"4878fc3c-0dbe-5459-923c-c8e41416533c","questionId":"7b360dc1-dcfa-5afa-87ae-168db52e1a3f","sourceKey":"bank:TAX-CM223:WHT-011","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, royalties paid to a resident individual attract WHT at 5% (the rate for corporate recipients is 10%). A publishing company pays royalties of N3,000,000 to a Nigerian author. How much WHT should be deducted?","options":["N300,000","N60,000","N150,000","N450,000"],"correctOption":2,"section":"Withholding Tax","explanation":"For an individual recipient, WHT on royalties = N3,000,000 x 5% = N150,000. Option A applies the 10% rate that applies when the royalty is paid to a company."}},{"itemId":"2067f2b0-e6fb-5d29-8872-8757d6596fe5","questionId":"6c8a8f39-ec5d-57b0-b790-049fac1bb196","sourceKey":"bank:TAX-CM223:WHT-012","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, commission paid to a resident company attracts WHT at 5%. An insurance company pays sales commission of N2,400,000 to Broad Street Agencies Ltd. How much WHT should be deducted?","options":["N180,000","N120,000","N48,000","N240,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT = N2,400,000 x 5% = N120,000, since commission sits in the same 5% class as consultancy and professional fees for residents. Option D uses the non-resident rate, and A confuses WHT with the 7.5% VAT rate."}},{"itemId":"895fa5f8-37b6-5af3-a958-8f71798250d7","questionId":"b90cee48-7052-5c3a-bcb7-323ccca47a61","sourceKey":"bank:TAX-CM223:WHT-013","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, professional fees paid to a resident attract WHT at 5%. Okafor Chambers, a resident partnership, invoices a client N7,200,000 (ignore VAT). How much cash will Okafor Chambers actually receive from the client?","options":["N6,480,000","N7,200,000","N360,000","N6,840,000"],"correctOption":3,"section":"Withholding Tax","explanation":"Cash received = fee - WHT = N7,200,000 - (5% x N7,200,000) = N7,200,000 - N360,000 = N6,840,000. Option A deducts 10% instead of 5%, C is just the WHT, and B ignores the deduction."}},{"itemId":"b24b13d1-523c-5580-a9dc-9258daa8c56f","questionId":"00150c6c-7002-559a-8ae4-9c3cb815396e","sourceKey":"bank:TAX-CM223:WHT-014","payload":{"prompt":"A resident consultancy firm received a net payment of N9,500,000 after its client deducted WHT at 5% on its fee under the withholding regulations applied by the NTAA 2025. What was the gross fee before WHT?","options":["N10,450,000","N9,025,000","N9,975,000","N10,000,000"],"correctOption":3,"section":"Withholding Tax","explanation":"Gross = net / (1 - rate) = N9,500,000 / 0.95 = N10,000,000. Option C simply adds 5% to the net amount, which gives the wrong base because the 5% was taken from the gross figure, not from the net."}},{"itemId":"7a815115-6f8f-5746-92ee-ae897186c0b4","questionId":"a0fad6d6-c2a4-5325-bb87-fdce5116716a","sourceKey":"bank:TAX-CM223:WHT-015","payload":{"prompt":"Under the NTAA 2025, s.105, a person who fails to deduct tax is liable to an administrative penalty of 40% of the amount not deducted. Oshodi Motors Ltd paid rent of N7,000,000 to a property company without deducting WHT at 10%. What is the administrative penalty?","options":["N70,000","N280,000","N980,000","N2,800,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT not deducted = N7,000,000 x 10% = N700,000; penalty = 40% x N700,000 = N280,000. Option D wrongly applies 40% to the gross rent, and C adds the WHT itself to the penalty, which answers a different question (total liability)."}},{"itemId":"c597a64a-4672-5ba0-8dc3-080ee49071b1","questionId":"80416564-8864-52fc-97f6-cde62e0ba516","sourceKey":"bank:TAX-CM223:WHT-016","payload":{"prompt":"Under the NTAA 2025, s.105, failure to deduct tax attracts an administrative penalty of 40% of the amount not deducted, and the tax itself remains payable. Ajah Telecoms Ltd paid professional fees of N12,000,000 to a resident company without deducting WHT at 5%. What is the total of the WHT and the penalty now due (ignore interest)?","options":["N240,000","N1,680,000","N5,400,000","N840,000"],"correctOption":3,"section":"Withholding Tax","explanation":"WHT = N12,000,000 x 5% = N600,000; penalty = 40% x N600,000 = N240,000; total = N840,000. Option B uses a 10% WHT rate, A is the penalty alone, and C applies the 40% to the gross fee."}},{"itemId":"9ba49220-ec4a-5f33-ba2f-421ebcc90774","questionId":"95e26108-bedb-5c53-acf2-3b08b0f6b0e2","sourceKey":"bank:TAX-CM223:WHT-017","payload":{"prompt":"Under the NTAA 2025, s.107(1), deducted tax not remitted by the due date attracts an administrative penalty of 10% per annum. Badagry Farms Ltd deducted WHT of N3,650,000 and remitted it 60 days late. Time-apportion the penalty on a days/365 basis. What is the penalty (excluding interest)?","options":["N30,000","N1,460,000","N365,000","N60,000"],"correctOption":3,"section":"Withholding Tax","explanation":"Penalty = N3,650,000 x 10% x 60/365 = N60,000. Option C treats the 10% as a flat one-off charge instead of a per annum rate, and B uses the 40% rate that applies to failure to deduct, not failure to remit."}},{"itemId":"2d16b8f1-a6e1-5819-bb06-9ed4cc638907","questionId":"fae8e02a-0f75-5059-a832-6463dda96a26","sourceKey":"bank:TAX-CM223:WHT-018","payload":{"prompt":"Under the NTAA 2025, s.107(1), interest at the prevailing CBN Monetary Policy Rate (MPR) is charged on deducted tax not remitted on time. Mushin Plastics Ltd remitted WHT of N2,000,000 73 days late when the MPR was 27% per annum. Using simple interest on a days/365 basis, what is the interest?","options":["N540,000","N40,000","N108,000","N148,000"],"correctOption":2,"section":"Withholding Tax","explanation":"Interest = N2,000,000 x 27% x 73/365 = N108,000. Option A charges a full year of interest, B uses the 10% penalty rate instead of the MPR, and D adds the penalty and interest together."}},{"itemId":"8d9a4d38-1e2f-50bb-8f4f-e905d6554c49","questionId":"2550975c-8040-5000-8b5c-b16176f3dfba","sourceKey":"bank:TAX-CM223:WHT-020","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, Victoria Island Media Ltd made these payments to resident companies in April: office rent N4,000,000 (WHT 10%), legal fees N6,000,000 (WHT 5%), and stationery bought from a trading company (not the manufacturer) N10,000,000 (WHT 2%). What total WHT must it remit for April?","options":["N900,000","N1,000,000","N700,000","N1,200,000"],"correctOption":0,"section":"Withholding Tax","explanation":"Total = (N4,000,000 x 10%) + (N6,000,000 x 5%) + (N10,000,000 x 2%) = N400,000 + N300,000 + N200,000 = N900,000. Option D uses 10% on the legal fees, B wrongly applies a single 5% rate to every payment, and C uses 5% instead of 10% on the rent."}},{"itemId":"2d0437a1-db0d-5d03-a949-74b867115b3e","questionId":"12fab442-4cfa-551e-8d85-0bdba859fc2c","sourceKey":"bank:TAX-CM223:WHT-021","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, fees paid to non-resident entertainers and sportspersons for performances in Nigeria attract WHT at 15%. A Lagos concert promoter pays a Ghanaian musician N8,000,000. How much WHT should be deducted?","options":["N1,200,000","N1,600,000","N800,000","N400,000"],"correctOption":0,"section":"Withholding Tax","explanation":"WHT = N8,000,000 x 15% = N1,200,000 on amounts earned in Nigeria by a non-resident entertainer. Option C uses the general 10% non-resident rate for fees, and B uses the non-resident directors' rate."}},{"itemId":"70d00d56-e7f2-5743-9e99-242305d73683","questionId":"afc2c84a-aef4-59c0-a1f3-a3e9cb514000","sourceKey":"bank:TAX-CM223:WHT-022","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, compensation for loss of employment paid to an individual attracts WHT at 10%. Oyo Textiles Ltd pays a resident former manager compensation of N6,000,000. How much WHT should be deducted?","options":["N300,000","N900,000","N600,000","N5,400,000"],"correctOption":2,"section":"Withholding Tax","explanation":"WHT = N6,000,000 x 10% = N600,000. Option D is the net amount paid to the former employee, and B wrongly uses the resident directors' fee rate."}},{"itemId":"7c6a9618-70d2-5caa-95d8-49176d00454b","questionId":"1decba90-16bb-54a7-9feb-92c9adae5d0a","sourceKey":"bank:TAX-CM223:WHT-023","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, winnings from lottery, gaming and reality shows paid to a resident individual attract WHT at 5%. A resident individual wins N2,000,000 in a licensed reality show. How much WHT should the organiser deduct?","options":["N300,000","N200,000","N100,000","N40,000"],"correctOption":2,"section":"Withholding Tax","explanation":"WHT = N2,000,000 x 5% = N100,000 for a resident winner. Option A applies the 15% rate that applies to a non-resident winner."}},{"itemId":"1308a72c-f3a3-53dd-9500-c527df3be98a","questionId":"d3fb88c6-0ef8-56db-981c-b691b889fbce","sourceKey":"bank:TAX-CM223:WHT-024","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, co-location and telecommunication tower services attract WHT at 2% for resident recipients and 5% for non-resident recipients. A mobile network pays a resident tower company N25,000,000 for co-location. How much WHT should be deducted?","options":["N1,875,000","N500,000","N2,500,000","N1,250,000"],"correctOption":1,"section":"Withholding Tax","explanation":"WHT = N25,000,000 x 2% = N500,000, the reduced rate reflecting low industry margins. Option D applies the non-resident rate, and A confuses WHT with VAT."}},{"itemId":"1405da32-5029-58e7-af45-010b62f67a92","questionId":"78334376-b42b-5e6a-a9f1-f74990b08846","sourceKey":"bank:TAX-CM223:WHT-025","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, professional fees paid to a resident attract WHT at 5%, but where the recipient has no Tax Identification Number (TIN) the prescribed rate is doubled (capped at 20%). A client pays N8,000,000 in professional fees to a resident consultant who has no TIN. How much WHT should be deducted?","options":["N1,200,000","N1,600,000","N400,000","N800,000"],"correctOption":3,"section":"Withholding Tax","explanation":"With no TIN the 5% rate doubles to 10%, so WHT = N8,000,000 x 10% = N800,000. Option C ignores the no-TIN rule, while B jumps straight to the 20% cap, which only limits the doubled rate and is not itself the rate here."}},{"itemId":"de9d1897-dc95-59b1-b9a2-4769895fb283","questionId":"ea5ad1c2-2028-515d-bb59-18b039297ff0","sourceKey":"bank:TAX-CM223:WHT-026","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, 'supply or rendering of services other than those specifically listed' attracts WHT at 2% for residents, and the rate is doubled where the supplier has no TIN. A company pays a resident cleaning contractor without a TIN N5,000,000. How much WHT should be deducted?","options":["N200,000","N1,000,000","N100,000","N500,000"],"correctOption":0,"section":"Withholding Tax","explanation":"The 2% general-services rate doubles to 4% for a supplier without a TIN: WHT = N5,000,000 x 4% = N200,000. Option C ignores the doubling, and B wrongly treats the 20% ceiling as the applicable rate."}},{"itemId":"35f2a921-094e-50a5-acf6-2898875e49c7","questionId":"9ff32b7d-de79-509e-8254-b44195e9f175","sourceKey":"bank:TAX-CM223:WHT-027","payload":{"prompt":"WHT deducted under the NTAA 2025, s.51, is an advance payment of the recipient's income tax, so it can be credited against the final liability. Agege Consulting Ltd's company income tax for the year is N9,000,000, and it holds valid WHT credit evidence of N2,500,000 for tax deducted by its clients. How much company income tax remains payable?","options":["N6,500,000","N9,000,000","N2,500,000","N11,500,000"],"correctOption":0,"section":"Withholding Tax","explanation":"Tax payable = final liability - WHT credits = N9,000,000 - N2,500,000 = N6,500,000. Option B ignores the credit, which would make the company pay the same tax twice, and C adds the credit instead of subtracting it."}},{"itemId":"e811ed23-6e39-5b52-9507-8195a65511e9","questionId":"50bdb8ed-6663-57bf-b86f-4c8db84a5d59","sourceKey":"bank:TAX-CM223:WHT-028","payload":{"prompt":"Under the NTAA 2025, s.107(1), tax deducted at source must be remitted by the 21st day of the month immediately following the month of deduction. Ikorodu Steel Ltd deducted WHT in May 2026 and remitted it on 30 July 2026. Counting from the due date to the remittance date (excluding the due date), how many days late was the remittance?","options":["60 days","69 days","30 days","39 days"],"correctOption":3,"section":"Withholding Tax","explanation":"The May deduction was due by 21 June 2026, and 21 June to 30 July is 9 days in June plus 30 in July, which is 39 days. Option A counts from the end of May, and option B counts from 1 June instead of from the 21 June due date."}},{"itemId":"5064d76d-4078-5bc3-90b3-1b414867ef49","questionId":"24f15cca-46e2-59a8-a958-aa6ccdd12e07","sourceKey":"bank:TAX-CM223:WHT-029","payload":{"prompt":"Under the NTAA 2025, s.107(1), WHT deducted must be remitted by the 21st day of the month immediately following the month of deduction. Kano Agro Ltd deducted WHT on payments made on 3 March 2026 and 28 March 2026. By what date must both deductions be remitted?","options":["21 April 2026","24 March 2026 and 18 April 2026 respectively","31 March 2026","21 March 2026"],"correctOption":0,"section":"Withholding Tax","explanation":"All deductions made in a month share one deadline, the 21st of the next month, so both March deductions are due by 21 April 2026. Option B uses the old practice of counting 21 days from each payment date, which the NTAA replaced with a single monthly date."}},{"itemId":"41a1b3fb-01f2-5402-bf83-0067d30d915a","questionId":"3ffa7a95-de25-5f97-8948-f4a4492308be","sourceKey":"bank:TAX-CM223:WHT-030","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, a resident company paying a resident professional firm deducts WHT at 5%. Ebute Metta Shipping Ltd pays a resident audit firm a fee of N4,000,000 and then fails to remit the deducted WHT for 146 days. The NTAA s.107(1) penalty is 10% per annum and interest is at the CBN MPR of 25% per annum, both time-apportioned on a days/365 basis. What is the total of penalty and interest (excluding the tax itself)?","options":["N28,000","N560,000","N70,000","N56,000"],"correctOption":0,"section":"Withholding Tax","explanation":"WHT = N4,000,000 x 5% = N200,000; penalty plus interest = N200,000 x (10% + 25%) x 146/365 = N28,000. Option C charges a full year, option D starts from a 10% WHT rate, and option B applies the rates to the gross fee instead of the tax."}},{"itemId":"6aa7da98-cda4-53f7-997b-61bace499d16","questionId":"7acbc6b2-c2e8-5acf-ba17-e90932923c4d","sourceKey":"bank:TAX-CM223:WHT-031","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025 (NTAA), which description best fits withholding tax?","options":["A separate tax charged on the payer's own profits at the time of payment","A consumption tax added to the price of every taxable supply","An advance payment of the recipient's income tax, deducted by the payer when a payment is made","A duty charged on written instruments that transfer property"],"correctOption":2,"section":"Withholding Tax","explanation":"Withholding tax is not a standalone tax: it is part of the payee's eventual income tax collected early by the payer. Option A wrongly makes the payer the taxpayer, B describes VAT, and D describes stamp duty."}},{"itemId":"f0b0f9e3-2f0c-5e0c-b119-01a2162942c3","questionId":"67c9b296-8c42-5484-bd22-bac9542dff12","sourceKey":"bank:TAX-CM223:WHT-032","payload":{"prompt":"Under the NTAA 2025, s.51, the 'withholding agent' in withholding tax is the:","options":["Tax Appeal Tribunal that settles disputes","Recipient, who pays the tax when filing returns","Bank through which the payment passes","Payer, who deducts the tax from the payment and remits it"],"correctOption":3,"section":"Withholding Tax","explanation":"The payer (for example, the company paying rent or fees) is the agent who deducts the tax at the date of payment or settlement and remits it to the tax authority. Option B describes the person who suffers the deduction, not the agent."}},{"itemId":"20166ae9-c164-5dcd-a89c-59ae06104330","questionId":"b0867f34-5b61-5d41-bbbc-ae768c30003a","sourceKey":"bank:TAX-CM223:WHT-033","payload":{"prompt":"Which section of the Nigeria Tax Administration Act 2025 is the core provision on deduction of tax at source (withholding tax)?","options":["Section 22","Section 105","Section 51","Section 81"],"correctOption":2,"section":"Withholding Tax","explanation":"Section 51 requires a person making a payment to deduct tax at the rate prescribed in the withholding regulations. Option D is the VAT revenue-distribution section, B is the penalty for failure to deduct, and A deals with VAT returns."}},{"itemId":"cb101ea5-8a5b-57f2-be25-f8ba4e35a4f2","questionId":"1623832d-6e66-5b7c-bb4f-d380a6ba2649","sourceKey":"bank:TAX-CM223:WHT-034","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025 (NTAA) framework, where are the specific withholding tax rates (for example, 10% on rent) found?","options":["In a table inside the NTAA 2025 penalty provisions","In regulations on deduction of tax at source, to which NTAA 2025 s.51 refers","In the First Schedule to the Nigeria Tax Act 2025","In the Ninth Schedule to the Nigeria Tax Act 2025"],"correctOption":1,"section":"Withholding Tax","explanation":"Section 51 of the NTAA says tax is deducted 'at the rate prescribed in regulations', so the rate tables live in subsidiary legislation, currently the 2024 withholding regulations. Option D is the stamp duty rate schedule, and C deals with capital allowances."}},{"itemId":"00c13c3b-cf76-536b-b705-84e64127d8ba","questionId":"04ae8f30-dc75-5823-9c9e-4eda9cbc5d74","sourceKey":"bank:TAX-CM223:WHT-035","payload":{"prompt":"Under the NTAA 2025, s.107(1), by when must tax deducted at source be remitted?","options":["By the 14th day of the month following the end of the quarter","Within 21 days of each payment","Within 30 days of the end of the accounting year","By the 21st day of the month immediately following the month of deduction"],"correctOption":3,"section":"Withholding Tax","explanation":"Section 107(1) sets one monthly deadline: the 21st day of the month after the deduction. Option B is the older practice of counting 21 days from each payment, which the new Act replaced with a fixed date."}},{"itemId":"37649682-b7de-5bdb-8695-95c50954d3f1","questionId":"f3f25c95-1b11-580c-8efe-ff170ba6d904","sourceKey":"bank:TAX-CM223:WHT-036","payload":{"prompt":"Under the NTAA 2025, s.105, what is the administrative penalty for failing to deduct or withhold tax?","options":["A fixed N1,000,000","40% of the amount not deducted","10% of the amount not deducted","40% of the gross payment made"],"correctOption":1,"section":"Withholding Tax","explanation":"Section 105 imposes an administrative penalty of 40% of the tax that should have been deducted. Option C was the old CITA-era rate, and D wrongly applies the 40% to the whole payment instead of to the tax."}},{"itemId":"94a5a8e9-9962-57e0-a7ae-8656917e2961","questionId":"d8dcde5b-fe20-5a3a-9bd8-cc1e8d73385f","sourceKey":"bank:TAX-CM223:WHT-038","payload":{"prompt":"A company paid a supplier without deducting WHT, while another company deducted WHT but kept the money for three months. Under the NTAA 2025, which statement correctly matches each failure to its penalty?","options":["Failure to deduct: 10% per annum (s.107); failure to remit: 40% of the tax (s.105)","Failure to deduct: 40% of the amount not deducted (s.105); failure to remit: 10% per annum plus CBN MPR interest (s.107)","Both failures: 10% per annum plus MPR interest (s.107)","Both failures: 40% of the tax plus MPR interest (s.105)"],"correctOption":1,"section":"Withholding Tax","explanation":"The NTAA treats the two failures separately: not deducting attracts 40% of the undeducted tax under s.105, while deducting but not remitting attracts 10% per annum plus interest at the MPR under s.107. Option A swaps the two, and options D and C wrongly use one rule for both."}},{"itemId":"36a45586-f6d4-50b3-8edc-613acb668b59","questionId":"6fde40c2-342b-57ae-a666-ac60e4edc528","sourceKey":"bank:TAX-CM223:WHT-039","payload":{"prompt":"Under the NTAA 2025, s.107(3), on conviction for failure to remit tax deducted, an offender is liable to:","options":["Imprisonment of up to ten years and forfeiture of business assets","Imprisonment of up to three years, a fine of not less than the principal plus up to 50% of it, or both","Imprisonment of up to six months only","A fine equal to 10% of the tax with no imprisonment"],"correctOption":1,"section":"Withholding Tax","explanation":"Beyond the administrative penalty, s.107(3) creates a criminal sanction of up to three years' imprisonment and a fine of not less than the principal amount plus a penalty of up to 50% of it. The other options state terms that are not in the provision."}},{"itemId":"8451c646-8b40-5661-86fd-5866989eaa2a","questionId":"85ad770f-1a6d-53f7-a503-b563c8b32d7d","sourceKey":"bank:TAX-CM223:WHT-041","payload":{"prompt":"Under the NTAA 2025, s.41, Bodija Traders Ltd objected to a WHT assessment, but the tax authority sent no response within 90 days. What is the legal effect?","options":["The objection lapses and must be refiled","The matter goes automatically to the Supreme Court","The assessment becomes final and conclusive","The taxpayer's objection is treated as upheld"],"correctOption":3,"section":"Withholding Tax","explanation":"Section 41 requires the authority to respond within 90 days, 'otherwise the objection of the taxpayer shall be upheld'. Option C reverses the rule by favouring the authority's silence, and the appeal route in B starts at the Tax Appeal Tribunal, not the Supreme Court."}},{"itemId":"5fb834d1-070a-54ee-a21f-03d0950fa319","questionId":"ab8eeb2f-ff34-5f68-b526-39971c7c70c3","sourceKey":"bank:TAX-CM223:WHT-042","payload":{"prompt":"Under the NTAA 2025 and the withholding regulations, for a non-resident company that earns professional, consultancy or management fees from Nigeria, WHT deducted under the 2025 framework is best described as:","options":["A refundable deposit returned on request","An advance tax to be offset in a Nigerian CIT return","A final tax on that income","A deduction that only applies if the company registers in Nigeria"],"correctOption":2,"section":"Withholding Tax","explanation":"For non-residents, WHT on such fees earned from Nigeria is the final tax, which is why the non-resident rate (10%) is higher than the resident rate (5%). Option B describes how WHT works for a resident company, which files a return and claims credit."}},{"itemId":"73db589b-1806-53c6-b568-330f34f051a8","questionId":"de74f278-3c91-55fb-b189-ce7c9ebd9e0d","sourceKey":"bank:TAX-CM223:WHT-043","payload":{"prompt":"A Nigerian company receives a dividend from another Nigerian company after 10% WHT has been deducted. Under the NTAA 2025, this dividend is called 'franked investment income'. What does that mean?","options":["It is not subject to further income tax in the hands of the receiving company","It is exempt from WHT at the time of payment","It is taxed again at 30% in the receiving company","It must be grossed up and taxed at the development levy rate"],"correctOption":0,"section":"Withholding Tax","explanation":"Franked investment income is a dividend that has already borne WHT, so it is not charged to further income tax in the recipient company. Option B is wrong because WHT is in fact deducted when the dividend is paid; that deduction is what 'franks' it."}},{"itemId":"134ba5ae-ab70-5913-8ac8-8ae9c50c0a88","questionId":"01ff0886-1ce4-58d0-8140-16721ce68be5","sourceKey":"bank:TAX-CM223:WHT-044","payload":{"prompt":"Under the NTAA 2025, s.51, at what point must the payer deduct WHT?","options":["When the recipient files its annual return","Only when the tax authority issues a demand notice","At the date of payment or settlement of the amount","At the end of the payer's financial year"],"correctOption":2,"section":"Withholding Tax","explanation":"Section 51 of the NTAA requires deduction at the time the amount is paid or settled, and the withholding regulations treat the earlier of payment or settlement as the trigger. Options A and D would delay collection, which defeats the purpose of deduction at the point of payment."}},{"itemId":"21885410-321f-5fdf-bbab-0983c8b0ade2","questionId":"bc4bc709-06ad-5f6b-bbcd-4bc8ee41b04c","sourceKey":"bank:TAX-CM223:WHT-045","payload":{"prompt":"Which of the following is NOT a feature of withholding tax under the NTAA 2025 framework?","options":["The rates are set in regulations rather than in the Acts","It is a final tax for resident companies on all their income","The payer acts as agent for the tax authority","It is credited against the resident recipient's final income tax"],"correctOption":1,"section":"Withholding Tax","explanation":"For a resident company, WHT is only an advance payment that is credited against its final income tax, so it is not a final tax for them. Options C, D and A are all genuine features of the system."}},{"itemId":"191d52d4-e820-587a-9763-e42a5cedef0e","questionId":"941c9bc3-c909-5fe7-8d4b-87fb0ac67c6a","sourceKey":"bank:TAX-CM223:WHT-046","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, which payment to a RESIDENT INDIVIDUAL attracts the highest WHT rate?","options":["Rent","Dividends","Professional fees","Directors' fees"],"correctOption":3,"section":"Withholding Tax","explanation":"Directors' fees paid to a resident individual attract 15%, the highest of the four. Dividends and rent (B, A) attract 10%, and professional fees (C) attract 5%."}},{"itemId":"3f7ba918-ae84-52f8-a309-305d5c1e35e1","questionId":"28425a8d-2624-56d0-8238-148121186336","sourceKey":"bank:TAX-CM223:WHT-047","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, supply of goods 'other than by the manufacturer or producer' attracts WHT at 2%. Ijebu Bottling Ltd buys glass bottles directly from the factory that makes them. What WHT applies to the purchase price?","options":["10%, because the buyer is a company","2%, as on any supply of goods","5%, as a contract of supply","No WHT, because the goods are bought directly from the manufacturer"],"correctOption":3,"section":"Withholding Tax","explanation":"The 2% class covers only goods supplied by someone other than the manufacturer or producer, such as traders. A purchase straight from the factory falls outside it, so option B overlooks the key qualification in the rule."}},{"itemId":"7bdcdbe0-f227-5a9a-9e63-f2d734e0fafa","questionId":"63640e45-1cbf-5a94-a318-295afd3c63d7","sourceKey":"bank:TAX-CM223:WHT-048","payload":{"prompt":"Under the 2024 withholding regulations applied with the NTAA 2025, Ketu Bakery Ltd, a small company, buys flour worth N1,500,000 in a month from a trader who has a valid TIN. Its total purchases from that trader that month are below N2,000,000. What is Ketu Bakery's WHT obligation on this purchase?","options":["No obligation to deduct WHT","Deduct 5% because the supplier is a trader","Deduct 2% and remit by the 21st of the next month","Deduct 4% because the buyer is a small company"],"correctOption":0,"section":"Withholding Tax","explanation":"The regulations relieve a small company from deducting WHT where its transactions with a supplier do not exceed N2,000,000 in a month and the supplier has a valid TIN. Option C applies the normal 2% supply-of-goods rule, which this relief displaces."}},{"itemId":"1ee7376c-b628-5628-b22c-5f5d2267562c","questionId":"74d4ef55-8d3a-5e4c-b92b-13a5fb9bf629","sourceKey":"bank:TAX-CM223:WHT-049","payload":{"prompt":"Under the NTAA 2025, to which authority should a company remit WHT deducted from rent paid to another COMPANY?","options":["The Nigeria Revenue Service (NRS)","The State Internal Revenue Service of the landlord's state","The Nigeria Customs Service","The Joint Revenue Board"],"correctOption":0,"section":"Withholding Tax","explanation":"The NRS, which replaced FIRS, administers WHT where the recipient is a company or a non-resident. WHT deducted from individuals goes to the relevant State IRS (option B), and the JRB (D) coordinates rather than collects."}},{"itemId":"4c5cda2a-3f41-51de-a8b6-d164af65aa4a","questionId":"e17c09f3-caa5-53dc-9f3d-f2c10c16590f","sourceKey":"bank:TAX-CM223:WHT-050","payload":{"prompt":"Compared with the old CITA regime, how did the NTAA 2025 change the penalty for failure to deduct WHT?","options":["It was replaced by a fixed fine of N50,000","It fell from 40% to 10% of the amount not deducted","It rose from 10% to 40% of the amount not deducted","It stayed at 10% but interest was removed"],"correctOption":2,"section":"Withholding Tax","explanation":"The old CITA penalty for failure to deduct was 10% of the amount not deducted; NTAA s.105 raised it to 40%, a much stronger deterrent. Option B reverses the direction of the change."}},{"itemId":"ee168e00-a150-505d-9308-73099899c413","questionId":"91972385-d720-5e56-bc0e-ca84d4703843","sourceKey":"bank:TAX-CM223:WHT-051","payload":{"prompt":"Under the NTAA 2025, interest on late remittance of deducted tax is charged at:","options":["A fixed 21% per annum","The prevailing CBN Monetary Policy Rate","The commercial bank prime lending rate","A fixed 10% per annum, as under the old CITA"],"correctOption":1,"section":"Withholding Tax","explanation":"The NTAA links interest to the prevailing CBN Monetary Policy Rate, so it moves with monetary policy. Option D is the fixed rate used under the repealed law, which is a common mix-up."}},{"itemId":"3adb4fba-ce57-56e2-9933-8f4084bc70e5","questionId":"dbcf1249-b95b-59e5-8730-303e7a3ee6fb","sourceKey":"bank:TAX-CM223:WHT-052","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, why is the WHT rate on consultancy fees higher for a non-resident company (10%) than for a resident company (5%)?","options":["Because for the non-resident the deduction is its final Nigerian tax","Because residents receive a 50% statutory discount","Because the rate includes VAT on imported services","Because non-residents are charged a penalty for not registering"],"correctOption":0,"section":"Withholding Tax","explanation":"The higher non-resident rate exists because the deduction is the final tax for a non-resident that does not file a Nigerian return. Option C confuses WHT with VAT, and the other options describe rules that do not exist."}},{"itemId":"e106c7f6-4e5f-51c2-8dbf-ec854e95d089","questionId":"80f9c902-decb-5a26-8b0d-2e1f2b0c6643","sourceKey":"bank:TAX-CM223:WHT-053","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, what happens to the WHT rate where a supplier (other than for passive income such as dividends) does not have a Tax Identification Number?","options":["The prescribed rate is doubled, subject to a maximum of 20%","A flat rate of 40% applies","The rate is halved to encourage registration","WHT is not deducted until the supplier registers"],"correctOption":0,"section":"Withholding Tax","explanation":"Suppliers without a TIN suffer twice the prescribed rate, capped at 20%, which pushes businesses to register. Option B confuses this with the 40% penalty for failure to deduct."}},{"itemId":"d8ea3b10-9a94-5560-bad7-88a505994826","questionId":"215c6092-5228-5f9c-9470-1422d34d12b0","sourceKey":"bank:TAX-CM223:WHT-054","payload":{"prompt":"Under the NTAA 2025, s.51, Bariga Consulting Ltd suffered WHT of N1,200,000 on fees from several clients during the year. How does this WHT affect Bariga's own company income tax?","options":["Bariga can deduct the WHT as an expense in arriving at profit","Bariga must pay the N1,200,000 again with its CIT","Bariga can use the WHT, supported by credit evidence, to reduce its final CIT payable","The WHT is lost because it was paid by the clients"],"correctOption":2,"section":"Withholding Tax","explanation":"Because WHT is an advance payment of the recipient's income tax, Bariga sets the amount off against its CIT liability. Option B would tax the same income twice, and A treats a tax credit as a business expense, which it is not."}},{"itemId":"58c7ba59-ead0-56a5-89b3-556c71d39928","questionId":"aade04ac-461f-50e4-95ef-746ce6c39103","sourceKey":"bank:TAX-CM223:WHT-055","payload":{"prompt":"Under the withholding regulations applied by the NTAA 2025, which of these payments to a RESIDENT company does NOT attract WHT at 10%?","options":["Interest","Management fees","Dividends","Rent"],"correctOption":1,"section":"Withholding Tax","explanation":"Management fees fall in the commission, consultancy, technical, management and professional fees class, which is 5% for residents. Dividends, interest and rent (options C, A, D) all attract 10%."}},{"itemId":"31f37909-867b-5360-8151-bd2d879d9362","questionId":"4676f6f3-493c-56b7-8e5a-103cb6df9d31","sourceKey":"bank:TAX-CM223:PQ-004-a","payload":{"prompt":"Under the Nigeria Tax Act 2025, what is the main difference between an exempt supply (s.185) and a zero-rated supply (s.186)?","options":["Neither carries output VAT, but input VAT on a zero-rated supply is recoverable while input VAT on an exempt supply is not","Zero-rated supplies are charged at 7.5% and refunded later","Exempt supplies allow input VAT recovery while zero-rated supplies do not","There is no practical difference; both terms mean the supply is outside VAT"],"correctOption":0,"section":"Value Added Tax","explanation":"Both exempt and zero-rated supplies leave the customer paying no VAT, but only a zero-rated supplier can recover the input VAT on its purchases; for an exempt supplier, input VAT becomes a cost. Option C reverses the rule. Option D misses this input VAT difference, which is exactly why the distinction matters."}},{"itemId":"73c77252-9cfa-5e15-a24a-94a1f507fa5b","questionId":"9c9229d6-1bc6-5e2e-899f-bbef9870363c","sourceKey":"bank:TAX-CM223:PQ-004-b","payload":{"prompt":"A Nigerian software company sells its services only to clients abroad. Under the Nigeria Tax Act 2025, exported services are zero-rated. What is the commercial effect for the company?","options":["It cannot recover any input VAT, so VAT becomes a cost of the business","It must charge its foreign clients 7.5% VAT and claim a refund later","It is automatically exempt from company income tax on its export profits","It charges 0% VAT to its foreign clients and can still recover the input VAT it pays on its own purchases"],"correctOption":3,"section":"Value Added Tax","explanation":"Zero-rating means the export is taxed at 0%, so the foreign client pays no Nigerian VAT, while the company can claim back the input VAT on things like equipment and services, keeping its prices competitive. Option A describes an exempt supplier, not a zero-rated one. Option C is wrong because VAT zero-rating does not affect company income tax."}},{"itemId":"8c16898c-7fca-5be4-9178-bdee4c06828b","questionId":"bdc51390-1fc4-5d18-bf00-a4a340a3809e","sourceKey":"bank:TAX-CM223:PQ-004-c","payload":{"prompt":"Under the Nigeria Tax Act 2025, which of the following is an exempt supply rather than a zero-rated supply?","options":["Exported services","Land and buildings","Educational books","Basic food items"],"correctOption":1,"section":"Value Added Tax","explanation":"Land and buildings are listed among exempt supplies, so no VAT is charged and the supplier cannot recover related input VAT. Options A, D and C are all zero-rated under the 2025 Act, which means 0% VAT with input VAT still recoverable."}},{"itemId":"5a1828eb-5ddf-578f-9bba-cc31e29121d3","questionId":"deb7a995-b5c6-5a4e-bd51-f8902789a441","sourceKey":"bank:TAX-CM223:PQ-005-a","payload":{"prompt":"Under section 81(1) of the Nigeria Tax Administration Act 2025, how is net VAT revenue shared among the tiers of government?","options":["85% Federal Government, 15% States and FCT, 0% Local Governments","15% Federal Government, 50% States and FCT, 35% Local Governments","10% Federal Government, 55% States and FCT, 35% Local Governments","50% Federal Government, 30% States and FCT, 20% Local Governments"],"correctOption":2,"section":"Value Added Tax","explanation":"Section 81(1) NTAA 2025 gives 10% to the Federal Government, 55% to the States and FCT and 35% to Local Governments, shifting more VAT to sub-national governments. Option B was the sharing ratio under the repealed VAT Act. Options D and A are not the statutory ratio."}},{"itemId":"b1912926-900d-5c1c-a05d-7debbc0a4818","questionId":"59c45add-9508-5469-b697-1939083e4bf3","sourceKey":"bank:TAX-CM223:PQ-005-b","payload":{"prompt":"Under section 81(2) of the Nigeria Tax Administration Act 2025, on what basis is the VAT share of States and Local Governments distributed among them?","options":["100% by the place where VAT returns are filed","50% by population, 30% equally and 20% by derivation of returns filed","50% equally, 20% by population and 30% by consumption","Equally among all States and Local Governments"],"correctOption":2,"section":"Value Added Tax","explanation":"The sub-national share is split 50% equally, 20% by population and 30% by consumption, so states where goods and services are actually consumed get a bigger share. Option B reshuffles the figures and wrongly uses where returns are filed. Option A ignores the equality and population parts, and option D ignores population and consumption."}},{"itemId":"5e7a1307-7aa2-56ce-b955-fb07d6465a6f","questionId":"ba5dbe7d-eee1-5556-b3fe-bc7e549c6b61","sourceKey":"bank:TAX-CM223:PQ-005-d","payload":{"prompt":"Under section 81(3) of the Nigeria Tax Administration Act 2025, how is 'consumption' determined for the 30% consumption part of VAT distribution?","options":["By each state's share of the national population","By the number of VAT-registered businesses in each state","By the state where the supplier's head office files its VAT returns","By the place where the goods or services are consumed, irrespective of where the VAT return is filed"],"correctOption":3,"section":"Value Added Tax","explanation":"Consumption is measured by where the goods or services are actually consumed, not where the return is filed, so a company with a Lagos head office cannot pull all the consumption share into Lagos. Option C is exactly what the provision rules out. Option A is the separate population factor, and option B is not a factor."}},{"itemId":"0428e790-9921-5c47-b28b-12944ebf174d","questionId":"87df1c82-4693-51a9-ba37-e56ddafeee84","sourceKey":"bank:TAX-CM223:PQ-009-a","payload":{"prompt":"Radiance Health Ltd, a VAT-registered company, has these transactions for a month in 2026 under the Nigeria Tax Act 2025 (standard rate 7.5%): sales of taxable medical devices N25,000,000 (VAT-exclusive); zero-rated sales of medical equipment N8,000,000; purchases of taxable components N10,000,000 (VAT-exclusive); purchases of zero-rated medicines N4,000,000; import of machinery with a CIF value of N6,000,000, on which import VAT at 7.5% of CIF was paid; and consultancy services bought for N2,140,000 (VAT-inclusive). All inputs relate to its taxable and zero-rated supplies. Round to the nearest naira. What is Radiance's output VAT for the month?","options":["N1,349,302","N2,475,000","N1,875,000","N1,744,186"],"correctOption":2,"section":"Value Added Tax","explanation":"Output VAT arises only on the taxable sales: N25,000,000 x 7.5% = N1,875,000, while the zero-rated sales carry VAT at 0%. Option B wrongly charges 7.5% on the zero-rated sales as well. Option D treats the VAT-exclusive figure as VAT-inclusive, and option A is the input VAT figure."}},{"itemId":"2e1dd914-8fcb-5024-a9a5-bf4f61c7e8e8","questionId":"725ee061-c8a6-56d3-8b91-c45965d6b0e0","sourceKey":"bank:TAX-CM223:PQ-009-b","payload":{"prompt":"Radiance Health Ltd, a VAT-registered company, has these transactions for a month in 2026 under the Nigeria Tax Act 2025 (standard rate 7.5%): sales of taxable medical devices N25,000,000 (VAT-exclusive); zero-rated sales of medical equipment N8,000,000; purchases of taxable components N10,000,000 (VAT-exclusive); purchases of zero-rated medicines N4,000,000; import of machinery with a CIF value of N6,000,000, on which import VAT at 7.5% of CIF was paid; and consultancy services bought for N2,140,000 (VAT-inclusive). All inputs relate to its taxable and zero-rated supplies. Round to the nearest naira. What is Radiance's recoverable input VAT for the month?","options":["N1,649,302","N1,349,302","N1,200,000","N1,360,500"],"correctOption":1,"section":"Value Added Tax","explanation":"Recoverable input VAT is N750,000 on components (N10,000,000 x 7.5%), N450,000 on the imported machinery (N6,000,000 x 7.5%) and N149,302 on the consultancy (N2,140,000 x 7.5/107.5), a total of N1,349,302. The 2025 Act allows input VAT on services and fixed assets used for taxable or zero-rated supplies. Option C leaves out the consultancy, option A wrongly adds VAT on zero-rated medicines that carried no VAT, and option D applies 7.5% to a VAT-inclusive amount."}},{"itemId":"78895f33-0a1f-5e1c-a90f-b1b4454a75d1","questionId":"33505419-1b74-5fb2-81f4-f1dc52fa82fd","sourceKey":"bank:TAX-CM223:PQ-009-c","payload":{"prompt":"Radiance Health Ltd, a VAT-registered company, has these transactions for a month in 2026 under the Nigeria Tax Act 2025 (standard rate 7.5%): sales of taxable medical devices N25,000,000 (VAT-exclusive); zero-rated sales of medical equipment N8,000,000; purchases of taxable components N10,000,000 (VAT-exclusive); purchases of zero-rated medicines N4,000,000; import of machinery with a CIF value of N6,000,000, on which import VAT at 7.5% of CIF was paid; and consultancy services bought for N2,140,000 (VAT-inclusive). All inputs relate to its taxable and zero-rated supplies. Round to the nearest naira. What is Radiance's net VAT position for the month?","options":["N675,000 payable","N1,875,000 payable","N525,698 refundable","N525,698 payable"],"correctOption":3,"section":"Value Added Tax","explanation":"Net VAT is output VAT less recoverable input VAT: N1,875,000 - N1,349,302 = N525,698, and because output exceeds input it is payable to the NRS. Option C gets the direction wrong. Option A leaves out the input VAT on the consultancy, and option B ignores input VAT altogether."}},{"itemId":"dc869416-5e43-5436-ae5b-ca3a8f409ea1","questionId":"8f4ad174-5ee7-512d-acf1-18fea41f6703","sourceKey":"bank:TAX-CM223:PQ-009-d","payload":{"prompt":"Under the Nigeria Tax Administration Act 2025, by when must a monthly VAT return be filed, and if a taxpayer is in a refund position, within what time must the NRS refund the tax after a valid refund request?","options":["By the 14th day of the following month; within 90 days","By the 30th day of the following month; within 12 months","By the 21st day of the following month; within 30 days of a valid request","By the 21st day of the following month; within 90 days"],"correctOption":2,"section":"Value Added Tax","explanation":"Section 22(1) NTAA 2025 requires the VAT return by the 21st day of the following month, and section 56(3) requires the NRS to refund, or allow a set-off, within 30 days of a valid refund request. Option D is tempting because 90 days applies to general (non-VAT) refunds, but VAT refunds have the shorter 30-day timeline. Option B confuses the refund period with the 12 months a taxpayer has to make the request."}},{"itemId":"d1373921-500f-53d8-87f3-c9581ca3e9b7","questionId":"a59bbe85-eca5-5278-bde5-14774a333921","sourceKey":"bank:TAX-CM223:VAT-001","payload":{"prompt":"Under the Nigeria Tax Act 2025 (NTA), s.147, VAT is charged at 7.5%. Ikeja Furniture Ltd sells taxable goods for N18,000,000 (VAT-exclusive). What output VAT should it charge?","options":["N1,255,814","N1,350,000","N900,000","N19,350,000"],"correctOption":1,"section":"Value Added Tax","explanation":"Output VAT = VAT-exclusive price x 7.5% = N18,000,000 x 7.5% = N1,350,000. Option A wrongly applies the 7.5/107.5 fraction, which is only for VAT-inclusive prices, and D is the total invoice value including VAT."}},{"itemId":"422f0e19-1d1a-57dc-94a5-c8a08afe4251","questionId":"0b9584b7-133f-55cb-94ee-92e448d5dfcc","sourceKey":"bank:TAX-CM223:VAT-002","payload":{"prompt":"Under the NTA 2025, s.147, VAT is 7.5%. Ajegunle Electronics Ltd's sales for the month were N21,500,000, VAT-INCLUSIVE. What is the output VAT contained in this figure?","options":["N1,612,500","N20,000,000","N1,500,000","N1,075,000"],"correctOption":2,"section":"Value Added Tax","explanation":"For a VAT-inclusive amount, VAT = inclusive price x 7.5/107.5 = N21,500,000 x 7.5/107.5 = N1,500,000. Option A multiplies the inclusive figure by 7.5%, which charges VAT on VAT, and B is the VAT-exclusive sales value."}},{"itemId":"247b4ccc-3b20-586d-98ee-7fbd82deddd4","questionId":"eb15f872-5bc8-5fdb-b95e-acd707bacdea","sourceKey":"bank:TAX-CM223:VAT-003","payload":{"prompt":"Under the NTA 2025, VAT is charged at 7.5%. A customer paid a VAT-inclusive price of N4,300,000 for a generator. What was the VAT-exclusive price?","options":["N4,622,500","N3,977,500","N4,000,000","N300,000"],"correctOption":2,"section":"Value Added Tax","explanation":"VAT-exclusive price = inclusive price / 1.075 = N4,300,000 / 1.075 = N4,000,000. Option B deducts 7.5% of the inclusive price, which takes out too much because the 7.5% was calculated on the smaller exclusive figure."}},{"itemId":"f978ef97-ede3-5e11-a0b5-d579f586b51b","questionId":"f14664b6-11e6-5fa7-9abf-26d431611aa5","sourceKey":"bank:TAX-CM223:VAT-004","payload":{"prompt":"Under the NTA 2025, ss.147 and 155, VAT is 7.5% and input VAT is credited against output VAT. In June, Owerri Packaging Ltd made taxable sales of N30,000,000 and taxable purchases of N12,000,000 (both VAT-exclusive), all used for its taxable supplies. What is the net VAT payable?","options":["N2,250,000","N900,000","N3,150,000","N1,350,000"],"correctOption":3,"section":"Value Added Tax","explanation":"Net VAT = output VAT - input VAT = (N30,000,000 x 7.5%) - (N12,000,000 x 7.5%) = N2,250,000 - N900,000 = N1,350,000. Option A ignores the input VAT credit, and C adds input VAT instead of deducting it."}},{"itemId":"ff0a8803-c2b3-5904-8e9a-c5df10982b2b","questionId":"6ba4b970-35ab-52b7-91d8-d8cb6c33fd31","sourceKey":"bank:TAX-CM223:VAT-005","payload":{"prompt":"Under the NTA 2025, VAT at 7.5% is collected at each stage of a supply chain, with input VAT credited. A manufacturer sells detergent to a wholesaler for N4,000,000, the wholesaler sells it to a retailer for N6,000,000, and the retailer sells it to consumers for N9,000,000 (all VAT-exclusive). How much net VAT does the RETAILER remit?","options":["N225,000","N1,425,000","N675,000","N375,000"],"correctOption":0,"section":"Value Added Tax","explanation":"Retailer's net VAT = output - input = (N9,000,000 - N6,000,000) x 7.5% = N225,000. Option C ignores the retailer's input VAT credit, and B adds up VAT at every stage as if there were no credit mechanism."}},{"itemId":"6a7eaaee-a3ce-55d0-a4dd-591e48608c8c","questionId":"808134ea-babb-51b4-8fe9-0d6b4d1e2fac","sourceKey":"bank:TAX-CM223:VAT-006","payload":{"prompt":"Under the NTA 2025, VAT at 7.5% is collected at each stage of a supply chain with credit for input VAT. Cement passes from a manufacturer (sale price N5,000,000) to a distributor (sale price N8,000,000) to a retailer (sale price N12,000,000), all VAT-exclusive. What TOTAL VAT reaches the NRS from the whole chain?","options":["N900,000","N375,000","N1,875,000","N525,000"],"correctOption":0,"section":"Value Added Tax","explanation":"With input credits, total VAT remitted equals 7.5% of the final selling price: N12,000,000 x 7.5% = N900,000 (that is N375,000 + N225,000 + N300,000). Option C sums output VAT at each stage, which ignores the credits, and that cascading result is what the old sales tax produced."}},{"itemId":"3af9209d-dac1-5699-be89-2f823251fe0d","questionId":"4517e26f-445f-5ad1-b03f-4340963436b0","sourceKey":"bank:TAX-CM223:VAT-007","payload":{"prompt":"Under the NTA 2025, VAT is 7.5% on taxable supplies and exported goods (other than oil and gas) are zero-rated under s.186, with input VAT recoverable. In May, Calabar Cashew Ltd made local taxable sales of N10,000,000 and zero-rated exports of N6,000,000; its taxable purchases were N9,000,000 (all VAT-exclusive, all used in making these supplies). What is its net VAT payable?","options":["N525,000","N750,000","N75,000","N328,125"],"correctOption":2,"section":"Value Added Tax","explanation":"Output VAT = N10,000,000 x 7.5% = N750,000 (exports at 0%); input VAT = N9,000,000 x 7.5% = N675,000, all recoverable because zero-rated supplies keep the right to input credit; net = N75,000. Option A wrongly charges VAT on the exports, and D disallows the input VAT linked to the exports as if they were exempt."}},{"itemId":"6620dc7e-5e8f-5758-b80e-2b9c97ad1d23","questionId":"3a2c23a1-4e2c-5626-8209-8c8b168b3248","sourceKey":"bank:TAX-CM223:VAT-008","payload":{"prompt":"Under the NTA 2025, s.186, exported services are zero-rated, so the supplier charges 0% but can recover input VAT. Yaba Code Ltd's only supplies in a quarter were exported software services of N40,000,000. It paid VAT at 7.5% on taxable purchases of N8,000,000 (VAT-exclusive). What is its VAT refund position?","options":["N600,000","N3,000,000","N2,400,000","Nil, because exports carry no VAT"],"correctOption":0,"section":"Value Added Tax","explanation":"Output VAT on zero-rated exports is nil, while input VAT = N8,000,000 x 7.5% = N600,000, so Yaba Code is owed a refund or credit of N600,000. Option B wrongly charges 7.5% on the exports, and option C nets that wrong output VAT against the input VAT; option D treats the exports as exempt, which would give no recovery."}},{"itemId":"558fd385-2f3b-5400-94d0-f4b86cff6b21","questionId":"e5fa51b4-a7d5-5f39-9030-c9bae0c3bd62","sourceKey":"bank:TAX-CM223:VAT-009","payload":{"prompt":"Under the NTA 2025, VAT is 7.5% and input VAT on purchases used to make EXEMPT supplies cannot be recovered. Lekki Land Developers Ltd sells only land and buildings (exempt under s.185) and buys taxable building services of N6,000,000 (VAT-exclusive). What is the total cost of these services to the company, including VAT?","options":["N6,000,000","N6,450,000","N5,550,000","N450,000"],"correctOption":1,"section":"Value Added Tax","explanation":"An exempt supplier cannot reclaim input VAT, so the VAT becomes part of its cost: N6,000,000 + (7.5% x N6,000,000) = N6,450,000. Option A assumes the VAT is recoverable, which is only true for taxable or zero-rated suppliers."}},{"itemId":"40dd694a-a2da-5a79-8e8a-5023a40657e5","questionId":"833a4feb-7dc4-5383-a591-14f7b782e77b","sourceKey":"bank:TAX-CM223:VAT-010","payload":{"prompt":"Under the NTA 2025, s.149, VAT on imported goods is charged on a value that includes customs duty. Ibadan Pharma Ltd imports machinery with a CIF value of N20,000,000; import duty is 10% of CIF. Ignoring other levies, what import VAT at 7.5% is payable on CIF plus duty?","options":["N150,000","N1,500,000","N3,650,000","N1,650,000"],"correctOption":3,"section":"Value Added Tax","explanation":"VAT base = CIF + duty = N20,000,000 + N2,000,000 = N22,000,000; VAT = N22,000,000 x 7.5% = N1,650,000. Option B charges VAT on CIF alone and forgets to add the duty, the most common slip."}},{"itemId":"e95b2fa0-64a3-5eb4-99a0-4223964624f6","questionId":"009de13d-1e84-59da-bfc3-e283e6793cfc","sourceKey":"bank:TAX-CM223:VAT-011","payload":{"prompt":"Under the NTA 2025, s.149, import VAT is charged on CIF plus import duty. Nnewi Parts Ltd imports spare parts with a CIF value of USD 50,000 when USD 1 = N1,500. Import duty is 20% of CIF. Ignoring other levies, what is the import VAT at 7.5%?","options":["N5,625,000","N1,125,000","N6,750,000","N4,500,000"],"correctOption":2,"section":"Value Added Tax","explanation":"CIF = 50,000 x N1,500 = N75,000,000; duty = 20% = N15,000,000; VAT = (N75,000,000 + N15,000,000) x 7.5% = N6,750,000. Option A omits the duty from the base, and D uses the old 5% VAT rate."}},{"itemId":"8578ef25-4c2f-5eda-af19-1f52941e44f6","questionId":"819e10fa-f007-56a6-941b-d9f22b4a5e1e","sourceKey":"bank:TAX-CM223:VAT-012","payload":{"prompt":"Under the NTAA 2025, s.81(1), net VAT revenue is shared 10% to the Federal Government, 55% to the States and FCT, and 35% to Local Governments. If net VAT revenue for a month is N800 billion, what is the share of the States and FCT?","options":["N80,000,000,000","N440,000,000,000","N400,000,000,000","N280,000,000,000"],"correctOption":1,"section":"Value Added Tax","explanation":"States and FCT share = 55% x N800 billion = N440 billion. Option C uses the 50% share under the repealed VAT Act, while D and A are the Local Government and Federal Government shares."}},{"itemId":"bce89d2d-ba36-5edf-9d64-ecbf30d3113e","questionId":"fcb88bca-85e7-55cb-8f98-387050efbc2b","sourceKey":"bank:TAX-CM223:VAT-013","payload":{"prompt":"Under the NTAA 2025, s.81(1), net VAT revenue is shared 10% Federal Government, 55% States and FCT, and 35% Local Governments. If net VAT revenue is N1,200 billion, what goes to Local Governments?","options":["N240,000,000,000","N420,000,000,000","N660,000,000,000","N180,000,000,000"],"correctOption":1,"section":"Value Added Tax","explanation":"Local Governments receive 35% x N1,200 billion = N420 billion. Option C is the States' 55% share, and D uses the 15% Federal share under the old law."}},{"itemId":"aa40f8a5-2161-5cd1-a514-57cf5d99cbe1","questionId":"04104eee-78f7-5f69-b3d8-aa64778cb8a8","sourceKey":"bank:TAX-CM223:VAT-014","payload":{"prompt":"Under the NTAA 2025, s.81(1), the Federal Government receives 10% of net VAT revenue. Under the repealed VAT Act it received 15%. If net VAT revenue is N600 billion, how much does the Federal Government receive under the NTAA 2025?","options":["N330,000,000,000","N60,000,000,000","N210,000,000,000","N90,000,000,000"],"correctOption":1,"section":"Value Added Tax","explanation":"Federal share = 10% x N600 billion = N60 billion. Option D applies the old 15% share, which the NTAA reduced so that States and Local Governments receive more."}},{"itemId":"4b057bcf-dedb-5360-8947-290476595a85","questionId":"64726a3e-8e35-5349-be1b-f5239f85f939","sourceKey":"bank:TAX-CM223:VAT-015","payload":{"prompt":"Under the NTAA 2025, s.81(2), the VAT share of the States and FCT is distributed 50% equally, 20% on population and 30% on consumption. If the States and FCT pool for a month is N550 billion, how much is distributed on the basis of POPULATION?","options":["N165,000,000,000","N110,000,000,000","N302,500,000,000","N275,000,000,000"],"correctOption":1,"section":"Value Added Tax","explanation":"Population portion = 20% x N550 billion = N110 billion. Option A is the 30% consumption portion, and D is the 50% shared equally."}},{"itemId":"5a39aa85-6ed5-5d52-9432-692be52fd706","questionId":"2296a6a6-aa23-5720-aad3-16cd335cb275","sourceKey":"bank:TAX-CM223:VAT-016","payload":{"prompt":"Under the NTAA 2025, s.81(2), VAT shared among Local Governments is distributed 50% equally, 20% on population and 30% on consumption, where consumption is determined by the place of consumption. If the Local Government pool is N350 billion, how much is distributed on the basis of CONSUMPTION?","options":["N105,000,000,000","N70,000,000,000","N122,500,000,000","N175,000,000,000"],"correctOption":0,"section":"Value Added Tax","explanation":"Consumption portion = 30% x N350 billion = N105 billion. Option B is the 20% population portion, and C wrongly reuses the 35% Local Government share of the national pool."}},{"itemId":"cbb1ccff-c6a3-5893-bf6b-d838efcce28c","questionId":"0e8c9ff5-f50e-5180-9a54-085e96137f1b","sourceKey":"bank:TAX-CM223:VAT-017","payload":{"prompt":"Under the NTAA 2025, s.101, a taxable person who fails to file a return is liable to N100,000 for the first month of failure and N50,000 for each subsequent month. Onitsha Traders Ltd filed its VAT return three months late. What is the penalty?","options":["N250,000","N300,000","N200,000","N150,000"],"correctOption":2,"section":"Value Added Tax","explanation":"Penalty = N100,000 (first month) + 2 x N50,000 (second and third months) = N200,000. Option B charges N100,000 for every month, and A counts three subsequent months instead of two."}},{"itemId":"82dce167-be7c-54fa-be8d-310b772a3304","questionId":"f887eb57-22ac-5006-806f-5930c2823ed7","sourceKey":"bank:TAX-CM223:VAT-018","payload":{"prompt":"Under the NTAA 2025, s.100, a person who fails to register is liable to N50,000 for the first month of failure and N25,000 for each subsequent month. Ajao Imports Ltd delayed its registration by four months. What is the penalty?","options":["N100,000","N150,000","N200,000","N125,000"],"correctOption":3,"section":"Value Added Tax","explanation":"Penalty = N50,000 (first month) + 3 x N25,000 = N125,000. Option C charges N50,000 for all four months, and B counts four subsequent months instead of three."}},{"itemId":"b110b6a2-9551-5fa7-9c56-4c37deb4d000","questionId":"284734f8-c99e-5892-9e0b-0ac41c60d622","sourceKey":"bank:TAX-CM223:VAT-019","payload":{"prompt":"Under the NTAA 2025, s.107(1), VAT collected but not remitted on time attracts an administrative penalty of 10% per annum plus interest at the CBN MPR. Warri Gas Services Ltd remitted VAT of N2,920,000 50 days late when the MPR was 27%. Time-apportioning both on a days/365 basis, what is the total of penalty and interest?","options":["N108,000","N400,000","N148,000","N1,168,000"],"correctOption":2,"section":"Value Added Tax","explanation":"Penalty + interest = N2,920,000 x (10% + 27%) x 50/365 = N148,000. Option B treats the 10% as a flat charge, A leaves out the penalty, and D applies the 40% failure-to-deduct rate."}},{"itemId":"554a062e-5564-53a1-9fd5-b730e66bc60e","questionId":"61ecdcc7-997d-56b5-87a6-24bd699e9dee","sourceKey":"bank:TAX-CM223:VAT-020","payload":{"prompt":"Under the NTA 2025, input VAT on services used for taxable supplies is recoverable. Port Harcourt Logistics Ltd paid a VAT-INCLUSIVE consultancy fee of N2,150,000 (VAT at 7.5%) for its taxable business. How much input VAT can it claim?","options":["N150,000","N2,000,000","N161,250","N107,500"],"correctOption":0,"section":"Value Added Tax","explanation":"Input VAT = N2,150,000 x 7.5/107.5 = N150,000. Option C applies 7.5% to the VAT-inclusive figure, which overstates the claim, and B is the VAT-exclusive fee."}},{"itemId":"1c18bd59-2f4b-51ba-aa76-074429e2963b","questionId":"b50693df-2d31-5147-8c46-e65dda992bcc","sourceKey":"bank:TAX-CM223:VAT-021","payload":{"prompt":"Under the NTA 2025 (VAT 7.5%; zero-rated exports under s.186; import VAT on CIF plus duty under s.149), Aba Leather Ltd had these July figures: local taxable sales N32,250,000 (VAT-INCLUSIVE); exports N5,000,000 (zero-rated); taxable purchases N14,000,000 (VAT-exclusive); purchases from an exempt supplier N2,000,000; and imported machinery with CIF N6,000,000 and 5% import duty. What is the net VAT payable?","options":["N577,500","N896,250","N1,102,500","N727,500"],"correctOption":3,"section":"Value Added Tax","explanation":"Output VAT = N32,250,000 x 7.5/107.5 = N2,250,000; input VAT = (N14,000,000 x 7.5%) + (N6,300,000 x 7.5%) = N1,050,000 + N472,500 = N1,522,500; net payable = N727,500. Option B takes 7.5% of the VAT-inclusive sales, A wrongly claims input VAT on the exempt purchases, and C charges VAT on the zero-rated exports."}},{"itemId":"a6b7abf9-c5ef-5428-b831-306960664e2e","questionId":"b14cbc8f-2a7a-533d-aaa9-c38db55769fa","sourceKey":"bank:TAX-CM223:VAT-022","payload":{"prompt":"Under the NTA 2025, s.155, net VAT is output VAT minus input VAT. Kaduna Mills Ltd's output VAT for August was N900,000 and its net VAT payable was N270,000. How much input VAT did it claim?","options":["N270,000","N879,750","N630,000","N1,170,000"],"correctOption":2,"section":"Value Added Tax","explanation":"Input VAT = output VAT - net VAT payable = N900,000 - N270,000 = N630,000. Option D adds the two figures instead of subtracting them."}},{"itemId":"14c2c63e-9788-5fa4-a399-5f4df1a7ad38","questionId":"c5ee2e63-80bc-5999-9922-9ff5e9cc6728","sourceKey":"bank:TAX-CM223:VAT-023","payload":{"prompt":"Under the NTA 2025, input VAT on a cost used for both taxable and exempt supplies must be apportioned. Jos Dairy Ltd paid input VAT of N600,000 on a shared factory overhead. Taxable supplies are 75% of its total supplies and exempt supplies 25%. Apportioning by this ratio, how much input VAT can it recover?","options":["N150,000","N600,000","N450,000","N33,750"],"correctOption":2,"section":"Value Added Tax","explanation":"Recoverable input VAT = N600,000 x 75% = N450,000; the 25% linked to exempt supplies is a cost. Option B recovers everything, and D wrongly applies the 7.5% rate a second time to an amount that is already VAT."}},{"itemId":"b33aba90-66fe-598b-8462-939c30255b60","questionId":"3d8434f7-3093-59ca-b4d5-1d98a0b37322","sourceKey":"bank:TAX-CM223:VAT-024","payload":{"prompt":"Under the NTA 2025, the final consumer bears the economic burden of VAT at 7.5%. A consumer pays N10,750,000, VAT-inclusive, for a car from a dealer. How much of this payment is VAT?","options":["N10,000,000","N537,500","N806,250","N750,000"],"correctOption":3,"section":"Value Added Tax","explanation":"VAT = N10,750,000 x 7.5/107.5 = N750,000. Option C multiplies the inclusive price by 7.5%, and B applies the old 5% rate to the inclusive price."}},{"itemId":"499e7ea2-609e-5b19-a5d2-7ff3b9241e9d","questionId":"ea67a8ce-1408-5390-85c1-e809da07abce","sourceKey":"bank:TAX-CM223:VAT-025","payload":{"prompt":"Under the NTA 2025, VAT at 7.5% is a multi-stage tax with credit for input VAT. A distributor buys bottled water for N5,000,000 and sells it for N7,000,000 (both VAT-exclusive). What net VAT does the distributor remit?","options":["N525,000","N900,000","N375,000","N150,000"],"correctOption":3,"section":"Value Added Tax","explanation":"Net VAT = (N7,000,000 - N5,000,000) x 7.5% = N150,000, which is VAT on the value the distributor adds. Option A is its output VAT before the input credit, and C is only its input VAT."}},{"itemId":"049a1697-0043-57e0-942f-2c85e1069adb","questionId":"00ef6018-1d13-515c-be54-55b83d3806d0","sourceKey":"bank:TAX-CM223:VAT-026","payload":{"prompt":"Under the NTA 2025, baby products are exempt under s.185 and other goods are taxable at 7.5%. Ikotun Supermarket Ltd sold N12,000,000 of goods (VAT-exclusive) in a month, of which N3,000,000 were baby products. What output VAT should it account for?","options":["N225,000","N337,500","N900,000","N675,000"],"correctOption":3,"section":"Value Added Tax","explanation":"Only the N9,000,000 of taxable goods bear VAT: N9,000,000 x 7.5% = N675,000. Option C wrongly charges VAT on the exempt baby products as well."}},{"itemId":"b1c9e828-e36f-5cfa-bb2e-83925fd6a4fc","questionId":"1c15c376-41a1-550a-8118-8ee8386ae9a4","sourceKey":"bank:TAX-CM223:VAT-027","payload":{"prompt":"Under the NTA 2025, basic food items are zero-rated under s.186 and other goods are taxable at 7.5%. Ilorin Foods Ltd sold taxable goods of N20,000,000 and basic food items of N8,000,000. It made taxable purchases of N10,000,000 for its taxable goods and N4,000,000 for its food items (all VAT-exclusive). What is its net VAT payable?","options":["N450,000","N750,000","N1,500,000","N1,050,000"],"correctOption":0,"section":"Value Added Tax","explanation":"Output VAT = N20,000,000 x 7.5% = N1,500,000; input VAT = (N10,000,000 + N4,000,000) x 7.5% = N1,050,000, all recoverable because zero-rated supplies keep input credit; net = N450,000. Option B disallows the input VAT on the food side as if those sales were exempt, and D charges VAT on the zero-rated food."}},{"itemId":"d6995d06-f25e-5d2b-b3a8-e265adc16325","questionId":"d0885be7-4de0-5c60-b5df-a81057388465","sourceKey":"bank:TAX-CM223:VAT-028","payload":{"prompt":"Under the NTAA 2025, s.56, the NRS must refund VAT not later than 30 days after receiving a valid refund request. Abeokuta Exporters Ltd's valid request was received by the NRS on 10 March 2026. By what date must the refund (or set-off) be made?","options":["21 April 2026","9 April 2026","10 June 2026","8 June 2026"],"correctOption":1,"section":"Value Added Tax","explanation":"Thirty days from 10 March 2026 is 9 April 2026. Option D applies the 90-day period that governs general (non-VAT) tax refunds under s.55, and A confuses the refund deadline with the monthly filing date."}},{"itemId":"af49109e-f920-507e-9cec-bf7ad5871302","questionId":"9e143cbd-a1d6-59b1-b736-c6108d72e203","sourceKey":"bank:TAX-CM223:VAT-029","payload":{"prompt":"Under the NTAA 2025, s.22(1), a VAT return is due on or before the 21st day of the month following the month of the transactions. Benin Rubber Ltd's transactions took place in November 2026. When is its VAT return due?","options":["21 December 2026","30 November 2026","14 December 2026","21 January 2027"],"correctOption":0,"section":"Value Added Tax","explanation":"November returns are due by 21 December 2026, the 21st day of the following month. Option D skips a month, and C uses a 14th-day date that is not the filing deadline for a taxable person's own return."}},{"itemId":"2a569e8e-b84e-5b7e-a2bd-8b00db64c4d0","questionId":"ccec2bca-67e9-5173-8367-c0dd41b50287","sourceKey":"bank:TAX-CM223:VAT-030","payload":{"prompt":"Under the NTA 2025, land and buildings, including interests in them, are exempt from VAT under s.185. Ilupeju Estates Ltd receives annual rent of N12,000,000 from a commercial tenant. What VAT should it charge on the rent?","options":["N600,000","N837,209","N900,000","Nil"],"correctOption":3,"section":"Value Added Tax","explanation":"Rent is a supply of an interest in land or buildings, which is exempt, so no VAT is charged. Option C wrongly treats the rent as a standard taxable supply."}},{"itemId":"1c732b0b-81ed-5b70-a9b6-675c99df24f3","questionId":"23fa7cd2-933b-58be-bc47-1832abc761a9","sourceKey":"bank:TAX-CM223:VAT-031","payload":{"prompt":"Under the NTA 2025, VAT is 7.5%. A non-resident streaming company supplies services to Nigerian subscribers worth N6,000,000 (VAT-exclusive) in a month. Under s.150 it must charge Nigerian VAT on these supplies. How much VAT is due?","options":["Nil, because the supplier is non-resident","N300,000","N450,000","N600,000"],"correctOption":2,"section":"Value Added Tax","explanation":"Services provided to and consumed by persons in Nigeria are taxable even if the supplier is abroad: VAT = N6,000,000 x 7.5% = N450,000. Option A assumes foreign suppliers are outside the Nigerian VAT net, which s.150 rejects."}},{"itemId":"24ef8285-3a08-58be-ab98-fa29db0d0e8a","questionId":"d5f44ef4-b1b5-5e6f-9e94-dff34a29b3cc","sourceKey":"bank:TAX-CM223:VAT-032","payload":{"prompt":"Under the Nigeria Tax Act 2025, s.147, what is the standard rate of VAT on taxable supplies?","options":["5%","15%","10%","7.5%"],"correctOption":3,"section":"Value Added Tax","explanation":"Section 147 charges VAT at 7.5% on the value of all taxable supplies, the same rate set by the Finance Act 2019. Option A is the pre-2020 rate under the old VAT Act."}},{"itemId":"7c4dcc4e-58e3-545a-8aea-25f17697385d","questionId":"1394e7d7-9b81-5e2c-88c2-38e08e91a974","sourceKey":"bank:TAX-CM223:VAT-033","payload":{"prompt":"A tax on consumption, collected at every stage of the supply chain, where each registered person charges tax on sales and deducts tax paid on purchases, and the final consumer bears the burden. Under the NTA 2025, this is:","options":["Value Added Tax","Stamp duty","Withholding tax","Excise duty"],"correctOption":0,"section":"Value Added Tax","explanation":"This is VAT: a multi-stage consumption tax with an input credit mechanism, so the full burden ends up on the final consumer. Option C is an advance income tax deducted by payers, and D is a single-stage charge on locally made goods."}},{"itemId":"cd7f82ed-564e-5aac-8f3f-2b783930ab50","questionId":"b52e1cd2-0946-564d-a253-8bc0804896f0","sourceKey":"bank:TAX-CM223:VAT-034","payload":{"prompt":"Under the NTA 2025, 'input VAT' means:","options":["VAT paid by a taxable person to a supplier on taxable supplies made to that person","VAT collected by government agencies on contracts","VAT paid by the final consumer only","VAT charged by a taxable person on supplies it makes"],"correctOption":0,"section":"Value Added Tax","explanation":"Input VAT is the VAT a business pays on its purchases, which it can credit against its output VAT. Option D is the definition of output VAT."}},{"itemId":"bcb91f32-e9ab-5dd8-82ee-2b96e3d352b1","questionId":"9174c24d-1780-558d-89fc-d3ee06229e1a","sourceKey":"bank:TAX-CM223:VAT-035","payload":{"prompt":"Under the NTA 2025, 'output VAT' means:","options":["VAT charged and collected by a taxable person on the taxable supplies it makes","VAT paid on goods imported into Nigeria","VAT refunded by the NRS after an audit","VAT paid on purchases of raw inputs"],"correctOption":0,"section":"Value Added Tax","explanation":"Output VAT is the VAT a business adds to its own sales. Option D describes input VAT, and B is import VAT, which for the importer is an input tax."}},{"itemId":"c69eefec-9cc6-561e-a9f7-ff8e2cba8d0a","questionId":"b2f86495-8bbc-5606-ba3c-ca36dca15b72","sourceKey":"bank:TAX-CM223:VAT-036","payload":{"prompt":"Under the NTA 2025, s.155, the result of 'output VAT minus recoverable input VAT' measures:","options":["The total VAT borne by the final consumer","The net VAT to remit to the NRS, or to claim as a refund or credit if negative","The VAT due on imported goods","The taxable person's profit for the month"],"correctOption":1,"section":"Value Added Tax","explanation":"Output VAT less recoverable input VAT is the net position: a positive figure is paid to the NRS, and a negative figure becomes a refund or credit. Option A is wrong because the consumer's burden equals VAT on the final price, not one trader's net figure."}},{"itemId":"e7c1709f-507a-5aac-8ab9-891f2059a06e","questionId":"c8d0efc0-4bef-5f5c-a521-29299b00c41f","sourceKey":"bank:TAX-CM223:VAT-038","payload":{"prompt":"Under the NTA 2025, s.185, which of the following is an EXEMPT supply?","options":["Baby products","Exported services","Fertilisers","Basic food items"],"correctOption":0,"section":"Value Added Tax","explanation":"Baby products are on the exempt list in s.185. Basic food, exported services and fertilisers (options D, B, C) are zero-rated under s.186, so their suppliers can still recover input VAT."}},{"itemId":"a9bc9652-00ea-54d7-af18-6049fba5a596","questionId":"61084c26-c1c4-5695-a86a-7ddf155b5c08","sourceKey":"bank:TAX-CM223:VAT-039","payload":{"prompt":"Under the NTA 2025, s.186, which of the following is ZERO-RATED?","options":["Government licences","Medical and pharmaceutical products","Money and securities","Land and buildings"],"correctOption":1,"section":"Value Added Tax","explanation":"Medical and pharmaceutical products are zero-rated, so suppliers charge 0% and recover input VAT. Land and buildings, money and securities, and government licences (options D, C, A) are exempt under s.185."}},{"itemId":"70dc287c-3cbd-5277-a052-0f22071d9681","questionId":"e210b834-b403-5085-8b1e-70dc9862c3ba","sourceKey":"bank:TAX-CM223:VAT-040","payload":{"prompt":"Which of the following is NOT a zero-rated supply under the NTA 2025, s.186?","options":["Oil and gas exports","Exported services","Educational books","Exported goods other than oil and gas"],"correctOption":0,"section":"Value Added Tax","explanation":"Oil and gas exports are EXEMPT under s.185, so oil and gas exporters cannot recover input VAT on them. Exported services, educational books and non-oil exports (B, C, D) are zero-rated."}},{"itemId":"a71e9283-aa1d-535c-b110-d6aed62c5e9d","questionId":"102b1741-0100-503b-945c-9abb434959f1","sourceKey":"bank:TAX-CM223:VAT-041","payload":{"prompt":"Yaba Code Ltd, a Nigerian software company, sells its services only to clients in the United States. Under the NTA 2025, how are these supplies treated for VAT?","options":["Outside VAT entirely, with no registration duty","Exempt: no output VAT, and input VAT is a cost","Zero-rated: no output VAT, and input VAT on its costs is recoverable","Taxable at 7.5%, because the supplier is in Nigeria"],"correctOption":2,"section":"Value Added Tax","explanation":"The NTA expressly zero-rates exported services, so the firm charges 0% but reclaims VAT on its inputs, which keeps its prices competitive abroad. Option B treats the exports as exempt, which would make its input VAT an unrecoverable cost."}},{"itemId":"2c8e06e0-d128-5e75-af85-febe8a33d7d6","questionId":"6aab20a5-21c5-57c3-ab3c-547a1f6e2cd9","sourceKey":"bank:TAX-CM223:VAT-042","payload":{"prompt":"Under the NTAA 2025, s.22(1), by when must a taxable person file its monthly VAT return?","options":["On or before the 30th day of the same month","Within 6 months of the end of the accounting year","On or before the 21st day of the month following the month of the transactions","On or before the 10th day of the following quarter"],"correctOption":2,"section":"Value Added Tax","explanation":"Section 22(1) requires monthly VAT returns by the 21st day of the following month, whether or not there was activity. The other options describe deadlines that apply to no VAT return."}},{"itemId":"1dcc402a-e3f2-5949-b2cd-ecdfb0dbcfa8","questionId":"afa9c39b-ea11-51f1-acb3-08aae47c31bf","sourceKey":"bank:TAX-CM223:VAT-043","payload":{"prompt":"Under the NTAA 2025 (with s.22 on VAT returns), a 'small business' (freed from the obligation to charge VAT and file VAT returns) is one with:","options":["Total fixed assets below N100,000,000, including professional firms","Gross turnover of N25,000,000 or less a year, whatever its trade","Gross turnover of N100,000,000 or less a year and total fixed assets within N250,000,000, excluding providers of professional services","Fewer than 50 employees and turnover below N50,000,000"],"correctOption":2,"section":"Value Added Tax","explanation":"The NTAA defines a small business by both a N100 million turnover limit and a N250 million fixed-asset limit, and professional service providers are excluded. Option B is the old N25 million administrative threshold."}},{"itemId":"90f6a9be-5822-56f7-abc3-aad6b58a8e80","questionId":"3ba1a9c7-620f-5ba6-b65a-9d2051fd67c5","sourceKey":"bank:TAX-CM223:VAT-044","payload":{"prompt":"Under the NTAA 2025, Okoye & Partners, a law firm with annual turnover of N60,000,000 and fixed assets of N20,000,000, claims it is a 'small business' that need not file VAT returns. Is the claim correct?","options":["Yes, because its fixed assets are below N250,000,000","No, because providers of professional services are excluded from the small business definition","Yes, because its turnover is below N100,000,000","No, because only companies with turnover below N25,000,000 qualify"],"correctOption":1,"section":"Value Added Tax","explanation":"Although the firm's figures are within both limits, professional service providers are expressly excluded from the small business definition, so it must charge VAT and file returns. Options C and A each look at one limit and ignore the exclusion."}},{"itemId":"25f8b6fb-2e0f-50e7-a911-4b48a2762a97","questionId":"c964a999-a539-5049-9598-105ec9b8e921","sourceKey":"bank:TAX-CM223:VAT-045","payload":{"prompt":"Under the NTAA 2025, s.56, what are the time limits for a VAT refund?","options":["Request within 30 days; NRS to refund within 12 months","Request within 12 months of the transaction; NRS to refund (or set off) within 30 days of a valid request","Request within 6 years; NRS to refund within 90 days","Request within 90 days; NRS to refund within 21 days"],"correctOption":1,"section":"Value Added Tax","explanation":"Section 56 requires the claim within 12 months of the transaction and obliges the NRS to refund or set off within 30 days of receiving it. Option C mixes in the six-year claim period and 90-day refund period for general (non-VAT) refunds under s.55."}},{"itemId":"f5613a57-7399-5309-818d-791d5fd79a9c","questionId":"dd4977e4-5de2-5197-bac8-ab2ee19d0378","sourceKey":"bank:TAX-CM223:VAT-047","payload":{"prompt":"Under the NTAA 2025, s.81(2), on what basis is VAT revenue distributed among the States and among the Local Governments?","options":["30% equally, 50% by population, 20% by consumption","50% equally, 20% by population, 30% by consumption","50% by derivation, 30% by land mass, 20% equally","100% according to where VAT returns are filed"],"correctOption":1,"section":"Value Added Tax","explanation":"Section 81(2) shares the pool 50% equally, 20% on population and 30% on consumption. Option D is ruled out because consumption is measured by where goods and services are consumed, not where returns are filed."}},{"itemId":"f93eafc7-65bb-5009-8f86-6ebbcd9915a3","questionId":"e9ea5284-e6ce-5b90-bfe3-48dee23f9a1c","sourceKey":"bank:TAX-CM223:VAT-048","payload":{"prompt":"A Lagos-headquartered bank files all its VAT returns in Lagos, but most of the services on which it charged VAT were consumed by customers in Kano. Under the NTAA 2025, s.81, how is the consumption-based part of VAT distribution determined?","options":["By the state where the company's head office is located","By the state where the VAT return is filed","By the population of the state where the company was incorporated","By the place of consumption, irrespective of where the return is filed"],"correctOption":3,"section":"Value Added Tax","explanation":"The Act says consumption is determined by the place of consumption, irrespective of where the return is filed, so Kano benefits from consumption there. Options A and B describe the head-office bias that this rule was designed to remove."}},{"itemId":"3c1e50f7-a9c3-5571-a7ff-828d5d089a53","questionId":"cf68b606-0ec8-5679-9092-7ea4fb031c9e","sourceKey":"bank:TAX-CM223:VAT-049","payload":{"prompt":"How does VAT under the NTA 2025 differ from the old single-stage Sales Tax that it replaced?","options":["VAT covers goods only, while Sales Tax covered goods and services","VAT is charged only once at the retail stage, like Sales Tax","VAT is administered by each State, while Sales Tax was federal","VAT is charged at each stage with credit for input tax, removing the cascading 'tax-on-tax' effect"],"correctOption":3,"section":"Value Added Tax","explanation":"VAT is multi-stage with an input credit, so tax is not charged on tax. The old Sales Tax had no credit mechanism, covered goods only and was State-administered, which is why options A and C reverse the facts."}},{"itemId":"a957fb01-c04c-58d8-a6f2-036f387e84ff","questionId":"60d5214b-a9fc-57be-abb7-3df3f0a3ee14","sourceKey":"bank:TAX-CM223:VAT-050","payload":{"prompt":"Under the NTA 2025, s.150, what is the VAT position of a non-resident company that supplies taxable services to persons in Nigeria?","options":["It must register for VAT and charge Nigerian VAT on those supplies","It pays VAT only on goods, never on services","It is outside the VAT net because it has no Nigerian office","It may choose freely whether to charge VAT"],"correctOption":0,"section":"Value Added Tax","explanation":"The NTA brings non-resident suppliers of taxable goods and services to Nigerian recipients into the VAT net, so they must register and charge VAT. Option C reflects the gap that the provision closes."}},{"itemId":"4206fe8a-1c18-5759-bab6-7ab7c47442fb","questionId":"881c7c3d-2335-54b3-a324-3fc26ac1c317","sourceKey":"bank:TAX-CM223:VAT-051","payload":{"prompt":"Under the NTA 2025, s.149, VAT on imported goods is charged on:","options":["The FOB value only","The import duty alone","The value of the goods including customs duty and other charges up to the point of entry","The importer's expected selling price in Nigeria"],"correctOption":2,"section":"Value Added Tax","explanation":"The VAT base for imports is the customs (CIF) value plus duties and other charges, so VAT is effectively charged on duty as well. Option A leaves out insurance, freight and duty."}},{"itemId":"23e2b319-5453-53f1-a0ed-a901bbe62112","questionId":"3eed9186-d528-5a09-9904-4ac2cfd15b7c","sourceKey":"bank:TAX-CM223:VAT-052","payload":{"prompt":"Under the NTA 2025, which change was made to the recovery of input VAT compared with the old VAT Act?","options":["Input VAT is now claimable only on goods bought for resale","Input VAT on services and fixed assets used for taxable supplies is now claimable","Input VAT can now be claimed on exempt supplies","Input VAT recovery was abolished for exporters"],"correctOption":1,"section":"Value Added Tax","explanation":"The old law effectively limited input credit to goods for resale or direct use in production; the NTA allows recovery on services and fixed assets used for taxable supplies. Option A describes the old narrow rule, and C is wrong because exempt-related input VAT is still a cost."}},{"itemId":"a84375fe-7702-56b2-a85d-f0c4cd316369","questionId":"809c73a6-eb69-5a8a-a34f-edd0987a515e","sourceKey":"bank:TAX-CM223:VAT-053","payload":{"prompt":"Under the NTAA 2025, s.101, what is the administrative penalty for failing to file a return?","options":["N50,000 for the first month and N25,000 for each subsequent month","40% of the tax due","N100,000 for the first month and N50,000 for each subsequent month","10% per annum of the tax plus interest at the MPR"],"correctOption":2,"section":"Value Added Tax","explanation":"Section 101 charges N100,000 in the first month and N50,000 for each later month the failure continues. Option A is the failure-to-register penalty under s.100, and D is the late-remittance penalty."}},{"itemId":"7f192cd8-0cea-5ca0-b692-1cf1e75041a8","questionId":"ec10989f-4b6f-53df-b516-3f6f8d55841e","sourceKey":"bank:TAX-CM223:VAT-054","payload":{"prompt":"Under the NTAA 2025, s.100, what is the administrative penalty for failing to register as required?","options":["A one-off N5,000,000","N100,000 for the first month and N50,000 for each subsequent month","N10,000 per day","N50,000 for the first month and N25,000 for each subsequent month"],"correctOption":3,"section":"Value Added Tax","explanation":"Section 100 imposes N50,000 for the first month and N25,000 for each subsequent month. Option B is the failure-to-file penalty, and N5,000,000 in A is the separate penalty on a body that awards a contract to an unregistered person."}},{"itemId":"cefe6260-e8e0-5f62-808c-79d0444ddd2f","questionId":"f4f70f4d-354b-5721-9119-1fe6938e14a0","sourceKey":"bank:TAX-CM223:VAT-057","payload":{"prompt":"Under the NTA 2025, money and securities are exempt supplies under s.185. Ikeja Finance Ltd, whose only supplies are financial dealings in money and securities, buys office furniture and pays VAT on it. What happens to the VAT it paid on the furniture?","options":["It is set off against the company's WHT","It is an irrecoverable cost to the company","It is passed on to the State government","It is refunded within 30 days"],"correctOption":1,"section":"Value Added Tax","explanation":"A supplier making only exempt supplies cannot recover input VAT, so the VAT becomes part of its costs. Option D would be right only if its supplies were zero-rated or taxable."}},{"itemId":"a1a603d3-543f-5184-9faa-1ba05df4c102","questionId":"1804a560-0ed9-5f78-8e4c-e14e160963f0","sourceKey":"bank:TAX-CM223:VAT-058","payload":{"prompt":"Under the NTA 2025, VAT is charged on 'goods' and 'services'. For VAT purposes, 'goods' means:","options":["Only imported tangible property","Tangible and intangible property, including shares","Only movable tangible property","All forms of tangible property, movable or immovable"],"correctOption":3,"section":"Value Added Tax","explanation":"For VAT, goods cover all tangible property, movable or immovable, although supplies of land and buildings are then exempt. Option B is wrong because money and securities are not goods and are exempt anyway."}},{"itemId":"1a6fbc2e-c5cd-533a-8491-68c22c668bfa","questionId":"0dc327c2-5689-5252-a2f9-d754d0bf232c","sourceKey":"bank:TAX-CM223:VAT-059","payload":{"prompt":"Under the NTA 2025, a UK consultant advises a Lagos company by video call, and the advice is used in Lagos. Is this a taxable supply of a service in Nigeria?","options":["No, because services received from abroad are exempt","Yes, because the service is provided to and consumed by a person in Nigeria","Yes, but only if the consultant visits Nigeria","No, because the consultant is physically outside Nigeria"],"correctOption":1,"section":"Value Added Tax","explanation":"A service is treated as supplied in Nigeria where it is provided to and consumed by a person in Nigeria, wherever it is performed. Options D and C focus wrongly on where the supplier physically is."}},{"itemId":"19c58198-49d5-5d96-a995-76d658aac20a","questionId":"124dc6cf-a2ac-5741-b262-9ae5c2840620","sourceKey":"bank:TAX-CM223:VAT-060","payload":{"prompt":"Under the NTA 2025, which of these is EXEMPT from VAT under s.185?","options":["Medical services","Educational books and materials","Exported services","Goods and services purchased by diplomatic missions"],"correctOption":3,"section":"Value Added Tax","explanation":"Supplies to diplomatic missions are now on the exempt list. Educational books, medical services and exported services (options B, A, C) are zero-rated."}},{"itemId":"7d854885-613e-5fb9-8c2a-b2fbbdc1d93a","questionId":"d703bce9-6790-55f4-a714-30bb11e20bf7","sourceKey":"bank:TAX-CM223:PQ-006-a","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, what ad valorem stamp duty rate applies to a lease granted for a term of 12 years?","options":["3%","0.78%","1.5%","6%"],"correctOption":0,"section":"Stamp Duties","explanation":"A lease for a term of more than 7 years but not more than 21 years attracts 3% under the Ninth Schedule, so a 12-year lease falls in this band. Option B is the rate for short leases of up to 7 years. Option D is the figure wrongly applied to such leases in some older materials, and option C is the rate for a conveyance on sale."}},{"itemId":"1ca2e628-cc28-593e-b46e-f9db72ed8fd0","questionId":"7a9ac7b5-1da7-576e-9092-a9fc37a20f51","sourceKey":"bank:TAX-CM223:PQ-006-b","payload":{"prompt":"Under the Nigeria Tax Act 2025, within what period after execution must a chargeable instrument be stamped?","options":["90 days","30 days","14 days","40 days"],"correctOption":1,"section":"Stamp Duties","explanation":"The 2025 Act requires a chargeable instrument to be stamped within 30 days of execution, harmonising the timeline. Option D was the period under the repealed Stamp Duties Act. Options C and A are not the statutory period."}},{"itemId":"de4bca2b-8ff6-5f1d-8477-9502acc5ae6d","questionId":"e8dbd53e-0037-52a7-9b8d-67dfbdfc9525","sourceKey":"bank:TAX-CM223:PQ-006-c","payload":{"prompt":"Under section 110 of the Nigeria Tax Administration Act 2025, what is the penalty for failing to stamp a dutiable instrument on time?","options":["Double the duty, with no interest","40% of the unpaid duty with no interest","A flat N50,000 for each instrument","10% of the unpaid duty plus interest at the prevailing CBN monetary policy rate"],"correctOption":3,"section":"Stamp Duties","explanation":"Section 110 NTAA 2025 makes the person liable to pay 10% of the unpaid duty plus interest at the prevailing CBN monetary policy rate, in addition to the duty itself. Option B borrows the 40% figure from the penalty for failure to deduct withholding tax. Options C and A are not the statutory penalty."}},{"itemId":"c3cf0648-04b7-5276-b642-c91a6e8ef8f7","questionId":"7a39f2bb-bdcc-59d3-9e98-45d777a81839","sourceKey":"bank:TAX-CM223:PQ-006-d","payload":{"prompt":"What is the main legal consequence of leaving a dutiable instrument, such as a company's lease, unstamped under the Nigeria Tax Act 2025?","options":["The lease becomes void and the tenant must vacate","The instrument is valid only if registered with the Corporate Affairs Commission","It cannot be used even in criminal proceedings","It cannot be admitted in evidence in civil court or arbitration proceedings until it is properly stamped"],"correctOption":3,"section":"Stamp Duties","explanation":"An unstamped instrument is not void, but it cannot be relied on as evidence in civil or arbitral proceedings, which leaves the parties unable to enforce it until it is stamped. Option A overstates the effect, because the agreement still exists. Option C is wrong because unstamped instruments may still be admitted in criminal proceedings."}},{"itemId":"04e5d729-01ff-5942-ad1d-81f820818a63","questionId":"773a5cf7-d296-5a7c-92a8-e9b95e99d5ce","sourceKey":"bank:TAX-CM223:PQ-010-a","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, in 2026: a company buys land and buildings for a consideration of N250,000,000. Conveyance on sale is charged at 1.5% ad valorem. What stamp duty is payable, and by whom?","options":["N3,750,000, payable by the buyer (transferee)","N3,750,000, payable by the seller","N7,500,000, payable by the buyer (transferee)","N1,950,000, payable by the buyer (transferee)"],"correctOption":0,"section":"Stamp Duties","explanation":"Duty on a conveyance on sale is N250,000,000 x 1.5% = N3,750,000, and it is borne by the transferee, the buyer who needs a properly stamped title document. Option B has the right amount but the wrong party. Option D uses the 0.78% short-lease rate, and option C uses 3%."}},{"itemId":"fd67a455-aa8e-5ef5-b0a0-c4c884dcd371","questionId":"1afcabe7-5b2c-5d7f-80a1-9fbf26d809f5","sourceKey":"bank:TAX-CM223:PQ-010-b","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, in 2026: a company takes a 20-year lease at an annual rent of N12,000,000. Duty on a lease of more than 7 but not more than 21 years is charged at 3% of the annual rent. What stamp duty is payable?","options":["N7,200,000","N93,600","N360,000","N720,000"],"correctOption":2,"section":"Stamp Duties","explanation":"A 20-year lease falls in the more-than-7-years band, so duty is N12,000,000 x 3% = N360,000. Option B uses the 0.78% rate for leases of up to 7 years. Option D uses 6%, and option A wrongly applies 3% to the total rent for all 20 years."}},{"itemId":"6cd1ae7f-1e70-5d7d-a72a-eda197975abf","questionId":"15094c48-0c28-55f1-b5cd-142dc760a75f","sourceKey":"bank:TAX-CM223:PQ-010-c","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, in 2026: a new company registers with nominal (authorised) share capital of N5,000,000. Capital duty is 0.75% of the share capital. How much capital duty is payable?","options":["N37,500","N3,750","N6,250","N75,000"],"correctOption":0,"section":"Stamp Duties","explanation":"Capital duty is N5,000,000 x 0.75% = N37,500, paid by the company on its authorised share capital. Option D uses 1.5%, option C uses 0.125%, and option B misplaces the decimal (0.075%)."}},{"itemId":"b9665060-a0a5-557a-9278-72998d1ba0f4","questionId":"05ac08f4-ad7a-53df-b53f-c7d6e62a9c05","sourceKey":"bank:TAX-CM223:PQ-010-d","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, in 2026: a bank processes 300,000 electronic transfers of N10,000 or more (none of them salary payments or transfers between a customer's own accounts in the same bank). Each attracts a fixed stamp duty of N50. What total duty is due?","options":["N1,500,000","N15,000,000","N150,000,000","Nil, because electronic transfers are exempt"],"correctOption":1,"section":"Stamp Duties","explanation":"Every qualifying electronic transfer of N10,000 or more attracts N50, so 300,000 x N50 = N15,000,000. Options A and C misplace a zero. Option D is wrong because only transfers below N10,000, salary payments and intra-bank self-transfers are exempt."}},{"itemId":"453daf82-0cbd-5b13-a6c6-68de8a6d3a5d","questionId":"d0ad4b55-34a6-552c-a6d4-d2a31e6396ff","sourceKey":"bank:TAX-CM223:PQ-010-f","payload":{"prompt":"Under the Ninth Schedule to the Nigeria Tax Act 2025, in 2026: stamp duty of N360,000 on a company's lease is paid 3 months late. Under section 110 of the Nigeria Tax Administration Act 2025 the penalty is 10% of the unpaid duty plus interest at the CBN monetary policy rate. Ignoring interest, what is the total of duty plus penalty?","options":["N468,000","N396,000","N504,000","N360,000"],"correctOption":1,"section":"Stamp Duties","explanation":"The penalty is 10% x N360,000 = N36,000, so the duty plus penalty is N396,000, with interest at the CBN monetary policy rate added on top. Option D ignores the penalty. Option A wrongly charges 10% for each month late, and option C applies a 40% penalty, which belongs to failure to deduct withholding tax."}},{"itemId":"4509e946-2e46-5fa0-9059-dc888528e740","questionId":"782a258a-cc29-51c4-a85c-db8b4a9f9229","sourceKey":"bank:TAX-CM223:STD-001","payload":{"prompt":"Under the Nigeria Tax Act 2025 (NTA), Ninth Schedule, a conveyance or transfer on sale of real property attracts ad valorem stamp duty at 1.5% of the consideration, payable by the transferee. Ajah Holdings Ltd buys an office building for N80,000,000. What stamp duty is payable?","options":["N600,000","N12,000,000","N2,400,000","N1,200,000"],"correctOption":3,"section":"Stamp Duties","explanation":"Stamp duty = N80,000,000 x 1.5% = N1,200,000, paid by Ajah Holdings as transferee. Option B misplaces the decimal (15%), and A uses the 0.75% share capital rate."}},{"itemId":"d063014a-68f7-596c-84bd-cedb1fd54b74","questionId":"243f7c3b-0679-5f27-a94d-16ff4711700f","sourceKey":"bank:TAX-CM223:STD-002","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, a lease of not more than 7 years attracts stamp duty at 0.78% of the annual rent, payable by the lessee. Gbagada Clinic Ltd signs a 5-year lease at an annual rent of N6,000,000. What stamp duty is payable?","options":["N180,000","N234,000","N46,800","N468,000"],"correctOption":2,"section":"Stamp Duties","explanation":"Stamp duty = annual rent x 0.78% = N6,000,000 x 0.78% = N46,800. Option B applies the rate to the total rent for 5 years instead of to the annual rent, and A uses the rate for leases above 7 years."}},{"itemId":"7c6b5cf7-e00a-5886-ad51-55933b4a5909","questionId":"1d1e8bd7-d046-5667-9516-e8a967481263","sourceKey":"bank:TAX-CM223:STD-003","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, a lease of more than 7 years (and not more than 21 years) attracts stamp duty at 3% of the annual rent. Oregun Tech Ltd signs a 15-year office lease at an annual rent of N10,000,000. What stamp duty is payable?","options":["N300,000","N78,000","N4,500,000","N600,000"],"correctOption":0,"section":"Stamp Duties","explanation":"Stamp duty = N10,000,000 x 3% = N300,000, based on one year's rent. Option B uses the 0.78% rate for short leases, D uses 6%, a figure from old practice, and C applies 3% to all 15 years of rent."}},{"itemId":"a3a6f4b2-0e48-55f5-8177-da5198ac3bf7","questionId":"2d21eb46-77bf-569e-93b9-8559b3b3c91a","sourceKey":"bank:TAX-CM223:STD-004","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, capital duty on share capital is 0.75% of the nominal share capital. Lekki Ventures Ltd is incorporated with nominal share capital of N20,000,000. What capital duty is payable?","options":["N25,000","N1,500,000","N300,000","N150,000"],"correctOption":3,"section":"Stamp Duties","explanation":"Capital duty = N20,000,000 x 0.75% = N150,000. Option B misplaces the decimal (7.5%), and A uses the 0.125% loan capital rate."}},{"itemId":"daa676f0-4e0c-51a3-adc4-3ce02ffd510c","questionId":"ae66e3e7-dc27-5a41-8e6f-0428fb62a770","sourceKey":"bank:TAX-CM223:STD-005","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, duty on share capital is 0.75% and, when share capital is increased, it is charged on the amount of the increase. Ilupeju Foods Ltd increases its share capital from N10,000,000 to N25,000,000. What duty is payable on the increase?","options":["N187,500","N1,125,000","N262,500","N112,500"],"correctOption":3,"section":"Stamp Duties","explanation":"Duty = (N25,000,000 - N10,000,000) x 0.75% = N15,000,000 x 0.75% = N112,500. Option A charges the full new share capital, which would tax the N10,000,000 a second time."}},{"itemId":"3b365a3d-d982-5f67-85fe-ece7605ea0b9","questionId":"632623b6-08a3-5aa4-8bfa-b740694535b3","sourceKey":"bank:TAX-CM223:STD-006","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, duty on loan capital is 0.125% of the amount secured. Kaduna Textiles Plc raises loan capital (debenture stock) of N120,000,000. What stamp duty is payable?","options":["N450,000","N900,000","N150,000","N1,500,000"],"correctOption":2,"section":"Stamp Duties","explanation":"Duty = N120,000,000 x 0.125% = N150,000. Option D misplaces the decimal (1.25%), and B uses the 0.75% share capital rate."}},{"itemId":"a3996519-a1e7-5377-842f-308e5f883557","questionId":"29efda1e-602a-5935-8edc-b7c9d6bd4586","sourceKey":"bank:TAX-CM223:STD-007","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, a fixed stamp duty of N50 applies to each electronic receipt or transfer of N10,000 or more; under s.184, transfers below N10,000 and salary payments are exempt. In a month, Unity Bank processed 400,000 transfers of N10,000 or more, 150,000 transfers below N10,000, and 50,000 salary payments. What total duty should it collect?","options":["N27,500,000","N20,000,000","N22,500,000","N30,000,000"],"correctOption":1,"section":"Stamp Duties","explanation":"Only the 400,000 qualifying transfers bear duty: 400,000 x N50 = N20,000,000. Option D charges every transfer, C wrongly includes salary payments, and A wrongly includes transfers below N10,000."}},{"itemId":"71b992c2-af8a-51e8-80a8-be455bb6e612","questionId":"287f6667-e030-5c40-a4ef-4d00d150e43e","sourceKey":"bank:TAX-CM223:STD-008","payload":{"prompt":"Under the NTA 2025, a N50 stamp duty applies to each electronic transfer of N10,000 or more, while transfers below N10,000 and transfers between a customer's own accounts in the same bank are exempt (s.184). In one day Amaka sends N9,500 to a friend, N10,000 to a tailor, N250,000 to a landlord, and moves N50,000 between her own two accounts in the same bank. How much stamp duty does she bear?","options":["N50","N200","N150","N100"],"correctOption":3,"section":"Stamp Duties","explanation":"Only the N10,000 and N250,000 transfers qualify (N10,000 meets the 'N10,000 or more' threshold): 2 x N50 = N100. Option C wrongly charges the self-transfer, B charges all four, and A treats N10,000 as below the threshold."}},{"itemId":"24bc55c1-15b3-54dc-8a58-af2b87984256","questionId":"48d182bd-3073-5e49-916f-015a95760134","sourceKey":"bank:TAX-CM223:STD-009","payload":{"prompt":"Under the NTAA 2025, s.110, failure to stamp a dutiable instrument attracts a penalty of 10% of the unpaid duty plus interest at the CBN MPR. Duty of N360,000 was paid 90 days late when the MPR was 27%. Treat the 10% as a one-off charge and compute interest as simple interest on a days/365 basis. What is the total of penalty and interest, to the nearest naira?","options":["N59,967","N23,967","N36,000","N133,200"],"correctOption":0,"section":"Stamp Duties","explanation":"Penalty = 10% x N360,000 = N36,000; interest = N360,000 x 27% x 90/365 = N23,967; total = N59,967. Option C forgets the interest, B forgets the penalty, and D charges a full year of interest."}},{"itemId":"c9a51fca-11aa-5297-a137-73c11e0058d9","questionId":"71cd0217-f9e3-55ec-aa3e-7002f2ea8f04","sourceKey":"bank:TAX-CM223:STD-010","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, a lease of more than 7 years (not more than 21 years) attracts duty of 3% of annual rent, and under the NTAA 2025, s.110, late stamping adds a penalty of 10% of the unpaid duty plus MPR interest. Surulere Stores Ltd stamped a 10-year lease at annual rent of N9,000,000 after the deadline. Ignoring interest, what is the total of duty and penalty?","options":["N297,000","N270,000","N1,170,000","N77,220"],"correctOption":0,"section":"Stamp Duties","explanation":"Duty = N9,000,000 x 3% = N270,000; penalty = 10% x N270,000 = N27,000; total = N297,000. Option C applies the 10% penalty to the rent instead of the duty, and D uses the short-lease rate."}},{"itemId":"14965565-f09a-5078-9b62-af8e2db2dc1e","questionId":"fe84c5b0-c4d7-5714-8daf-7ce0a72cc848","sourceKey":"bank:TAX-CM223:STD-011","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, agreements or contracts not otherwise specified attract a fixed duty of N1,000 each. Ikeja Facility Services Ltd signs 25 separate cleaning service agreements in a month. What total stamp duty is payable?","options":["N250,000","N25,000","N1,000","N2,500"],"correctOption":1,"section":"Stamp Duties","explanation":"Fixed duty = 25 x N1,000 = N25,000; a fixed duty does not depend on the contract value. Option C charges only one agreement, and A misplaces a zero."}},{"itemId":"cf16813c-03bd-58ad-925a-58b70ad5a895","questionId":"6360b1e7-60b7-5f26-9823-32da39a1ff0d","sourceKey":"bank:TAX-CM223:STD-012","payload":{"prompt":"Under the NTA 2025, s.132, the transfer of a mineral asset (such as a mining lease) is dutiable at an ad valorem rate of 2% of the value of the transfer. Jos Tin Ltd acquires a mining lease for N300,000,000. What duty is payable?","options":["N600,000","N9,000,000","N4,500,000","N6,000,000"],"correctOption":3,"section":"Stamp Duties","explanation":"Duty = N300,000,000 x 2% = N6,000,000. Option C uses the 1.5% rate for conveyance of real property, which the NTA does not apply to mineral assets."}},{"itemId":"ca0f5984-d399-562d-8c46-b5d26ae0bf34","questionId":"74a814ea-e2dc-5dcd-aeef-7859be3245b3","sourceKey":"bank:TAX-CM223:STD-013","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, conveyance on sale of real property attracts 1.5% of the consideration and a lease of not more than 7 years attracts 0.78% of the annual rent. In one month Agege Pharma Ltd buys a warehouse for N150,000,000 and signs a 3-year lease of a shop at an annual rent of N4,000,000. What total stamp duty does it pay?","options":["N2,310,000","N2,370,000","N2,281,200","N2,343,600"],"correctOption":2,"section":"Stamp Duties","explanation":"Conveyance duty = N150,000,000 x 1.5% = N2,250,000; lease duty = N4,000,000 x 0.78% = N31,200; total = N2,281,200. Option D applies the lease rate to three years' rent, and A charges 1.5% on the rent as well."}},{"itemId":"0c1d921f-cc4c-5109-acbe-95e3520ece3e","questionId":"c35d8a9a-ed8b-56cf-8757-36a50b450933","sourceKey":"bank:TAX-CM223:STD-014","payload":{"prompt":"Under the NTA 2025, s.125, a chargeable instrument must be stamped not later than 30 days after its execution. Ojota Motors Ltd executed a lease on 5 March 2026. What is the last day for stamping it?","options":["21 April 2026","14 April 2026","4 April 2026","5 March 2026"],"correctOption":2,"section":"Stamp Duties","explanation":"Thirty days after 5 March 2026 is 4 April 2026. Option B reflects the old 40-day period under the repealed Stamp Duties Act, and A confuses stamping with the 21st-day remittance date for deducted taxes."}},{"itemId":"6d3a0c21-ed6f-56b8-9551-36ef9dc16888","questionId":"58e4a7e9-4de4-56ab-8b2c-a5c9c970d8d5","sourceKey":"bank:TAX-CM223:STD-015","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, each electronic receipt or transfer of N10,000 or more attracts N50 stamp duty. A bank processed 50,000 transfers of N20,000 each from Apex Ltd's account. What total duty is due?","options":["N5,000,000","N1,000,000","N2,500,000","N7,500,000"],"correctOption":2,"section":"Stamp Duties","explanation":"The duty is a fixed N50 per qualifying transfer, whatever the amount: 50,000 x N50 = N2,500,000. Options A and D wrongly treat it as a percentage of the amount transferred."}},{"itemId":"39b40e49-8dea-585b-bfb7-e509eb56254d","questionId":"93cb8f33-2b40-5503-83e9-645cbe1658c7","sourceKey":"bank:TAX-CM223:STD-016","payload":{"prompt":"Following the 2025 tax reform, where are the main provisions on stamp duties now found (Nigeria Tax Act 2025 vs older law)?","options":["Chapter Five of the Nigeria Tax Act 2025 (ss.123-142), with rates in the Ninth Schedule","The Nigeria Customs Service Act 2023","Chapter Six of the Nigeria Tax Act 2025, with rates in the First Schedule","The Stamp Duties Act Cap. S8, LFN 2004, as amended"],"correctOption":0,"section":"Stamp Duties","explanation":"The NTA repealed the Stamp Duties Act and moved stamp duties into Chapter Five, with the rates set out in the Ninth Schedule. Option D is the repealed law, and Chapter Six in C deals with VAT."}},{"itemId":"b08482d5-8136-52c7-8249-07ac860d0346","questionId":"54932a8c-7f66-5de2-9571-c95ad8b75f3c","sourceKey":"bank:TAX-CM223:STD-017","payload":{"prompt":"Under the Nigeria Tax Act 2025, Chapter Five, a tax charged on written instruments (documents) such as conveyances, leases and agreements, rather than directly on income or consumption, is known as:","options":["Stamp duty","Withholding tax","Capital gains tax","Value Added Tax"],"correctOption":0,"section":"Stamp Duties","explanation":"Stamp duty is charged on instruments, and payment is shown by stamping or electronic tagging of the document. VAT (D) is a tax on consumption, and WHT (B) is an advance income tax."}},{"itemId":"a454b7f7-739e-52f5-a611-00b2efb68c67","questionId":"91df09c3-a5fc-5234-8979-91c8264a8ac6","sourceKey":"bank:TAX-CM223:STD-018","payload":{"prompt":"Under the NTA 2025, s.125, within what period must a chargeable instrument be stamped?","options":["By the 21st day of the following month","Within 12 months of execution","Within 40 days of first execution","Not later than 30 days after its execution"],"correctOption":3,"section":"Stamp Duties","explanation":"Section 125 requires stamping within 30 days after execution. Option C was the period under the repealed Stamp Duties Act, and A is the remittance date for deducted taxes."}},{"itemId":"f4d46a80-1ca4-545f-8ab0-e1914a757346","questionId":"2bfa8142-5b45-5621-9a65-921fdf79b2fa","sourceKey":"bank:TAX-CM223:STD-020","payload":{"prompt":"Under the NTA 2025, s.126, what is the main consequence in civil proceedings of an instrument that has not been duly stamped?","options":["It becomes void and unenforceable for all purposes","It is not admissible in evidence","It is automatically stamped by the court at double duty","It is admissible only if the parties agree"],"correctOption":1,"section":"Stamp Duties","explanation":"An unstamped instrument cannot be admitted in evidence in civil proceedings until it is stamped, which is a strong incentive to comply. Option A goes too far: the document is not void, and it can be stamped later (with penalties) and then relied on."}},{"itemId":"d580e78f-d960-5401-87bc-45b0713e6a6f","questionId":"fcab724f-9be1-5f33-920b-98df1d829975","sourceKey":"bank:TAX-CM223:STD-021","payload":{"prompt":"Under the NTA 2025, s.126, in which type of proceedings may an unstamped instrument still be admitted in evidence?","options":["Criminal proceedings","Arbitration proceedings","Civil proceedings in the High Court","Tax Appeal Tribunal proceedings on stamp duty"],"correctOption":0,"section":"Stamp Duties","explanation":"The bar on unstamped instruments applies to civil and similar proceedings, but such an instrument may be admitted in criminal proceedings. Options C, B and D are all proceedings where the bar applies."}},{"itemId":"f303cfc9-3773-5ca2-a57a-3c76e1051009","questionId":"53fac885-936b-5ab2-b019-f1a614d4ffa5","sourceKey":"bank:TAX-CM223:STD-022","payload":{"prompt":"Under the NTA 2025, s.124, which of the following is a recognised way of denoting that stamp duty has been paid?","options":["Electronic or digital tagging","Endorsement by a notary public","A WHT credit certificate","Registration of the document at the CAC"],"correctOption":0,"section":"Stamp Duties","explanation":"Section 124 recognises modern methods such as electronic or digital tagging and electronic receipts, alongside adhesive stamps and dies. The other options are not ways of denoting duty."}},{"itemId":"31ebaf1c-286b-5665-a406-e3bb0666d8c7","questionId":"386b069d-01e3-5224-8af5-9945bdd30928","sourceKey":"bank:TAX-CM223:STD-024","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, an 'ad valorem' stamp duty is one that is:","options":["Charged only on instruments executed abroad","Calculated as a percentage of the value or consideration in the instrument","Payable only by the State government","A fixed amount regardless of the value involved"],"correctOption":1,"section":"Stamp Duties","explanation":"Ad valorem means 'according to value', so the duty rises with the consideration, as with 1.5% on a conveyance. Option D describes a fixed duty, such as N1,000 on an unspecified agreement."}},{"itemId":"93a39e9e-b61b-5592-a507-65e8d9cca651","questionId":"4e4733a8-4209-5853-82c6-9b059d3b8a11","sourceKey":"bank:TAX-CM223:STD-025","payload":{"prompt":"Under the NTA 2025, Ninth Schedule, which of these attracts a FIXED (not ad valorem) stamp duty?","options":["Loan capital raised by a company","A lease of office space","An agreement or contract not otherwise specified","A conveyance on sale of land"],"correctOption":2,"section":"Stamp Duties","explanation":"Agreements or contracts not expressly specified carry a fixed N1,000 duty, whatever their value. Conveyances, leases and loan capital (options D, B, A) are charged as a percentage of value or rent."}},{"itemId":"29ff3e4d-ff9c-59cb-aa7d-9cf5f8c22324","questionId":"d3a26c3a-9914-5fc4-909d-ee9d0cdbc5bb","sourceKey":"bank:TAX-CM223:STD-026","payload":{"prompt":"Under the NTA 2025, who is generally liable to pay stamp duty on a lease?","options":["The lessor","The estate agent","The lessee","The State government"],"correctOption":2,"section":"Stamp Duties","explanation":"The NTA follows the principle that the party who benefits pays, so the lessee (tenant) pays duty on a lease, just as the buyer pays on a conveyance. Option A is the landlord, who is not the liable party."}},{"itemId":"f2f38ad3-92e3-56ae-98ed-ab78fbd46727","questionId":"4cf4e4e8-5558-53d3-bc42-eab05077d0c8","sourceKey":"bank:TAX-CM223:STD-027","payload":{"prompt":"Under the NTA 2025, who pays the stamp duty on a conveyance on sale of a building?","options":["Both parties equally","The transferee (buyer)","The transferor (seller)","The lawyer who prepares the deed"],"correctOption":1,"section":"Stamp Duties","explanation":"The NTA puts the duty on the person who benefits, which in a sale is the buyer (transferee). Option C is the seller, who receives the price and does not bear the duty."}},{"itemId":"7e2bed56-4723-5569-8c94-40473bd76c3b","questionId":"ac55bd0d-f088-5438-b569-54e529b33797","sourceKey":"bank:TAX-CM223:STD-028","payload":{"prompt":"Under the NTA 2025, s.201, 'conveyance on sale' is limited to transfers of:","options":["Movable goods only","Intangible assets only","Any property, including shares and intellectual property","Real property"],"correctOption":3,"section":"Stamp Duties","explanation":"The NTA defines conveyance on sale as the transfer of real property, so transfers of intangibles and other business assets no longer attract conveyance duty. Option C reflects the wider position under the repealed Act."}},{"itemId":"293b6c39-e56c-5fde-845f-39a903d85a94","questionId":"37377cc2-49fb-5631-9b8e-bf1024efa433","sourceKey":"bank:TAX-CM223:STD-029","payload":{"prompt":"Under the NTA 2025, from 1 January 2026, who bears the N50 stamp duty on an electronic transfer of N10,000 or more?","options":["The Central Bank of Nigeria","The sender (transferor)","The recipient","The bank, from its own funds"],"correctOption":1,"section":"Stamp Duties","explanation":"The N50 duty, which replaced the Electronic Money Transfer Levy, is now deducted from the sender's account. Option C was the earlier practice under the EMTL, when the receiving account was charged."}},{"itemId":"0f8d6804-88c6-51ff-8acd-519aa22f13a2","questionId":"32c28dda-64ac-5ecd-aff0-35fce8b89f40","sourceKey":"bank:TAX-CM223:STD-030","payload":{"prompt":"Under the NTA 2025, s.184, which of the following electronic transactions is NOT exempt from the N50 stamp duty?","options":["A N15,000 transfer to a supplier at another bank","A transfer of N8,000","A salary payment of N400,000","A transfer between two accounts of the same customer in the same bank"],"correctOption":0,"section":"Stamp Duties","explanation":"A N15,000 transfer to a third party meets the N10,000 threshold and has no exemption, so N50 applies. Transfers below N10,000, salary payments and intra-bank self-transfers (options B, C, D) are all exempt."}},{"itemId":"7a2e8f75-f5af-54e2-96df-ec132e102fcb","questionId":"0ab0e8e5-3854-517d-b2fd-73ea0bba48c6","sourceKey":"bank:TAX-CM223:STD-031","payload":{"prompt":"Under the NTA 2025, s.184, which of the following is exempt from stamp duty?","options":["A mining lease transfer","A conveyance of a factory to a company","Documents relating to the transfer of stocks and shares","A 10-year lease of a warehouse"],"correctOption":2,"section":"Stamp Duties","explanation":"The exemption for documents relating to the transfer of stocks and shares carried over from the old Act into s.184. The conveyance, lease and mineral asset transfer (options B, D, A) are all dutiable."}},{"itemId":"218132fb-0626-5c11-84a1-789f6ca44a8c","questionId":"b4db4531-a7d7-533f-b367-68ae2167126e","sourceKey":"bank:TAX-CM223:STD-032","payload":{"prompt":"Under the NTA 2025, s.184, which of these instruments is exempt from stamp duty?","options":["Instruments relating to the transfer of Government stocks or funds","An agreement for cleaning services","A conveyance of land to a bank","A loan agreement between two companies"],"correctOption":0,"section":"Stamp Duties","explanation":"Transfers of Government or legislative stocks or funds are listed exemptions. The other instruments (D, B, C) are ordinary dutiable instruments."}},{"itemId":"3f9c6661-525b-57e6-8c47-e1b180a5ae80","questionId":"66f825c4-5130-5e5e-8373-055a6359a3a3","sourceKey":"bank:TAX-CM223:STD-033","payload":{"prompt":"Under the NTA 2025 and NTAA 2025 division of stamp duty jurisdiction, which instrument falls under the State Internal Revenue Service rather than the Nigeria Revenue Service?","options":["Memorandum and Articles of a new company","A tenancy agreement between two private individuals","A debenture issued by a company","Electronic transfer duty collected by banks"],"correctOption":1,"section":"Stamp Duties","explanation":"Stamp duties on instruments executed by individuals, such as private tenancies, are State matters, while instruments executed by companies go to the NRS. Options C, A and D are all federal."}},{"itemId":"74812b20-2b55-5a90-a573-a1b3f004217a","questionId":"c3965d01-0ff0-5bbb-88e9-332e22b11504","sourceKey":"bank:TAX-CM223:STD-034","payload":{"prompt":"Under the NTA 2025, s.142, Ikoyi Ltd transfers a building to Lekki Ltd in exchange for 10,000 cars instead of cash. How is the stamp duty value determined?","options":["By the original cost of the building to Ikoyi Ltd","By reference to the fair market value of the non-monetary consideration","Nil duty, because no money changed hands","At a fixed duty of N1,000"],"correctOption":1,"section":"Stamp Duties","explanation":"The NTA has a specific provision for non-monetary consideration such as barter, valuing it at fair market value. Option C reflects the loophole the provision closes."}},{"itemId":"df9eaffb-1987-5d2a-95c7-a3ff22fcb3d1","questionId":"15ce26cb-0a38-55a0-8129-e842e859f467","sourceKey":"bank:TAX-CM223:STD-035","payload":{"prompt":"Under the NTA 2025, a property sale is documented in a sale agreement, a deed of assignment and a receipt, all for the same transaction. How is stamp duty applied?","options":["Only the receipt is dutiable","None is dutiable because they duplicate each other","Only one instrument bears ad valorem duty; the others are stamped at a fixed duty","All three instruments bear full ad valorem duty"],"correctOption":2,"section":"Stamp Duties","explanation":"Where several instruments cover the same transaction, the NTA charges ad valorem duty on one and a fixed duty on the others, which avoids taxing one deal several times. Option D is the double charge the rule avoids."}},{"itemId":"f3f4730d-5628-5fa1-9784-78c0f51b4f7e","questionId":"b32843a8-0c9b-53a0-8abf-78f39a409239","sourceKey":"bank:TAX-CM223:STD-036","payload":{"prompt":"Under the NTA 2025, which rate structure applies to leases in the Ninth Schedule for a lease of not more than 7 years?","options":["A fixed N1,000","0.78% of the annual rent","3% of the annual rent","1.5% of the total rent for the term"],"correctOption":1,"section":"Stamp Duties","explanation":"Short leases of up to 7 years attract 0.78% of the annual rent. Option C is the rate for longer leases, and D confuses the lease rate with the conveyance rate."}},{"itemId":"d1e75ae1-36bc-5411-a6c4-4320d00e48d1","questionId":"e3aa17e9-db7a-5ce9-8d71-54f6900480a5","sourceKey":"bank:TAX-CM223:STD-037","payload":{"prompt":"Under the NTA 2025, which tax authority has jurisdiction over stamp duties on instruments executed by companies?","options":["The Corporate Affairs Commission","The Nigeria Revenue Service (NRS)","The State Internal Revenue Service","The Local Government revenue committee"],"correctOption":1,"section":"Stamp Duties","explanation":"Stamp duties on instruments executed by companies are federal and collected by the NRS. State IRSs (C) handle instruments executed by individuals, and the CAC (A) registers companies but does not collect stamp duty."}},{"itemId":"1605b8e4-8851-5791-a7f7-f93f5ffa9a20","questionId":"9f3609d3-c6f5-5d9c-b001-e0ee75b75465","sourceKey":"bank:TAX-CM223:STD-038","payload":{"prompt":"What happened to the Electronic Money Transfer Levy (EMTL) under the Nigeria Tax Act 2025?","options":["It was moved into withholding tax at 2%","It was abolished with no replacement","It was converted into a 0.5% VAT on all transfers","It was replaced by a N50 stamp duty on electronic transfers of N10,000 or more under the NTA 2025"],"correctOption":3,"section":"Stamp Duties","explanation":"The EMTL introduced by the Finance Acts was replaced by a N50 stamp duty in the NTA's Ninth Schedule on electronic receipts or transfers of N10,000 or more. The other options describe changes that did not happen."}},{"itemId":"e9b34c1d-3ed5-5bc6-88fb-3599ac144f4d","questionId":"a474f6d9-085b-59fc-980f-15d448212646","sourceKey":"bank:TAX-CM223:STD-039","payload":{"prompt":"Under the NTA 2025, s.132, how is the transfer of a mineral asset (such as a mining licence or lease) treated for stamp duty?","options":["It is dutiable at 2% of the value of the transfer","It is exempt as a government licence","It is charged at the 1.5% conveyance rate","It attracts only a fixed N1,000 duty"],"correctOption":0,"section":"Stamp Duties","explanation":"The NTA has a specific provision on mineral assets, charging 2% ad valorem on the transfer value. Option C is wrong because conveyance duty now applies only to real property."}},{"itemId":"4ed399fd-14b0-5f55-b5c5-1216b3ad1444","questionId":"0da431ad-a371-5f1d-a761-c57f8c3224fd","sourceKey":"bank:TAX-CM223:STD-040","payload":{"prompt":"Which law did the NTA 2025 repeal in consolidating stamp duties into Chapter Five?","options":["The Companies and Allied Matters Act 2020","The Nigeria Customs Service Act 2023","The Land Use Act 1978","The Stamp Duties Act, Cap. S8, LFN 2004"],"correctOption":3,"section":"Stamp Duties","explanation":"The NTA repealed the Stamp Duties Act (as amended by the Finance Acts) and moved its substance into Chapter Five and the Ninth Schedule. The other laws were not repealed by the NTA."}},{"itemId":"cbbd90b7-8ff0-5c9d-ad25-46388c7464eb","questionId":"605672b8-8454-5231-b2ef-ada0c2876fea","sourceKey":"bank:TAX-CM223:PQ-011-a","payload":{"prompt":"Cresta Beverages Ltd imports spirits from Scotland in 2026 with a CIF value of $800,000. The exchange rate is $1 = N1,700. The ECOWAS Common External Tariff rate on the spirits is 35% of the CIF value. What is the import duty payable?","options":["N476,000,000","N280,000","N136,000,000","N1,836,000,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"Customs value is CIF converted to naira: $800,000 x N1,700 = N1,360,000,000, and duty at 35% is N476,000,000. Option B forgets to convert to naira. Option C uses a 10% band, and option D is the duty-paid value (CIF plus duty), not the duty."}},{"itemId":"a5d62b05-acc6-51b1-ab97-e45962669aa0","questionId":"34dd375b-4e77-51cf-9819-bb6bca05a2ae","sourceKey":"bank:TAX-CM223:PQ-011-b","payload":{"prompt":"Cresta Beverages Ltd imports spirits from Scotland in 2026 with a CIF value of $800,000. The exchange rate is $1 = N1,700. Import duty is 35% of CIF. Taking the VAT base on importation as CIF plus import duty, and VAT at 7.5% under the Nigeria Tax Act 2025, what VAT is payable on importation?","options":["N35,700,000","N137,700,000","N102,000,000","N183,600,000"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"CIF is N1,360,000,000 and duty is N476,000,000, so the VAT base is N1,836,000,000 and VAT at 7.5% is N137,700,000. Option C charges VAT on CIF alone, leaving out the duty. Option A charges VAT on the duty only, and option D uses 10%."}},{"itemId":"56ebf4aa-be2b-5a6e-8bca-359b7c37773e","questionId":"5e2bbcb3-f4b5-57c6-8156-8b1dc2727e51","sourceKey":"bank:TAX-CM223:PQ-011-c","payload":{"prompt":"Cresta Beverages Ltd imports spirits from Scotland in 2026 with a CIF value of $800,000. The exchange rate is $1 = N1,700. The ECOWAS Trade Levy is 0.5% of the CIF value. What is the levy?","options":["N6,800,000","N2,380,000","N68,000,000","N13,600,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"The levy is N1,360,000,000 x 0.5% = N6,800,000. Option C uses 5% and option D uses 1%. Option B wrongly applies 0.5% to the import duty instead of the CIF value."}},{"itemId":"7971fce4-72dc-56c3-88bb-8bffb95ef437","questionId":"fbb33cc9-75ca-5856-ba78-9752e3e3ac93","sourceKey":"bank:TAX-CM223:PQ-011-d","payload":{"prompt":"Cresta Beverages Ltd exports beer made partly from imported inputs on which it paid import duty. Under the Nigeria Customs Service Act 2023, what is manufacturing drawback?","options":["A refund of the import duty paid on imported inputs used in making goods that are later exported","A VAT credit given only to exporters","A refund of company income tax on export profits","An extra excise duty charged on exported beer"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"Manufacturing drawback refunds import duty on imported inputs in proportion to their content in goods that are exported, so exporters are not burdened with duty on materials that leave the country inside their products. Option D is the opposite of a relief. Options B and C confuse drawback with VAT and income tax rules."}},{"itemId":"37b5e1f0-ef08-51b2-81e0-d77a8e1fed75","questionId":"112c8f93-def7-5f2d-82cd-274d4b1480c7","sourceKey":"bank:TAX-CM223:PQ-011-e","payload":{"prompt":"Which statement best describes excise duty as it applies to beer brewed locally by Cresta Beverages Ltd?","options":["A tax on the brewery's annual profits","A tax charged only when the beer is exported","A duty on imported goods, charged on their CIF value at the port","A duty on goods manufactured in Nigeria, charged on production at the factory, often as a specific amount per litre plus an ad valorem percentage"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Excise duty is a tax on selected locally manufactured goods such as beer, spirits and tobacco, charged at the factory gate, typically as a specific rate per unit plus a percentage of value. Option C describes customs import duty. Option A describes company income tax, and option B is wrong because exports are generally relieved rather than targeted."}},{"itemId":"cdf4150d-eb75-5f27-880f-e5fa6e1a02ad","questionId":"9efac3a6-1427-5a47-956f-3bced529611b","sourceKey":"bank:TAX-CM223:CUS-001","payload":{"prompt":"Under the Nigeria Customs Service Act 2023, import duty in Nigeria is computed on the customs value of goods, which in practice is the CIF value. What does CIF stand for?","options":["Cost, Inspection and Fees","Customs, Insurance and Freight","Cost, Insurance and Freight","Cost, Interest and Freight"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"CIF means Cost, Insurance and Freight: the price of the goods plus the insurance and freight needed to bring them to the Nigerian port. Option A replaces insurance with inspection and fees, which are separate charges, while Option B wrongly puts customs into the value on which customs duty is itself charged."}},{"itemId":"8cadf6e7-6100-5903-b96b-0f6cbedaf8ac","questionId":"47666bd9-1f29-5515-b75c-8b3c2f64ecf5","sourceKey":"bank:TAX-CM223:CUS-002","payload":{"prompt":"Under the Nigeria Customs Service Act 2023 framework, on which value is import duty normally computed for goods imported into Nigeria?","options":["The expected retail selling price in Nigeria","The ex-factory price of the goods in Nigeria","The CIF value of the goods, converted to naira","The FOB value of the goods only"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Import duty is charged on the CIF value, that is the cost of the goods plus insurance and freight to Nigeria, converted to naira. Option D leaves out insurance and freight, and Option B is the base for excise duty on locally manufactured goods, not for import duty."}},{"itemId":"b06295d8-8669-512c-b0d2-c804cfa2f31f","questionId":"2a09f62d-5c9f-56a7-ada1-4d835f2c5145","sourceKey":"bank:TAX-CM223:CUS-003","payload":{"prompt":"Nigeria applies the ECOWAS Common External Tariff (CET) to classify import duty rates. Which set correctly lists the five CET duty bands?","options":["5%, 7.5%, 10%, 20% and 30%","0%, 5%, 10%, 20% and 35%","0%, 5%, 10%, 15% and 25%","0%, 10%, 20%, 30% and 40%"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"The ECOWAS CET has five bands: 0%, 5%, 10%, 20% and 35%, rising from essential inputs to finished goods the region wants to protect. Option C invents a 15% and 25% band, and Option A confuses the VAT rate of 7.5% with a tariff band."}},{"itemId":"8080d0c5-c151-5bc5-9216-42ed8cb82ca8","questionId":"e7a57676-9de4-5347-94b8-125fac4ae587","sourceKey":"bank:TAX-CM223:CUS-004","payload":{"prompt":"Which of the following is NOT one of the five ECOWAS Common External Tariff bands applied to imports into Nigeria?","options":["35%","15%","5%","20%"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"The five CET bands are 0%, 5%, 10%, 20% and 35%, so 15% is not a band. Options A, C and D are all genuine CET rates, with 35% being the highest band."}},{"itemId":"defc43e8-92f1-5c9c-866a-2214c2bd3aea","questionId":"6f457e45-e0ea-546f-812b-358170ed9ceb","sourceKey":"bank:TAX-CM223:CUS-005","payload":{"prompt":"An importer in Apapa is told that the highest ECOWAS Common External Tariff band applies to his consignment. What import duty rate is that?","options":["20% of the CIF value","35% of the CIF value","50% of the CIF value","35% of the FOB value"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"The top CET band is 35%, and like every band it is applied to the CIF value. Option A is the next band down, and Option D uses the wrong base because duty is not charged on FOB value alone."}},{"itemId":"e898ff1f-5798-5676-aca5-ad8930a578a7","questionId":"effa6748-48d5-5a58-b454-c18461be0ac1","sourceKey":"bank:TAX-CM223:CUS-006","payload":{"prompt":"A duty charged on goods manufactured within Nigeria, imposed at the ex-factory stage on items such as beer, spirits, tobacco and sugar-sweetened beverages, is called:","options":["Import duty","Excise duty","Value added tax","Duty drawback"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Excise duty is levied on locally manufactured goods at the ex-factory gate. Option A applies to goods brought into Nigeria from abroad, Option C is a general consumption tax on most supplies, and Option D is a refund of duty, not a charge."}},{"itemId":"89b4dbdb-1616-55b6-872f-c75c899abc91","questionId":"15c06efd-d793-5f89-a637-07a0000c9ad8","sourceKey":"bank:TAX-CM223:CUS-007","payload":{"prompt":"Which of the following best describes excise duty in Nigeria?","options":["A duty on all goods entering Nigeria, charged on CIF value","A refund of duty paid on imported inputs used for exports","A duty on selected goods manufactured in Nigeria, charged on quantity and/or ex-factory value","A tax on every supply of goods and services, charged at 7.5%"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Excise duty targets selected locally manufactured goods and is charged per unit, as a percentage of the ex-factory price, or both. Option A describes import duty, Option D describes VAT and Option B describes duty drawback."}},{"itemId":"4a0df76c-3ea3-5d0f-8506-c3921e2adac9","questionId":"6ef558e9-4ccb-5f62-87c6-bb15be0f8352","sourceKey":"bank:TAX-CM223:CUS-008","payload":{"prompt":"What is the main difference between import duty and excise duty in Nigeria?","options":["Import duty is charged on goods brought into Nigeria; excise duty is charged on goods manufactured in Nigeria","Import duty is charged on services; excise duty is charged on goods","Import duty is charged at 7.5%; excise duty is charged at 35%","Import duty is charged on exports; excise duty is charged on imports"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"The two duties are separated by where the goods come from: import duty falls on imports at CIF value, while excise duty falls on local production at the ex-factory stage. Option B is wrong because no customs duty is charged on services, and Option C confuses the VAT rate and the top CET band with the duties themselves."}},{"itemId":"cbadcb56-3b37-5891-8800-6a36389f0907","questionId":"50339061-6b16-5244-abe1-21b5a3d800a9","sourceKey":"bank:TAX-CM223:CUS-009","payload":{"prompt":"In excise duty, what is a 'specific' rate?","options":["A rate fixed separately for each manufacturer by negotiation","A percentage of the CIF value of imported goods","A fixed amount charged per unit of quantity, such as per litre or per stick","A percentage of the ex-factory value of the goods"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"A specific rate is a fixed naira amount per unit, for example per litre of beer or per stick of cigarettes, regardless of price. Option D describes an ad valorem rate, and Option B describes how import duty is charged."}},{"itemId":"e6e383ab-8cf8-5a27-9cae-7e97fbe58e86","questionId":"e15faaf6-180a-5df9-8e12-26de8adf677b","sourceKey":"bank:TAX-CM223:CUS-010","payload":{"prompt":"An excise rate expressed as a percentage of the ex-factory price of the goods is known as:","options":["An ad valorem rate","A flat rate per unit","A specific rate","A drawback rate"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"Ad valorem means 'according to value', so the duty rises with the ex-factory price. Options B and C both describe a fixed amount per litre or per stick, which does not change with price."}},{"itemId":"594d8233-5453-56b5-b8c2-e4f2c3fbba3a","questionId":"bd8766bd-e979-52b1-8b6a-74803b44da92","sourceKey":"bank:TAX-CM223:CUS-011","payload":{"prompt":"Excise on beer is charged as a fixed amount per litre plus a percentage of the ex-factory price. Such a duty is best described as:","options":["A compound duty, combining a specific and an ad valorem element","A customs duty charged on the CIF value","A purely ad valorem duty charged on value only","A purely specific duty charged per litre only"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"When a per-unit amount and a percentage of value are both charged on the same product, the duty is compound (mixed). Options C and D each capture only one of the two elements, and Option B applies to imports, not local brewing."}},{"itemId":"e48048d3-6178-5e3a-8ff1-2f76733f3201","questionId":"740a58e8-cbdb-54dd-8110-58a3edc47a0f","sourceKey":"bank:TAX-CM223:CUS-012","payload":{"prompt":"Which of the following products is most typically subject to excise duty in Nigeria?","options":["Legal services supplied by a law firm","Sugar-sweetened beverages produced by a local bottler","Imported medical equipment","Unprocessed yams sold by a farmer"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Sugar-sweetened beverages appear in the Nigerian excise schedule alongside beer, spirits, wine and tobacco. Option D is unprocessed farm produce, Option A is a service, and Option C is an import that bears customs charges rather than excise on local manufacture."}},{"itemId":"c3f1d08d-8724-5a88-bbc5-d623576b60f8","questionId":"1613c371-6a07-5af1-a3ff-7d0e69b21790","sourceKey":"bank:TAX-CM223:CUS-013","payload":{"prompt":"Which of the following is NOT an excisable product in the Nigerian excise schedule?","options":["Beer and stout","Cigarettes","Fresh tomatoes sold in a local market","Spirits such as gin and vodka"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Excise in Nigeria targets manufactured products such as beer, spirits, wine, tobacco and sugar-sweetened beverages, not fresh farm produce. Options A, B and D are all listed excisable products."}},{"itemId":"c1938328-885a-50a6-a6e4-f8bc88bbc494","questionId":"e3964a66-4793-5132-93d0-9ff757661f01","sourceKey":"bank:TAX-CM223:CUS-014","payload":{"prompt":"What is 'duty drawback' under the Nigeria Customs Service Act 2023 framework?","options":["A penalty for importing goods without a pre-arrival declaration","A discount on excise for manufacturers who produce above a set volume","An additional duty charged on luxury imports","A refund of import duty paid on goods that are re-exported or used to make goods that are exported"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Duty drawback gives back import duty when the imported goods, or the inputs inside exported products, leave Nigeria, so exports are not burdened with Nigerian import duty. Option C describes a surcharge, which increases duty rather than refunding it."}},{"itemId":"a734dd5a-39a8-58f3-82ec-021be1fd4dc9","questionId":"17a95be7-9914-5ca2-ab2b-15a6db6cb407","sourceKey":"bank:TAX-CM223:CUS-015","payload":{"prompt":"Kano Traders Ltd imported a consignment, paid import duty, and later re-exported the entire consignment unused. Under the Nigeria Customs Service Act 2023 drawback rules, how much of the import duty can be reclaimed?","options":["None, because duty is never refundable","50% of the import duty paid","Only the VAT paid on importation","100% of the import duty paid"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Goods imported and re-exported unused qualify for a 100% drawback of the duty paid on them. Option B has no basis in the drawback rules, and Option A ignores the drawback scheme altogether."}},{"itemId":"72bfbd80-ce01-55e0-9764-3bef9db95ae3","questionId":"643c331f-756c-5c79-b3d7-7bba3c47527d","sourceKey":"bank:TAX-CM223:CUS-016","payload":{"prompt":"Under the Nigeria Customs Service Act 2023 framework, a 'manufacturing drawback' refunds:","options":["VAT charged on locally purchased raw materials","Excise duty paid on goods sold in Nigeria","All import duty paid by a manufacturer in the year, whether or not it exports","Import duty on imported inputs in proportion to their content in manufactured goods that are exported"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Manufacturing drawback is proportionate: only the duty on the imported inputs that end up in exported products is refunded. Option C ignores the export link, and Options A and B concern excise and VAT rather than import duty."}},{"itemId":"be694952-e6ed-5bc1-9e3c-0162bb5c5246","questionId":"d3bbeaa7-6c18-569e-a61a-01ab390f4599","sourceKey":"bank:TAX-CM223:CUS-017","payload":{"prompt":"Which law is the primary legislation for the administration and computation of customs (import) duty in Nigeria after the 2025 tax reforms?","options":["The Nigeria Tax Act 2025","The Value Added Tax Act","The Nigeria Revenue Service (Establishment) Act 2025","The Nigeria Customs Service Act 2023"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Customs duty was not absorbed into the Nigeria Tax Act 2025; it remains governed by the Nigeria Customs Service Act 2023 with ECOWAS CET rates. Option A consolidated income tax, VAT and stamp duties but not customs duty, and Option B has been repealed."}},{"itemId":"8303e60b-2002-5134-aeb3-485fefe05ece","questionId":"03fe1698-92c1-55a7-8922-76159bd55cc2","sourceKey":"bank:TAX-CM223:CUS-018","payload":{"prompt":"The Nigeria Customs Service Act 2023 repealed which earlier law that had governed customs and excise administration in Nigeria?","options":["The Customs and Excise Management Act (CEMA)","The Companies Income Tax Act","The Value Added Tax Act","The Stamp Duties Act"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"The Nigeria Customs Service Act 2023 replaced the Customs and Excise Management Act (CEMA), Cap. C45, as the main customs statute. Options B, C and D were repealed by the Nigeria Tax Act 2025, not by the customs law."}},{"itemId":"274dce7d-0da3-5a8b-9e82-bf7492f9673e","questionId":"8ba18345-2639-53b0-94fc-ce8130ad752c","sourceKey":"bank:TAX-CM223:CUS-019","payload":{"prompt":"Which of the following statements about customs duty after the 2025 tax reforms is NOT correct?","options":["Import duty rates follow the ECOWAS Common External Tariff","Customs duty remains governed by the Nigeria Customs Service Act 2023","Customs duty was absorbed into the Nigeria Tax Act 2025 and is now charged under it","Import duty is charged on the CIF value of imported goods"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"The 2025 reforms consolidated income tax, VAT and stamp duties into the Nigeria Tax Act 2025, but customs duty stayed under the Nigeria Customs Service Act 2023. Options A, B and D are all correct statements, so they are not the answer."}},{"itemId":"56b0a5d3-0f87-587c-8590-0a5d9c2d93b7","questionId":"80c2a1fa-4c02-5ec2-8d1b-2170ecda8a5b","sourceKey":"bank:TAX-CM223:CUS-020","payload":{"prompt":"Lagos Design Studio Ltd pays a firm in London for architectural drawings delivered by email. Which of the following can NEVER be charged on this import of a service?","options":["Withholding tax","Customs import duty","Value added tax","Stamp duty on a written contract for the work"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Customs duty is charged on goods at their CIF value, so there is no customs duty on an imported service. VAT, withholding tax and stamp duty in Options A, C and D may still need to be considered under their own rules, so they cannot be ruled out in the same way."}},{"itemId":"fb5d867b-790e-5c2f-9d33-6feca68376c1","questionId":"0a1ca0ed-90e0-5ba5-85e1-230711ebf5ec","sourceKey":"bank:TAX-CM223:CUS-021","payload":{"prompt":"Under the Nigeria Customs Service Act 2023, what is the primary method of valuing imported goods for customs purposes?","options":["A value fixed by the importer in a sworn declaration, without reference to the price","Transaction value: the price actually paid or payable for the goods when sold for export to Nigeria","The value of identical goods imported in the last five years","The retail price of similar goods in Lagos markets"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Customs valuation starts with the transaction value, the price actually paid or payable, following the WTO approach; other methods are fall-backs. Option C is a secondary method used only when transaction value cannot be used, and Option D would tax the importer's later mark-up."}},{"itemId":"a5941a68-d94b-5c6c-909a-ba9871c114b7","questionId":"c65ca342-4032-5263-8dea-bb9af67d228e","sourceKey":"bank:TAX-CM223:CUS-022","payload":{"prompt":"An importer buys goods from its parent company abroad, and the relationship has clearly influenced the invoice price. Under the Nigeria Customs Service Act 2023, which valuation approach should Customs move to?","options":["A value equal to the importer's expected selling price minus VAT","The invoice price, because transaction value always applies","The FOB value with no adjustment","The value of identical or similar goods imported at about the same time"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Transaction value cannot be used where the buyer and seller are related and the relationship has influenced the price, so Customs falls back on the value of identical or similar goods. Option B ignores that exception, and Option C still relies on the influenced price."}},{"itemId":"c1b3c672-d183-596a-b4b8-16df425d4d88","questionId":"e5272d09-7653-590d-b1f2-5c8bb4337fa0","sourceKey":"bank:TAX-CM223:CUS-023","payload":{"prompt":"Why is VAT on an imported item normally higher than 7.5% of its CIF value?","options":["Because the VAT base on importation includes the import duty as well as the CIF value","Because VAT on imports is charged at 10% instead of 7.5%","Because VAT on imports is charged on the retail price","Because VAT on imports is charged on the FOB value plus a 20% mark-up"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"VAT on imported goods is computed on the CIF value plus import duty, so it is VAT charged partly on the duty. Option B is wrong because the rate is still 7.5%, and Options C and D invent bases that the framework does not use."}},{"itemId":"cc09a311-79a7-585b-80c6-068a0df22f8f","questionId":"09d03379-f1f0-51a5-a3c6-9e2a5729b138","sourceKey":"bank:TAX-CM223:CUS-024","payload":{"prompt":"The rationale usually given for excise duty on products such as sugar-sweetened beverages and tobacco is that it:","options":["Protects local manufacturers from competing imported products","Refunds import duty to exporters of manufactured goods","Raises revenue while discouraging consumption of goods considered harmful","Replaces VAT on those products so they are not taxed twice"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Excise is often called a 'sin tax': it raises revenue and, by raising the price, discourages consumption of harmful products. Option A is the protective role of import tariffs, and Option D is wrong because VAT still applies alongside excise."}},{"itemId":"86c29913-77a1-59a3-9d6c-9e8dc2359ae4","questionId":"9912e380-bdcc-5679-90c2-d3cdedca6ab0","sourceKey":"bank:TAX-CM223:CUS-025","payload":{"prompt":"For a locally manufactured excisable product, the ad valorem element of excise duty is calculated on:","options":["The CIF value of the goods","The ex-factory price of the goods","The cost of imported raw materials only","The retail price including VAT"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"The ad valorem part of excise is a percentage of the ex-factory price, the value at the factory gate. Option A is the import duty base, and Option D would charge excise on distributor margins and VAT."}},{"itemId":"9fa97a0e-0295-50bc-9790-58417cd118b1","questionId":"d6c45c01-be3b-50a3-8e59-db32d9f92d46","sourceKey":"bank:TAX-CM223:CUS-026","payload":{"prompt":"Owerri Medicals Ltd imported equipment with FOB value $50,000, insurance $1,000 and freight $4,000. The exchange rate is $1 = N1,500. Under the Nigeria Customs Service Act 2023, what is the CIF value in naira?","options":["N76,500,000","N75,000,000","N82,500,000","N81,000,000"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"CIF = (FOB + insurance + freight) x exchange rate = ($50,000 + $1,000 + $4,000) x 1,500 = N82,500,000. Option B uses FOB only, and Option D forgets insurance."}},{"itemId":"e40a6d66-343e-5854-9f47-ac8b6ad6ef13","questionId":"ffd76ced-ac7c-5acb-a67f-6f9116ab1379","sourceKey":"bank:TAX-CM223:CUS-027","payload":{"prompt":"Goods with FOB value $50,000, insurance $1,000 and freight $4,000 are imported at $1 = N1,500. The ECOWAS CET rate is 10%. Under the Nigeria Customs Service Act 2023, what is the import duty?","options":["N16,500,000","N8,250,000","N7,500,000","N6,187,500"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Import duty = CET rate x CIF = 10% x N82,500,000 = N8,250,000. Option C applies 10% to FOB only, and Option D wrongly applies the VAT rate instead of the CET rate."}},{"itemId":"b5fb0eea-1dbc-574f-bafe-6bcc4bcea054","questionId":"4a625d7f-6022-5095-a900-d1d42562b9b3","sourceKey":"bank:TAX-CM223:CUS-028","payload":{"prompt":"Ikeja Electronics Ltd imported goods with a CIF value of N40,000,000. Import duty is 20% of CIF. VAT at 7.5% is charged on CIF plus import duty (no other charges are in the VAT base). What is the VAT on importation?","options":["N3,600,000","N3,000,000","N600,000","N4,800,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"VAT base = CIF + duty = N40,000,000 + N8,000,000 = N48,000,000; VAT = 7.5% x N48,000,000 = N3,600,000. Option B forgets to add the duty to the base, and Option C charges VAT on the duty alone."}},{"itemId":"4dcf86d6-249f-57ee-a09f-88d9ce97b21b","questionId":"02452a6a-6340-50ec-b03b-f5b8c342f986","sourceKey":"bank:TAX-CM223:CUS-029","payload":{"prompt":"Benin Diagnostics Ltd imported laboratory equipment: FOB EUR80,000, insurance EUR1,500, freight EUR3,500; EUR1 = N1,800. Assume: import duty 5% of CIF; CISS levy 1% of CIF; ECOWAS levy 0.5% of CIF; VAT 7.5% on (CIF + import duty). What are the total import charges, to the nearest naira?","options":["N21,993,750","N21,420,000","N19,698,750","N9,945,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"CIF = EUR85,000 x 1,800 = N153,000,000. Duty N7,650,000 + CISS N1,530,000 + ECOWAS N765,000 + VAT 7.5% x N160,650,000 = N12,048,750; total N21,993,750. Option D leaves out VAT, and Option B computes VAT on CIF only."}},{"itemId":"a82303d2-25c2-5281-8378-f6274289faba","questionId":"d92b8a3f-eba8-55d9-b97e-8a6f467d3f96","sourceKey":"bank:TAX-CM223:CUS-030","payload":{"prompt":"Aba Foods Ltd imported packaged food with a CIF value of $25,000 at $1 = N1,600. Assume: import duty 20% of CIF; CISS levy 1% of CIF; ECOWAS levy 0.5% of CIF; NAFDAC levy 0.5% of CIF; VAT 7.5% on (CIF + import duty). What are the total import charges?","options":["N12,400,000","N12,200,000","N11,600,000","N11,800,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"CIF = 25,000 x 1,600 = N40,000,000. Duty N8,000,000 + CISS N400,000 + ECOWAS N200,000 + NAFDAC N200,000 + VAT 7.5% x N48,000,000 = N3,600,000; total N12,400,000. Option B forgets the NAFDAC levy, which applies to food, drugs and cosmetics, and Option D leaves the duty out of the VAT base."}},{"itemId":"533fdc4c-6d9b-5492-b079-5d891b1fedf9","questionId":"7a136ffb-8899-52be-8bb3-c85cb3718363","sourceKey":"bank:TAX-CM223:CUS-031","payload":{"prompt":"An importer paid import duty of N4,200,000 on goods with a CIF value of N12,000,000. Under the ECOWAS Common External Tariff, which band was applied?","options":["35%","42%","20%","10%"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"CET rate = duty / CIF = N4,200,000 / N12,000,000 = 35%, the top CET band. Option B divides by the wrong figure, and Option C is the next band down."}},{"itemId":"fa63ad9e-fdfa-5a92-94a0-48f84946d307","questionId":"b04a7b0e-4088-547d-9cd4-a6e49e20799e","sourceKey":"bank:TAX-CM223:CUS-032","payload":{"prompt":"Goods with a CIF value of N30,000,000 attract import duty at 10% under the ECOWAS CET. Assume a surcharge of 7% of the import duty also applies. What is the total of import duty plus surcharge?","options":["N210,000","N3,000,000","N3,210,000","N5,100,000"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Duty = 10% x N30,000,000 = N3,000,000; surcharge = 7% x N3,000,000 = N210,000; total N3,210,000. Option D wrongly computes the surcharge on CIF instead of on the duty, and Option B forgets the surcharge."}},{"itemId":"9aec6e3d-3822-5828-864e-56366b5890b9","questionId":"1c89d8df-c719-5f3b-b84b-b7370a405928","sourceKey":"bank:TAX-CM223:CUS-033","payload":{"prompt":"Machinery is bought for FOB $60,000 with freight of $6,000. Insurance is 1% of (FOB + freight). The exchange rate is $1 = N1,550. What is the CIF value in naira for customs purposes, to the nearest naira?","options":["N103,230,000","N93,000,000","N102,300,000","N103,323,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Insurance = 1% x $66,000 = $660; CIF = $66,660 x 1,550 = N103,323,000. Option C ignores insurance, and Option A calculates insurance on FOB only."}},{"itemId":"91e92d22-56d1-5024-af32-48046da28aa8","questionId":"693b02e5-b393-59a6-9164-73d67a2f6714","sourceKey":"bank:TAX-CM223:CUS-034","payload":{"prompt":"Enugu Breweries Ltd produced 200,000 litres of beer at an ex-factory price of N500 per litre. Assume excise on beer is N0.30 per litre plus 20% ad valorem on the ex-factory value. What is the total excise duty?","options":["N20,000,000","N60,000","N30,060,000","N20,060,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Specific: 200,000 x N0.30 = N60,000; ad valorem: 200,000 x N500 x 20% = N20,000,000; total N20,060,000. Option A forgets the specific element, and Option B forgets the ad valorem element."}},{"itemId":"af3ad4a6-9080-5f66-851f-f5fe7e31becf","questionId":"506af1f4-66ca-56e2-93c1-2d407876f184","sourceKey":"bank:TAX-CM223:CUS-035","payload":{"prompt":"A distillery in Ota produced 50,000 litres of gin at an ex-factory price of N2,000 per litre. Assume excise on spirits is N1.50 per litre plus 30% ad valorem. What is the excise duty payable?","options":["N30,000,000","N29,925,000","N20,075,000","N30,075,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Specific: 50,000 x N1.50 = N75,000; ad valorem: 50,000 x N2,000 x 30% = N30,000,000; total N30,075,000. Option A leaves out the per-litre charge, and Option C uses the beer ad valorem rate of 20% instead of 30%."}},{"itemId":"62b154f2-5374-5e79-ada7-b415bed74d18","questionId":"b6ac997a-839a-50cc-8cde-9fcb0c02e711","sourceKey":"bank:TAX-CM223:CUS-036","payload":{"prompt":"A tobacco manufacturer produced 2,000,000 cigarette sticks with an ex-factory price of N40 per stick. Assume excise on cigarettes is N3.50 per stick plus 20% ad valorem. What is the excise duty?","options":["N7,000,000","N16,000,000","N23,000,000","N17,400,000"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Specific: 2,000,000 x N3.50 = N7,000,000; ad valorem: 2,000,000 x N40 x 20% = N16,000,000; total N23,000,000. Option A ignores the ad valorem part, and Option D wrongly applies 20% to the specific duty plus price."}},{"itemId":"d0b471b1-2711-57b2-946c-794060782956","questionId":"f1f9685d-fdbb-5369-a9f9-9c0ae77576a7","sourceKey":"bank:TAX-CM223:CUS-037","payload":{"prompt":"A juice bottler produced 80,000 litres of a sugar-sweetened beverage. Assume excise is N0.10 per centilitre (1 litre = 100 centilitres). What is the excise duty?","options":["N8,000","N80,000","N8,000,000","N800,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Volume in centilitres = 80,000 x 100 = 8,000,000 cl; excise = 8,000,000 x N0.10 = N800,000. Option A applies the rate per litre, forgetting to convert to centilitres, and Option C converts litres to millilitres instead."}},{"itemId":"44574ddd-395f-5b94-98f8-e97d5303a889","questionId":"09b0d31c-1292-59ec-8c1c-5939b90a8e5d","sourceKey":"bank:TAX-CM223:CUS-038","payload":{"prompt":"A winery produced 30,000 litres of wine at N1,500 per litre ex-factory. Assume excise on wine is N0.65 per litre plus 20% ad valorem. What is the excise duty?","options":["N9,019,500","N9,000,000","N9,045,000","N13,519,500"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"Specific: 30,000 x N0.65 = N19,500; ad valorem: 30,000 x N1,500 x 20% = N9,000,000; total N9,019,500. Option D uses 30% instead of 20%, and Option C uses the N1.50 spirits rate per litre."}},{"itemId":"2a6ace44-82ae-578d-847d-605e98f5c770","questionId":"3cfac899-3945-5f04-9481-fcf53d168279","sourceKey":"bank:TAX-CM223:CUS-039","payload":{"prompt":"A cigar maker's ex-factory sales of other tobacco products are N18,000,000. Assume excise on other tobacco is 20% ad valorem with no specific element. What is the excise duty?","options":["N5,400,000","N6,300,000","N1,350,000","N3,600,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"Excise = 20% x N18,000,000 = N3,600,000. Option A uses the spirits ad valorem rate, and Option C applies the VAT rate instead of the excise rate."}},{"itemId":"63ac5078-77cc-5d57-89b0-de5fe1137008","questionId":"d7e077e0-eac2-53fa-a1d8-2698e4434a5e","sourceKey":"bank:TAX-CM223:CUS-040","payload":{"prompt":"Assume excise on beer is N0.30 per litre plus 20% of the ex-factory price. If beer sells at N400 per litre ex-factory, what is the excise duty per litre, to 2 decimal places?","options":["N0.30","N80.30","N80.06","N80"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Excise per litre = N0.30 + 20% x N400 = N0.30 + N80.00 = N80.30. Option D drops the specific N0.30, and Option C wrongly applies 20% to the price plus the specific duty."}},{"itemId":"a5fb8975-4347-531d-8088-36119261627a","questionId":"2bae0e89-71be-5455-b5df-875cb6ef6979","sourceKey":"bank:TAX-CM223:CUS-041","payload":{"prompt":"Port Harcourt Supplies Ltd paid import duty of N6,000,000 on a consignment. It later re-exported 40% of the consignment unused. Under the Nigeria Customs Service Act 2023 drawback rules, what drawback can it claim?","options":["N2,400,000","N1,200,000","N6,000,000","N3,600,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"Re-exported unused goods earn a 100% drawback of the duty attributable to them: 40% x N6,000,000 = N2,400,000. Option C claims duty on the whole consignment, and Option D uses the share kept in Nigeria."}},{"itemId":"f48ad609-bd9d-5360-bffb-ad27c0782b4d","questionId":"f56032d9-f409-5381-bb55-0ef575459565","sourceKey":"bank:TAX-CM223:CUS-042","payload":{"prompt":"A juice manufacturer paid import duty of N9,000,000 on imported concentrate used to produce 1,000,000 cartons. It exported 300,000 cartons. Under manufacturing drawback (proportionate to imported content in exported goods), what drawback is claimable?","options":["N6,300,000","N202,500","N2,700,000","N9,000,000"],"correctOption":2,"section":"Customs and Excise Duties","explanation":"Drawback = N9,000,000 x 300,000/1,000,000 = N2,700,000. Option D claims all the duty although most output was sold locally, and Option A uses the local-sales proportion."}},{"itemId":"f6cd5c30-0a30-56c5-ad31-152a8285dff7","questionId":"65702d38-4063-5f07-b128-338e17aefc4d","sourceKey":"bank:TAX-CM223:CUS-043","payload":{"prompt":"Delta Spirits Ltd imported spirits with a CIF value of $800,000 at $1 = N1,700. The ECOWAS CET rate is 35%. VAT at 7.5% is charged on (CIF + import duty). What is the total of import duty and VAT?","options":["N613,700,000","N578,000,000","N476,000,000","N511,700,000"],"correctOption":0,"section":"Customs and Excise Duties","explanation":"CIF = 800,000 x 1,700 = N1,360,000,000; duty = 35% = N476,000,000; VAT = 7.5% x N1,836,000,000 = N137,700,000; total N613,700,000. Option B computes VAT on CIF only, and Option D charges VAT only on the duty."}},{"itemId":"ae9a4743-1426-5fea-996b-616bdc36d7d1","questionId":"4514ccd6-aee3-582b-bb22-9bbd25e60451","sourceKey":"bank:TAX-CM223:CUS-044","payload":{"prompt":"Goods with a CIF value of N50,000,000 are imported. Assume the CISS levy is 1% of CIF and the ECOWAS levy is 0.5% of CIF. What is the combined CISS and ECOWAS levy?","options":["N500,000","N750,000","N7,500,000","N250,000"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"CISS N500,000 + ECOWAS N250,000 = 1.5% x N50,000,000 = N750,000. Options A and D give only one of the two levies, and Option C treats 1.5% as 15%."}},{"itemId":"90aa671d-805c-5550-b0ce-5e1d9a58b102","questionId":"94c3c6b8-0fd2-5d99-9e84-87c07d537e3f","sourceKey":"bank:TAX-CM223:CUS-045","payload":{"prompt":"A brewery produced 1,000,000 litres of beer at N600 per litre ex-factory. Assume excise is N0.30 per litre plus 20% ad valorem, charged on all litres produced. Separately, 250,000 litres were exported and import duty of N4,000,000 was paid on the imported inputs used in the exported beer only. What is the excise duty?","options":["N116,300,000","N120,300,000","N90,225,000","N120,000,000"],"correctOption":1,"section":"Customs and Excise Duties","explanation":"Excise = 1,000,000 x N0.30 + 1,000,000 x N600 x 20% = N300,000 + N120,000,000 = N120,300,000. Option A wrongly nets off the import duty drawback, which is a refund of customs duty and not a deduction from excise, and Option C reduces the base although the stem states excise applies to all litres produced."}},{"itemId":"e14d1412-e6a3-5abc-97c4-04ce557352df","questionId":"ce8250fe-c01c-5606-8eb6-0b99d6586c6a","sourceKey":"bank:TAX-CM223:CUS-046","payload":{"prompt":"Medical equipment with a CIF value of N20,000,000 attracts import duty at the 5% CET band. VAT at 7.5% is charged on CIF plus duty. What is the VAT base on importation?","options":["N20,000,000","N22,575,000","N1,575,000","N21,000,000"],"correctOption":3,"section":"Customs and Excise Duties","explanation":"VAT base = CIF + import duty = N20,000,000 + N1,000,000 = N21,000,000. Option A omits the duty, Option C is the VAT itself (7.5% of the base), and Option B wrongly adds the VAT into its own base."}},{"itemId":"d31dd716-650d-5641-974c-b2e4f33ace7d","questionId":"2383e00a-e385-56d4-809a-b57ddd602411","sourceKey":"bank:TAX-CM223:PQ-003-c","payload":{"prompt":"Under the repealed Companies Income Tax Act regime, failure to deduct tax attracted a penalty of 10% of the amount not deducted, plus interest. How does the penalty for failure to deduct under section 105 of the Nigeria Tax Administration Act 2025 compare?","options":["It has been reduced to 5% of the amount not deducted","It is unchanged at 10% of the amount not deducted","It is now 20% of the amount not deducted, double the old rate","It is now 40% of the amount not deducted, four times the old rate"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The NTAA 2025 raised the penalty for failure to deduct from 10% to 40% of the amount not deducted, quadrupling it to push payers to comply. Option B is tempting because 10% still appears in the new law, but only as the per annum penalty for failure to remit. Options A and C are not the new rate."}},{"itemId":"b28985e6-2448-5bb5-aec7-b35eaf419267","questionId":"252c350e-a060-59e1-8c0e-324eaf6fe776","sourceKey":"bank:TAX-CM223:PQ-005-c","payload":{"prompt":"Under the repealed VAT Act, VAT revenue was shared 15% to the Federal Government, 50% to States and FCT and 35% to Local Governments. What change does section 81(1) of the Nigeria Tax Administration Act 2025 make?","options":["Local Governments rise to 55% and States and FCT fall to 35%","There is no change; the old ratio is carried over","The Federal Government share rises to 85% and States fall to 15%","The Federal Government share falls to 10% and the States and FCT share rises to 55%, while Local Governments stay at 35%"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Under the NTAA 2025 the Federal Government gives up 5 percentage points to the States and FCT, moving from 15/50/35 to 10/55/35, while Local Governments keep 35%. Option C moves revenue in the wrong direction. Option A swaps the States and Local Government shares, and option B ignores the reform."}},{"itemId":"3833beb0-5854-56e7-b824-6a0fe197b973","questionId":"798f76c7-752f-51be-a7aa-dd2e72cc7a35","sourceKey":"bank:TAX-CM223:PQ-010-e","payload":{"prompt":"Under the old Finance Act regime, the N50 electronic money transfer levy on electronic receipts of N10,000 or more was borne by the recipient. Under the Nigeria Tax Act 2025 (from 1 January 2026), who bears the N50 stamp duty on an electronic transfer of N10,000 or more?","options":["The recipient","The sender (transferor)","The sender and recipient equally","The bank, from its own income"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"From 1 January 2026 the N50 duty on transfers of N10,000 or more is charged to the person making the transfer, so banks now deduct it from the sender's account. Option A describes the old electronic money transfer levy. Options D and C are not how the duty is charged."}},{"itemId":"b8e1eddd-2cb2-53be-8c18-23e0d982699b","questionId":"3caf045f-57b1-5ca2-94b1-445443e389a0","sourceKey":"bank:TAX-CM223:GVS-001","payload":{"prompt":"From what date did the Nigeria Tax Act 2025 commence?","options":["1 January 2025","1 July 2026","1 January 2026","26 June 2025"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 was assented to on 26 June 2025 but commenced on 1 January 2026. Option D is the assent date, not the commencement date, and the other options are not dates fixed by the Act."}},{"itemId":"348a2c7d-edb1-5ff8-81fd-467ad33bf0f9","questionId":"611ab29b-db46-50d4-b435-7bc4d1438fe2","sourceKey":"bank:TAX-CM223:GVS-002","payload":{"prompt":"On what date was the Nigeria Tax Act 2025 assented to by the President?","options":["1 October 2024","26 June 2025","31 December 2025","1 January 2026"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The President signed the four reform Acts on 26 June 2025; the Nigeria Tax Act 2025 then took effect from 1 January 2026. Option D is the commencement date, which students often confuse with the assent date."}},{"itemId":"fd670c48-f28c-50f4-808d-2fce2a41f3b9","questionId":"ee931332-87ab-5d1b-a94b-c6976c5470e9","sourceKey":"bank:TAX-CM223:GVS-003","payload":{"prompt":"Which of the following laws was NOT repealed by the Nigeria Tax Act 2025?","options":["The Stamp Duties Act","The Nigeria Customs Service Act 2023","The Value Added Tax Act","The Companies Income Tax Act"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Customs duty was left outside the Nigeria Tax Act 2025 and remains under the Nigeria Customs Service Act 2023. Options A, C and D were all repealed and their substance consolidated into the Nigeria Tax Act 2025."}},{"itemId":"eda71bce-1a60-532d-b44c-3886301c7ca5","questionId":"90414dc0-b730-5c41-a690-5577cb7c0782","sourceKey":"bank:TAX-CM223:GVS-004","payload":{"prompt":"Which of the following Acts was repealed by the Nigeria Tax Act 2025 with effect from its commencement?","options":["The Tertiary Education Trust Fund (Establishment) Act","The Nigeria Export Processing Zones Act","The Petroleum Profits Tax Act","The Nigeria Customs Service Act 2023"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Petroleum Profits Tax Act is one of the twelve enactments listed as repealed by the Nigeria Tax Act 2025. Option D still governs customs, while Options A and B were amended rather than repealed."}},{"itemId":"94e480dd-26e2-5b1c-b968-ec614aa38b0e","questionId":"56cbf422-c436-5866-b28a-f8738f6b2cd1","sourceKey":"bank:TAX-CM223:GVS-005","payload":{"prompt":"After the 2025 reforms, where are the main rules on Value Added Tax in Nigeria found?","options":["In the Value Added Tax Act, which continues alongside the new Acts","In the Nigeria Tax Act 2025, after the repeal of the Value Added Tax Act","In the Nigeria Customs Service Act 2023","In the Joint Revenue Board (Establishment) Act 2025"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Value Added Tax Act was repealed and VAT now sits in the Nigeria Tax Act 2025 as one chapter of a consolidated statute. Option A is wrong because the old Act no longer operates, and Option D concerns the inter-governmental revenue board, not the VAT charge."}},{"itemId":"dec5797d-2615-5e07-be47-91b68c839a96","questionId":"790ca0c6-6f18-53a5-a708-c2ddaa6e0bff","sourceKey":"bank:TAX-CM223:GVS-006","payload":{"prompt":"Stamp duties in Nigeria were previously governed by the Stamp Duties Act. After the 2025 reforms, they are governed by:","options":["The Stamp Duties Act, as amended in 2025","The Nigeria Customs Service Act 2023","The Nigeria Tax Act 2025","The Nigeria Revenue Service (Establishment) Act 2025"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Stamp Duties Act was repealed and its provisions were absorbed into the Nigeria Tax Act 2025. Option A is wrong because the old Act was repealed rather than amended, and Option D only establishes the revenue authority."}},{"itemId":"44248120-93ae-5f25-ba70-8a620548499a","questionId":"b7e29c0e-b01d-5d3e-a511-e8ff7044f0c8","sourceKey":"bank:TAX-CM223:GVS-007","payload":{"prompt":"Which old law, repealed by the Nigeria Tax Act 2025, provided the Pioneer Status Incentive now replaced by the Economic Development Tax Incentive?","options":["The Income Tax (Authorised Communications) Act","The Industrial Development (Income Tax Relief) Act","The Venture Capital (Incentives) Act","The Casino Taxation Act"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Pioneer status was granted under the Industrial Development (Income Tax Relief) Act; that Act was repealed and the Economic Development Tax Incentive took its place. Options A, C and D were also repealed, but none of them was where pioneer status came from."}},{"itemId":"e2405b32-5634-5848-b549-4765165f22bd","questionId":"818d0e9f-0f92-5158-b6bd-dbf35a69c2a2","sourceKey":"bank:TAX-CM223:GVS-008","payload":{"prompt":"Which Act did the Nigeria Revenue Service (Establishment) Act 2025 repeal?","options":["The Companies Income Tax Act","The Nigeria Customs Service Act 2023","The Personal Income Tax Act","The Federal Inland Revenue Service (Establishment) Act 2007"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Revenue Service (Establishment) Act 2025 repealed the FIRS (Establishment) Act 2007 and replaced the FIRS with the Nigeria Revenue Service. Options A and C were repealed by the Nigeria Tax Act 2025, not by the establishment Act."}},{"itemId":"ccd3c484-2f82-57d7-989e-8e30aaca12d1","questionId":"1a31ca03-ee5f-5afc-9746-ce9951d415a8","sourceKey":"bank:TAX-CM223:GVS-009","payload":{"prompt":"A company's old correspondence refers to the 'FIRS'. Under the 2025 reform Acts, which body now performs that role?","options":["The State Internal Revenue Service of each state","The Nigeria Customs Service (NCS)","The Nigeria Revenue Service (NRS)","The Joint Revenue Board (JRB)"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The FIRS was restructured and renamed the Nigeria Revenue Service by the Nigeria Revenue Service (Establishment) Act 2025. Option D coordinates federal and state tax administration rather than collecting federal taxes, and Option B handles customs."}},{"itemId":"ce4db32d-1bb3-550e-9ab6-4a0aa286fdbf","questionId":"08c14326-8d4b-5a6e-8967-08d42e2aa0d0","sourceKey":"bank:TAX-CM223:GVS-010","payload":{"prompt":"Under the 2025 reform Acts, the Joint Tax Board (JTB) has been replaced by:","options":["The Tax Appeal Tribunal","The Nigeria Revenue Service (NRS)","The Office of the Tax Ombud","The Joint Revenue Board (JRB)"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Joint Revenue Board (Establishment) Act 2025 replaces the JTB with the Joint Revenue Board, which harmonises and coordinates revenue administration across governments. Option B is the successor of the FIRS, and Options A and C are separate bodies under the same Act."}},{"itemId":"7a923f35-4e3c-5a99-86e1-17fd932ec4cd","questionId":"db46fd5d-04ff-5fbe-859a-153b9413202c","sourceKey":"bank:TAX-CM223:GVS-011","payload":{"prompt":"The Joint Revenue Board (Establishment) Act 2025 created an independent office to review taxpayers' complaints about taxes, levies, fees, customs duty and excise matters. What is it called?","options":["The Nigeria Revenue Service","The Tax Appeal Tribunal","The Federal High Court","The Office of the Tax Ombud"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Office of the Tax Ombud is an impartial complaints reviewer created by the Joint Revenue Board (Establishment) Act 2025. Option B hears formal tax appeals rather than complaints, and Option A is the collecting authority whose conduct may be complained about."}},{"itemId":"1213e07b-3f67-5e86-ab0d-867895406b6e","questionId":"5896e1d8-cd62-5348-8ab8-742bf208d379","sourceKey":"bank:TAX-CM223:GVS-012","payload":{"prompt":"The Nigeria Tax Act 2025 repealed the Taxes and Levies (Approved List for Collection) Act. What was that Act's main role?","options":["It listed the taxes and levies that each tier of government could collect","It established the Federal Inland Revenue Service as an agency","It imposed customs duty on goods imported into Nigeria","It fixed the standard rate of VAT for all supplies"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Approved List Act set out which taxes and levies the federal, state and local governments could collect; its repeal removed, for example, state authority to collect certain business premises fees and development levies under it. Options B, C and D describe customs, VAT and FIRS laws instead."}},{"itemId":"01b53fcf-d596-5efa-b53c-c6fb3c4bd7ea","questionId":"be50caed-4041-5dda-9515-6604a032f036","sourceKey":"bank:TAX-CM223:GVS-013","payload":{"prompt":"How did the standard VAT rate change when VAT moved from the old Value Added Tax Act (as amended by the Finance Act 2019) into the Nigeria Tax Act 2025?","options":["It rose from 5% to 7.5%","It rose from 7.5% to 10%","It fell from 7.5% to 5%","It stayed at 7.5%"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The standard rate was 7.5% under the Finance Act 2019 amendment and remains 7.5% under the Nigeria Tax Act 2025. Option A describes the 2019 change from 5% to 7.5%, which happened before the 2025 reforms."}},{"itemId":"ca462b40-516f-5a36-8f87-e7ba7f94e2ca","questionId":"08e1f1bd-64fb-59db-9fb9-a1ebabcf8dac","sourceKey":"bank:TAX-CM223:GVS-014","payload":{"prompt":"Under the old Value Added Tax Act, the Federal Government took 15% of VAT revenue. What is the Federal Government's share under the Nigeria Tax Administration Act 2025?","options":["85%","15%","55%","10%"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Administration Act 2025 sets VAT sharing at 10% Federal, 55% States and FCT, and 35% Local Governments, so the federal share fell from 15% to 10%. Option C is the new state share, and Option A is not a VAT share under either system."}},{"itemId":"1cb08be8-1308-5b21-994f-2e681a208600","questionId":"2dbde919-a078-5615-b885-e848daf2f566","sourceKey":"bank:TAX-CM223:GVS-015","payload":{"prompt":"Suppose distributable VAT revenue for a period is N600,000,000,000. Under the old Value Added Tax Act the States' share was 50%; under the Nigeria Tax Administration Act 2025 it is 55% (States and FCT). By how much does the States' share increase?","options":["N60,000,000,000","N270,000,000,000","N330,000,000,000","N30,000,000,000"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"New share 55% x N600,000,000,000 = N330,000,000,000; old share 50% = N300,000,000,000; increase = 5% x N600,000,000,000 = N30,000,000,000. Option C gives the new share itself rather than the increase."}},{"itemId":"3a7326ef-d6d5-5603-b776-fb22003629e0","questionId":"ef3bb2a8-8cca-5b9c-9fd5-b67e5fa3125e","sourceKey":"bank:TAX-CM223:GVS-016","payload":{"prompt":"Under the Nigeria Tax Act 2025, what is the rate of the development levy, and on what base is it charged?","options":["3% of total profits after capital allowances","4% of assessable profits","4% of turnover","2% of assessable profits"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 imposes a development levy of 4% on the assessable profits of companies chargeable to tax. Option D is lower than the statutory rate, and Option C uses turnover, which is not the base."}},{"itemId":"c1688c8b-68a3-5a45-a14e-0863a26795e6","questionId":"0afde638-ee57-565c-895a-62d7618fbf46","sourceKey":"bank:TAX-CM223:GVS-017","payload":{"prompt":"The Nigeria Tax Act 2025 development levy consolidated several earmarked levies. Which of the following was NOT replaced by it?","options":["The NITDA levy","The Nigeria Police Trust Fund levy","Tertiary education tax","Value added tax"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The 4% development levy replaced earmarked company levies such as the tertiary education tax, the NITDA levy, the NASENI levy and the Police Trust Fund levy. VAT is a separate consumption tax that continues under the Nigeria Tax Act 2025, so it was not replaced."}},{"itemId":"0d364745-31e4-58ed-b313-85cf7841c7c1","questionId":"babd2623-705b-54c2-a276-0377a0b56ec8","sourceKey":"bank:TAX-CM223:GVS-018","payload":{"prompt":"Which companies are excluded from the development levy under the Nigeria Tax Act 2025?","options":["Small companies and non-resident companies","Manufacturing companies and banks","All companies with losses brought forward","Companies listed on the Nigerian Exchange"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The levy applies to all companies chargeable to tax other than small companies and non-resident companies. Options B and D are not exempt categories, and Option C confuses the levy base with relief for losses."}},{"itemId":"97850967-96f9-585a-9abf-4c3756ffa7eb","questionId":"ca590ebe-be96-51b5-87e1-0cbf5850e882","sourceKey":"bank:TAX-CM223:GVS-019","payload":{"prompt":"Ilorin Cement Ltd (not a small company) has assessable profits of N250,000,000. Under the Nigeria Tax Act 2025, the development levy is 4% of assessable profits, and 50% of the levy goes to the Tertiary Education Trust Fund. How much of the company's levy goes to the Tertiary Education Trust Fund?","options":["N5,000,000","N125,000,000","N10,000,000","N2,500,000"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Levy = 4% x N250,000,000 = N10,000,000; TETFund share = 50% x N10,000,000 = N5,000,000. Option C is the whole levy, and Option D uses the old idea of a 2% education tax."}},{"itemId":"07ccf9ca-188b-50f0-904d-e35a0b4ada43","questionId":"41e0bad3-b5c3-5e93-b8a2-ecdcc566a5e2","sourceKey":"bank:TAX-CM223:GVS-020","payload":{"prompt":"Total development levy collected in a month under the Nigeria Tax Act 2025 is N40,000,000. The Nigerian Education Loan Fund receives 15% and the National Cybersecurity Fund receives 5%. What is their combined share?","options":["N20,000,000","N4,000,000","N6,000,000","N8,000,000"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Combined share = (15% + 5%) x N40,000,000 = 20% x N40,000,000 = N8,000,000. Option C includes only the education loan share, and Option A is the TETFund share."}},{"itemId":"b71ff302-eb0d-52d1-8f4b-b924ce84884c","questionId":"0b46d4dd-dc00-5aaf-a066-8438234bb2d8","sourceKey":"bank:TAX-CM223:GVS-021","payload":{"prompt":"Under the Nigeria Tax Act 2025, what is the companies income tax rate for a small company?","options":["20%","0%","30%","15%"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Small companies are taxed at 0% under the Nigeria Tax Act 2025, while other companies pay 30%. Option C is the rate for companies that are not small, and Option D confuses the minimum effective tax rate with the small company rate."}},{"itemId":"4da62458-79b4-5bca-8915-496d56ee3ccc","questionId":"cc28f460-4340-54e6-a127-e2258ceebdb6","sourceKey":"bank:TAX-CM223:GVS-022","payload":{"prompt":"Ondo Logistics Ltd has annual gross turnover of N90 million and total fixed assets of N180 million. It provides haulage (not professional) services. Under the 2025 Acts, how is it classified?","options":["A small company, since turnover is not more than N100 million and fixed assets are not more than N250 million","Not a small company, since fixed assets exceed N100 million","A small company only if it also has fewer than 10 employees","Not a small company, since turnover exceeds N25 million"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"A small company under the 2025 framework has gross turnover of N100 million or less and total fixed assets of N250 million or less, with professional service providers excluded. Option D applies the old N25 million threshold, and Option C adds an employee test that the definition does not contain."}},{"itemId":"522e6047-d8fa-50bb-bfa5-d83d578ba20e","questionId":"40a7ec55-cc19-5960-b16f-05ac8acf9bd5","sourceKey":"bank:TAX-CM223:GVS-023","payload":{"prompt":"Adeyemi & Co Legal Practitioners Ltd has turnover of N60 million and fixed assets of N20 million. Under the 2025 Acts, why is it NOT a small company?","options":["Because small company status applies only to manufacturing companies","Because law firms must have fixed assets of at least N250 million","Because providers of professional services are excluded from the small company definition","Because its turnover exceeds N50 million"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Even though its turnover and assets are within the limits, a professional service provider such as a law firm is expressly excluded from the small company definition. Option D invents a N50 million limit, and Option A wrongly restricts the relief to manufacturers."}},{"itemId":"416950ea-0472-543f-a5b1-9a4832a17626","questionId":"fe40cfdd-0bc5-54e1-9dab-434d98ee6f63","sourceKey":"bank:TAX-CM223:GVS-024","payload":{"prompt":"Under the old Companies Income Tax Act (as amended by the Finance Act 2019), a small company had turnover of not more than N25 million. What is the turnover limit for a small company under the 2025 Acts?","options":["N50 million","N250 million","N100 million","N25 million"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The 2025 Acts raised the small company turnover limit from N25 million to N100 million, alongside a fixed-asset limit of N250 million. Option B is the fixed-asset limit, not the turnover limit, and Option D is the old figure."}},{"itemId":"2d476a25-e2cb-52b8-8795-73499bfbc6ce","questionId":"24af7f97-fdc0-5ba7-8dd3-19c5913e4af0","sourceKey":"bank:TAX-CM223:GVS-025","payload":{"prompt":"Calabar Holdings Ltd (not a small company) makes a chargeable gain of N40,000,000. Under the old Capital Gains Tax Act the rate was 10%; under the Nigeria Tax Act 2025, companies' gains are taxed at 30%. By how much does the tax on this gain increase?","options":["N16,000,000","N8,000,000","N4,000,000","N12,000,000"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Old tax 10% x N40,000,000 = N4,000,000; new tax 30% x N40,000,000 = N12,000,000; increase = N8,000,000. Option D is the new tax itself, and Option C is the old tax."}},{"itemId":"9e35007d-0700-55cd-9cb1-8b48f8e86df2","questionId":"afaf7c92-fa19-572e-bb19-31755b565b9b","sourceKey":"bank:TAX-CM223:GVS-026","payload":{"prompt":"How does the Nigeria Tax Act 2025 capital allowance regime differ from the old Companies Income Tax Act regime?","options":["Only buildings now qualify for capital allowances","The initial allowance is doubled and the annual allowance is abolished","The initial allowance is abolished and only an annual allowance at fixed class rates on cost is given","Capital allowances are abolished and depreciation is now deductible"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The old regime gave an initial allowance followed by annual allowances; the Nigeria Tax Act 2025 gives only annual allowances at fixed rates of 10%, 20% or 25% on cost. Option D is wrong because accounting depreciation is still not deductible, and Option A ignores the many other qualifying classes."}},{"itemId":"efebd69a-f6c7-5ad7-a3eb-b99773821136","questionId":"7650c35a-b80b-5144-a6f9-dfb742a27a9c","sourceKey":"bank:TAX-CM223:GVS-027","payload":{"prompt":"Which new charge on goods was introduced by the Nigeria Tax Act 2025 on chargeable fossil fuel products?","options":["A 5% surcharge based on the retail price","A 2% stamp duty on fuel receipts","A 10% customs levy on imported petrol","A 7.5% excise on crude oil exports"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 introduced a 5% surcharge on chargeable fossil fuel products, computed on the retail price, with exemptions for items such as cooking gas, kerosene, CNG and renewable energy products. Options B, C and D describe charges that the Act does not create."}},{"itemId":"4ad2f64a-8986-59b9-9107-f3218b45c3bc","questionId":"7b2d191a-2405-59de-b37b-9b889727e507","sourceKey":"bank:TAX-CM223:GVS-028","payload":{"prompt":"Under the old Value Added Tax Act, input VAT on services and fixed assets generally could not be recovered. How does the Nigeria Tax Act 2025 change this?","options":["Input VAT on purchases, including services and fixed assets, is recoverable if related to taxable supplies","Input VAT is recoverable only on goods imported for resale","Input VAT is recoverable only by small companies below N100 million","Input VAT is no longer recoverable on any purchase, goods or services"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 allows input VAT on all purchases, including services and fixed assets, where they relate to taxable supplies, which removes a cost that businesses bore under the old Act. Option D reverses the change, and Option C confuses the small company relief with VAT credit."}},{"itemId":"d67ec6e5-e50e-55ff-9853-a3cede97b9c5","questionId":"93f10541-0cb6-5ef4-84bb-37e56a8e21f0","sourceKey":"bank:TAX-CM223:GVS-029","payload":{"prompt":"Under the Nigeria Tax Act 2025, how are exports of services treated for VAT?","options":["They are zero-rated, so the exporter charges 0% and can recover related input VAT","They are charged at the standard 7.5% rate","They are outside VAT and the exporter must deregister","They are exempt, so related input VAT cannot be recovered"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Exported services are zero-rated under the Nigeria Tax Act 2025: no output VAT is charged and input VAT on related costs can be recovered. Option D describes exemption, which blocks input VAT recovery, and Option B would make exports more expensive."}},{"itemId":"a7e4ba4f-afaf-5db4-af69-32d74da886a3","questionId":"666680f8-d2e5-5558-bece-7bf7c9b59ec9","sourceKey":"bank:TAX-CM223:GVS-030","payload":{"prompt":"For VAT purposes under the Nigeria Tax Act 2025 framework, 'goods' are best described as:","options":["Any supply made for consideration, including services","Only movable tangible items that can be shipped","All forms of tangible property, movable or immovable","Only goods manufactured in Nigeria"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Goods for VAT cover all tangible property, whether movable or immovable. Option B wrongly leaves out immovable property, and Option A would include services, which are a separate category of supply."}},{"itemId":"3d8c0503-acf9-50b1-8776-e04422cb803f","questionId":"07306913-47f1-5e98-a8e5-f1afa62ef1eb","sourceKey":"bank:TAX-CM223:GVS-031","payload":{"prompt":"A consultancy based in Accra provides online advisory services to Abuja Fintech Ltd, which uses them in Nigeria. Under the Nigeria Tax Act 2025, is the supply treated as taking place in Nigeria for VAT?","options":["Yes, because the service is provided to and consumed by a person in Nigeria, wherever it is rendered","No, because services are never subject to VAT","Yes, but only if the consultant has an office in Nigeria","No, because the service was rendered outside Nigeria"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"A service is treated as supplied in Nigeria when it is provided to and consumed by a person in Nigeria, regardless of whether it is rendered within or outside Nigeria. Option D looks at where the work is done rather than where it is consumed, and Option C adds a physical-presence test that does not apply."}},{"itemId":"cff9d2b0-e0d2-52a0-804c-258cdaa10e2a","questionId":"56836ed9-1809-54ab-889e-19ef6d17957f","sourceKey":"bank:TAX-CM223:GVS-032","payload":{"prompt":"A transaction includes both a supply of goods and a supply of a service. How is its VAT classification determined in the goods-and-services framework?","options":["By the dominant element of the transaction","Always as a supply of goods","Always as a supply of services","By whichever element is cheaper"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"For a mixed supply, the dominant element decides whether the transaction is treated as goods or services. Options B and C apply a fixed rule regardless of the facts, and Option D has no basis."}},{"itemId":"1e1fd0d1-ecb9-5bcd-9726-eb2fd0547d23","questionId":"aaf19d01-c9a7-5ec4-8ddf-ef3e7f9d5be5","sourceKey":"bank:TAX-CM223:GVS-033","payload":{"prompt":"In comparing how goods and services are taxed in Nigeria, which tax applies to imported goods but has no application to imported services?","options":["Value added tax","Stamp duty","Withholding tax","Customs import duty"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Import duty is charged on goods at CIF value and does not apply to services. VAT in Option A reaches both goods and services, including imported services through non-resident supplier rules."}},{"itemId":"c498e743-d6d2-5827-bdae-e9558e7e0fa0","questionId":"d5fd3752-048d-5414-bb36-868c2d456593","sourceKey":"bank:TAX-CM223:GVS-034","payload":{"prompt":"How did the old Sales Tax (before VAT was introduced in 1994) differ from VAT under the Nigeria Tax Act 2025?","options":["Sales tax was multi-stage; VAT is single-stage at the retail point","Sales tax covered services only; VAT covers goods only","Sales tax was single-stage at the final point; VAT is multi-stage with input tax credit","Both are single-stage taxes on retail sales only"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The old sales tax was collected once, at the final retail point, while VAT is charged at each stage, with each business deducting the input VAT it paid. Option A swaps the two, and Option B reverses the scope, since sales tax covered goods only."}},{"itemId":"a78c86e1-3df9-5a61-8daf-3bb31a9c1b75","questionId":"c362744f-bd25-5e6f-ab56-6b411f9b8f1b","sourceKey":"bank:TAX-CM223:GVS-035","payload":{"prompt":"What feature of VAT under the Nigeria Tax Act 2025 removes the 'tax on tax' (cascading) effect seen under the old Sales Tax?","options":["The input VAT credit mechanism","Revenue sharing with the states","Collection by the Nigeria Revenue Service","The 7.5% single rate"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Because each registered business deducts the input VAT it paid from its output VAT, tax is not charged on tax already paid earlier in the chain. Options B, C and D are real features of the VAT system, but none of them stops cascading."}},{"itemId":"92d888c0-f2f8-5910-ae21-3f6387587229","questionId":"8f795d38-d0ea-5b86-9e3a-dd9de99d23d7","sourceKey":"bank:TAX-CM223:GVS-036","payload":{"prompt":"Which statement correctly compares the scope and administration of the old Sales Tax with VAT under the 2025 Acts?","options":["Both cover goods only and are administered by the states","Sales tax covered goods only and was state-administered; VAT covers goods and services and is administered by the Nigeria Revenue Service","Sales tax covered services only; VAT is administered by the Nigeria Customs Service","Sales tax covered goods and services and was federally administered; VAT covers goods only"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Sales tax was a state-administered tax on goods, whereas VAT reaches both goods and services and is administered by the Nigeria Revenue Service. Option D reverses the scope, and Option C names the wrong agency."}},{"itemId":"a06f0ca6-9165-5b37-9704-2487fe6a30ff","questionId":"3b5935e5-bd35-544b-ba85-cf678f7a8997","sourceKey":"bank:TAX-CM223:GVS-037","payload":{"prompt":"A manufacturer sells goods to a wholesaler for N100,000, the wholesaler sells them to a retailer for N150,000, and the retailer sells to a consumer for N200,000 (all VAT-exclusive). With VAT at 7.5% under the Nigeria Tax Act 2025 and full input VAT credit at each stage, what is the total net VAT remitted along the whole chain?","options":["N15,000","N33,750","N3,750","N7,500"],"correctOption":0,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Net VAT at each stage is 7.5% of the value added: N7,500 + N3,750 + N3,750 = N15,000, which equals 7.5% of the final price. Option B adds up output VAT without input credit, which is the cascading effect VAT removes, and Option C is only the retailer's net VAT."}},{"itemId":"6939144f-190d-52eb-a572-5e084067c535","questionId":"f4bdcac4-8a4b-5c35-b859-a05db151a1e4","sourceKey":"bank:TAX-CM223:GVS-038","payload":{"prompt":"In a month a VAT-registered trader charged output VAT of N3,000,000 and paid input VAT of N1,800,000 on purchases for its taxable supplies. Under the Nigeria Tax Act 2025 credit mechanism, what net VAT does it remit?","options":["N4,800,000","N1,800,000","N3,000,000","N1,200,000"],"correctOption":3,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Net VAT = output VAT - input VAT = N3,000,000 - N1,800,000 = N1,200,000. Option C ignores the input credit, and Option A adds the input VAT instead of deducting it."}},{"itemId":"5619a2e4-de58-5d27-92f1-70bdd73c0fc1","questionId":"df7e81a9-b0f9-5f9d-9b67-3bcf2b82b94c","sourceKey":"bank:TAX-CM223:GVS-039","payload":{"prompt":"Which of these is a new feature of the Nigeria Tax Act 2025 that did not exist under the old Companies Income Tax Act?","options":["A 30% companies income tax rate for companies that are not small","A minimum effective tax rate of 15% for large companies and members of multinational groups","Non-deductibility of capital expenditure in computing profits","Taxation of company profits by the federal tax authority"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 introduces a 15% minimum effective tax rate for large companies and constituent entities of multinational groups. Options A, C and D all existed under the old companies income tax regime as well."}},{"itemId":"6840048d-3bfd-5d40-b7b0-a7bcc0faced5","questionId":"5d0c2266-e8c4-51a5-a600-6e6f7d61f6c7","sourceKey":"bank:TAX-CM223:GVS-040","payload":{"prompt":"Under the Nigeria Tax Act 2025, an individual whose annual chargeable income is not more than what amount is exempt from personal income tax?","options":["N300,000","N800,000","N1,000,000","N100,000,000"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"Individuals earning N800,000 or less per year are exempt from tax on their income under the Nigeria Tax Act 2025. Option D is the small company turnover limit, not a personal exemption."}},{"itemId":"5f9388a0-a1b1-58ae-b846-b2d914436124","questionId":"8c4a006c-1697-5217-8ceb-feb0bf13ffb0","sourceKey":"bank:TAX-CM223:GVS-041","payload":{"prompt":"Under the 2025 framework, which agency administers VAT on goods and services, and which administers customs duty on imports?","options":["VAT: each State Internal Revenue Service; customs duty: the Nigeria Revenue Service","VAT: the Nigeria Revenue Service; customs duty: the Nigeria Customs Service","VAT: the Nigeria Customs Service; customs duty: the Nigeria Revenue Service","Both: the Joint Revenue Board"],"correctOption":1,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"VAT is administered by the Nigeria Revenue Service, while customs duty remains with the Nigeria Customs Service under the Nigeria Customs Service Act 2023. Option C swaps the agencies, and Option D gives a collecting role to a coordinating board."}},{"itemId":"19772d1d-6d0b-5d7d-8e87-754d43a61649","questionId":"1a829021-4a0d-5568-9f2b-42d0eb0d34f6","sourceKey":"bank:TAX-CM223:GVS-042","payload":{"prompt":"Under the Nigeria Tax Act 2025, how are capital gains of companies (other than small companies) taxed?","options":["At 4% as part of the development levy","They are fully exempt","At the companies income tax rate of 30%","At a flat 10% capital gains tax"],"correctOption":2,"section":"Taxation of Goods and Services: Old Law and the 2025 Acts","explanation":"The Nigeria Tax Act 2025 aligns the tax on companies' chargeable gains with the 30% companies income tax rate, replacing the old 10% capital gains tax. Option D is the old Capital Gains Tax Act rate, and Option A confuses gains with the development levy."}},{"itemId":"3ab60858-9437-5f50-95e7-0eb3ae59b44c","questionId":"4d3139ea-80d5-59e1-a1d0-4b2e30a2cdbc","sourceKey":"bank:TAX-CM223:PQ-012-a","payload":{"prompt":"On 1 January 2026, Agbabiaka LLP bought legal research software for N10,000,000 for use in its practice, expecting to use it for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, at what rate is the annual capital allowance on the software claimed?","options":["10% of cost each year, over the 10-year expected use","50% initial allowance, then 25% of the balance each year","25% of cost each year","20% of cost each year"],"correctOption":2,"section":"Capital Allowances","explanation":"Software expenditure is in the 25% class with motor vehicles and other capital expenditure, and the allowance is a fixed annual rate on original cost. Option A wrongly follows the firm's own 10-year estimate instead of the statutory rate. Option D is the rate for plant and equipment, and option B is wrong because initial allowances no longer exist."}},{"itemId":"a037dbd0-de3d-5eb9-8f87-f5dcd2df0538","questionId":"5251c83b-f477-58ff-8dff-f3ca8bcf448b","sourceKey":"bank:TAX-CM223:PQ-012-b","payload":{"prompt":"On 1 January 2026, Agbabiaka LLP bought legal research software for N10,000,000 for use in its practice, expecting to use it for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, what capital allowance can Agbabiaka claim for 2026?","options":["N1,000,000","N2,000,000","N2,500,000","N5,000,000"],"correctOption":2,"section":"Capital Allowances","explanation":"The allowance is N10,000,000 x 25% = N2,500,000 for 2026, and the same amount in each following year while the software is used in the business. Option A spreads the cost over the 10-year expected use, option B uses the 20% rate, and option D uses 50%."}},{"itemId":"74259be3-46c0-51bf-97da-a05f2dd8ae8a","questionId":"c32a53fe-b8b0-5d4b-811c-605585bd0cb3","sourceKey":"bank:TAX-CM223:PQ-012-c","payload":{"prompt":"On 1 January 2026, Agbabiaka LLP bought legal research software for N10,000,000 for use in its practice, expecting to use it for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, why can't Agbabiaka simply deduct the N10,000,000 as an expense in computing its 2026 profit?","options":["Relief is given only when the software is sold","Only manufacturing companies may claim relief for software","Software is never qualifying capital expenditure","Capital expenditure is not a deductible expense; it is recovered through capital allowances on qualifying capital expenditure"],"correctOption":3,"section":"Capital Allowances","explanation":"Capital spending on an asset that lasts for years is not deductible like an ordinary expense; instead it is recovered gradually through capital allowances, and software is a recognised category of qualifying capital expenditure. Option C is wrong because software qualifies. Option B is wrong because any business using the asset for its trade can claim, and option A is wrong because relief is given annually while the asset is in use."}},{"itemId":"c453578d-6eb8-5432-8ebf-ded5d74b6a98","questionId":"1cc15e30-0262-5ce8-a135-12b2f41249cb","sourceKey":"bank:TAX-CM223:PQ-013-a","payload":{"prompt":"On 1 January 2026, Mega Chicken Poultry Ltd bought poultry cages (agricultural equipment) for N10,000,000 for use on its poultry farm, expecting to use them for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, at what annual rate is capital allowance claimed on agricultural equipment?","options":["10% of cost","50% of cost","20% of cost","25% of cost"],"correctOption":2,"section":"Capital Allowances","explanation":"Agricultural equipment is in the 20% class with plant, furniture and fittings, mining and other equipment. Option A is the rate for the separate agricultural expenditure category in the 10% class, not agricultural equipment. Option D is the rate for motor vehicles and software, and option B is not a class rate."}},{"itemId":"a06b7b44-b7dc-584a-9298-8bd88173e7fd","questionId":"66aca5e4-872c-5e0c-8eea-29592df55544","sourceKey":"bank:TAX-CM223:PQ-013-b","payload":{"prompt":"On 1 January 2026, Mega Chicken Poultry Ltd bought poultry cages (agricultural equipment) for N10,000,000 for use on its poultry farm, expecting to use them for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, what annual capital allowance can Mega Chicken claim for 2026?","options":["N2,500,000","N1,000,000","N2,000,000","N10,000,000"],"correctOption":2,"section":"Capital Allowances","explanation":"At 20% of cost, the annual allowance is N10,000,000 x 20% = N2,000,000, claimed each year over about five years. Option A wrongly uses the 25% rate meant for software and motor vehicles. Option B uses 10%, and option D treats the whole cost as relieved in one year."}},{"itemId":"5779c627-ec39-5183-a1cc-e1dc28152c2f","questionId":"62880292-95bf-5b0f-bcf6-3f7dbc63af47","sourceKey":"bank:TAX-CM223:PQ-013-c","payload":{"prompt":"On 1 January 2026, Mega Chicken Poultry Ltd bought poultry cages (agricultural equipment) for N10,000,000 for use on its poultry farm, expecting to use them for 10 years. Under the First Schedule to the Nigeria Tax Act 2025, which capital allowance can Mega Chicken claim on the cages?","options":["Only an annual allowance at a fixed rate on cost; there is no initial allowance","An allowance only in the year the cages are sold","Nothing, because agricultural assets are outside capital allowances","An initial allowance in 2026 plus an annual allowance on the balance"],"correctOption":0,"section":"Capital Allowances","explanation":"Since 1 January 2026, the only capital allowance is the annual allowance at fixed rates on original cost; the old initial allowance and balancing adjustments are gone. Option D describes the old regime. Option C is wrong because agricultural equipment is a qualifying category, and option B confuses allowances with relief on disposal."}},{"itemId":"591ee16f-4e1f-5ac7-be0f-256c07f8af51","questionId":"6c96784d-933c-5ca2-875d-273c846459e7","sourceKey":"bank:TAX-CM223:PQ-014-a","payload":{"prompt":"On 1 January 2026, Gold Miners Ltd bought mining cranes for N10,000,000 for use in its mining operations, expecting to use them for 5 years. Under the First Schedule to the Nigeria Tax Act 2025, at what annual rate is capital allowance claimed on the cranes?","options":["20% of cost","25% of cost","33.33% of cost","10% of cost"],"correctOption":0,"section":"Capital Allowances","explanation":"Mining expenditure and plant are in the 20% class, so the cranes qualify at 20% of cost each year. Option D is for buildings, agricultural expenditure, masts, intangibles and heavy transportation. Option B is for motor vehicles and software, and option C is not a class rate."}},{"itemId":"2cf8fefc-3ed3-5204-9c7c-2f1d8555eaf4","questionId":"bf178a75-6327-567b-aaed-960a4bb4b2c7","sourceKey":"bank:TAX-CM223:PQ-014-b","payload":{"prompt":"On 1 January 2026, Gold Miners Ltd bought mining cranes for N10,000,000 for use in its mining operations, expecting to use them for 5 years. Under the First Schedule to the Nigeria Tax Act 2025, what capital allowance can Gold Miners claim for 2026?","options":["N5,000,000","N1,000,000","N2,500,000","N2,000,000"],"correctOption":3,"section":"Capital Allowances","explanation":"The allowance is N10,000,000 x 20% = N2,000,000 a year while the cranes are used in the business. Option C uses 25%, option B uses 10%, and option A uses 50%."}},{"itemId":"a4890f06-f55d-50c9-a640-de5b026604d2","questionId":"eba8bf75-20a4-5ce1-a498-e5a5e1f7f286","sourceKey":"bank:TAX-CM223:PQ-014-c","payload":{"prompt":"On 1 January 2026, Gold Miners Ltd bought mining cranes for N10,000,000 for use in its mining operations, expecting to use them for 5 years. Under the First Schedule to the Nigeria Tax Act 2025, which of these would stop the cranes from counting as qualifying capital expenditure?","options":["The cranes are used by the company's own staff","The company is a mining company rather than a manufacturer","The cranes were imported but the import duties on them were not paid","The cranes were bought at the start of the year rather than at the end"],"correctOption":2,"section":"Capital Allowances","explanation":"An imported asset whose import duties have not been paid does not qualify for capital allowances, in the same way that an asset on which VAT was due but not paid does not qualify. Option A is normal business use and does not disqualify the asset. Options D and B are irrelevant, because the asset only needs to be owned and used for the business at the end of the basis period."}},{"itemId":"17023269-41a8-5581-9a7c-e59ace4dc14c","questionId":"60a1a4f5-42fd-5d57-80ad-348d9c4d7838","sourceKey":"bank:TAX-CM223:PQ-015-a","payload":{"prompt":"On 1 January 2026, a commercial bank bought a staff bus for N100,000,000, treated as motor vehicle expenditure under the First Schedule to the Nigeria Tax Act 2025. For 2026 its gross income was N500,000,000 and its allowable expenses (salaries, operating costs) were N200,000,000. It also carries N100,000,000 of tax overpaid for 2025 that has not been refunded. Company income tax is 30%; ignore the development levy and any minimum tax. What capital allowance can the bank claim on the bus for 2026?","options":["N10,000,000","N100,000,000","N25,000,000","N20,000,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Motor vehicles are in the 25% class, so the allowance is N100,000,000 x 25% = N25,000,000 for 2026. Option A spreads the cost over the bank's own 10-year estimate (10%), option D uses the 20% equipment rate, and option B treats the whole cost as deductible at once."}},{"itemId":"42195e39-68f3-5f34-b25b-e799a139f1a8","questionId":"ffd44b06-7d70-584d-81b5-6bc1fd4b63c1","sourceKey":"bank:TAX-CM223:PQ-015-b","payload":{"prompt":"On 1 January 2026, a commercial bank bought a staff bus for N100,000,000, treated as motor vehicle expenditure under the First Schedule to the Nigeria Tax Act 2025. For 2026 its gross income was N500,000,000 and its allowable expenses (salaries, operating costs) were N200,000,000. It also carries N100,000,000 of tax overpaid for 2025 that has not been refunded. Company income tax is 30%; ignore the development levy and any minimum tax. What is the bank's total (taxable) profit for 2026?","options":["N200,000,000","N300,000,000","N175,000,000","N275,000,000"],"correctOption":3,"section":"Capital Allowances","explanation":"Adjusted profit is N500,000,000 - N200,000,000 = N300,000,000, and deducting the N25,000,000 capital allowance gives total profit of N275,000,000. Option C wrongly deducts the overpaid tax from profit; overpaid tax is a credit against tax payable, not an expense. Option B ignores the capital allowance, and option A deducts the full cost of the bus."}},{"itemId":"c8772be2-e66c-5d07-8b5f-1cd4eb8cdc9c","questionId":"f086c732-18a2-5903-a0ec-05424238413e","sourceKey":"bank:TAX-CM223:PQ-015-c","payload":{"prompt":"On 1 January 2026, a commercial bank bought a staff bus for N100,000,000, treated as motor vehicle expenditure under the First Schedule to the Nigeria Tax Act 2025. For 2026 its gross income was N500,000,000 and its allowable expenses (salaries, operating costs) were N200,000,000. It also carries N100,000,000 of tax overpaid for 2025 that has not been refunded. Company income tax is 30%; ignore the development levy and any minimum tax. How does the N100,000,000 overpaid tax affect the bank's 2026 company income tax?","options":["Tax of N52,500,000 (30% of N175,000,000) is payable in cash","Tax of N82,500,000 (30% of N275,000,000) is covered by setting off the overpaid tax, leaving N17,500,000 still due to the bank","Tax of N82,500,000 is payable in cash, and the overpaid tax can only be refunded separately","No tax arises because banks are exempt"],"correctOption":1,"section":"Capital Allowances","explanation":"Company income tax is 30% x N275,000,000 = N82,500,000, and unrefunded overpaid tax can be set off against this liability, so nothing is payable and N17,500,000 remains for refund or future set-off. Option A comes from wrongly deducting the overpaid tax from profit. Option C ignores the set-off, and option D is wrong because banks are taxable companies."}},{"itemId":"0ee2c1e1-5f96-5bd7-9067-c0068f7cafd0","questionId":"e9763970-f25c-57fd-a2e8-6bdb1a82905e","sourceKey":"bank:TAX-CM223:CAP-001","payload":{"prompt":"Why does the Nigeria Tax Act 2025 grant capital allowances to companies?","options":["To replace the companies income tax charge on manufacturing companies","To refund the VAT that companies paid when buying fixed assets","Because capital expenditure is not deductible in computing profits, so allowances give relief for it","Because depreciation charged in the accounts is fully deductible anyway"],"correctOption":2,"section":"Capital Allowances","explanation":"Capital expenditure cannot be deducted as an expense, so the Act lets companies recover qualifying capital expenditure through capital allowances. Option D is wrong because accounting depreciation is not deductible, and Option B confuses capital allowances with input VAT."}},{"itemId":"b4f87219-fff0-54f1-949b-93e7543fc880","questionId":"4d9238f1-35c0-5df2-af2d-2b965fbc94ef","sourceKey":"bank:TAX-CM223:CAP-002","payload":{"prompt":"Under the First Schedule to the Nigeria Tax Act 2025, capital expenditure on assets such as plant, buildings, software and motor vehicles that can attract capital allowances is called:","options":["Qualifying Capital Expenditure (QCE)","Assessable profit","Allowable deductible expenses","Franked investment income"],"correctOption":0,"section":"Capital Allowances","explanation":"Expenditure on qualifying categories of assets is called Qualifying Capital Expenditure, and capital allowances are claimed on it. Option C refers to revenue expenses deducted directly, which cannot also be QCE, and Option B is a profit figure, not a type of expenditure."}},{"itemId":"a5bb76e5-e167-5624-8295-90626414c00b","questionId":"29c22c01-aef4-5a7b-acac-6444b5083882","sourceKey":"bank:TAX-CM223:CAP-003","payload":{"prompt":"Under the Nigeria Tax Act 2025, which condition must an asset meet for a company to claim capital allowance on it for a basis period?","options":["It must have been held for at least five years","It must have been depreciated in the accounts at the same rate","It must have been bought with cash rather than on credit","It must be owned and in use for the business at the end of the basis period"],"correctOption":3,"section":"Capital Allowances","explanation":"Capital allowance is available where the asset is owned and used for business purposes at the end of the relevant basis period. Option B is wrong because tax rates do not depend on accounting depreciation, and Option A invents a holding period."}},{"itemId":"13a3249a-acd9-5ccc-99ab-020fdfe271d0","questionId":"9ee0a516-48f0-5d07-aaa4-9bf9588a0c0c","sourceKey":"bank:TAX-CM223:CAP-004","payload":{"prompt":"Under the First Schedule to the Nigeria Tax Act 2025, what annual capital allowance rate applies to building expenditure?","options":["20%","10%","25%","15%"],"correctOption":1,"section":"Capital Allowances","explanation":"Building expenditure falls in Class 1, which carries an annual allowance of 10% of cost. Option A is the Class 2 rate for plant and equipment, and Option C is the Class 3 rate for motor vehicles and software."}},{"itemId":"fbef1c92-9f92-50e7-a366-aaa01f5a7976","questionId":"ea05b9c3-3cea-5ff1-ace9-6a8b09f07645","sourceKey":"bank:TAX-CM223:CAP-005","payload":{"prompt":"Which of the following is a Class 1 (10%) item under the First Schedule to the Nigeria Tax Act 2025?","options":["Software expenditure","Plant expenditure","Furniture and fittings expenditure","Mast expenditure"],"correctOption":3,"section":"Capital Allowances","explanation":"Class 1 at 10% covers building, agricultural, mast, intangible asset and heavy transportation expenditure. Options B and C are Class 2 at 20%, and Option A is Class 3 at 25%."}},{"itemId":"c8f5c8f6-571b-52cc-8d21-6e24cdcb6148","questionId":"562f8f75-8b7b-5e15-b9ec-f3cfd301e629","sourceKey":"bank:TAX-CM223:CAP-006","payload":{"prompt":"Which of the following is NOT a Class 2 (20%) item under the First Schedule to the Nigeria Tax Act 2025?","options":["Mining expenditure","Furniture and fittings expenditure","Software expenditure","Plant expenditure"],"correctOption":2,"section":"Capital Allowances","explanation":"Class 2 at 20% covers plant, furniture and fittings, agricultural equipment, mining and other equipment; software is in Class 3 at 25%. Options A, B and D are genuine Class 2 items."}},{"itemId":"4608fa46-33cb-5b67-8d7d-06972d5b113b","questionId":"05ac2be4-dce9-5507-b8f7-bd4f683c3d05","sourceKey":"bank:TAX-CM223:CAP-007","payload":{"prompt":"Which group correctly lists the Class 3 (25%) items under the First Schedule to the Nigeria Tax Act 2025?","options":["Plant, mining and other equipment","Agricultural equipment, motor vehicles and buildings","Buildings, masts and intangible assets","Motor vehicles, software and other capital expenditure"],"correctOption":3,"section":"Capital Allowances","explanation":"Class 3 carries the highest rate of 25% and covers motor vehicle, software and other capital expenditure. Option C lists Class 1 items at 10%, and Option A lists Class 2 items at 20%."}},{"itemId":"3256949f-0ebc-5cb7-b921-acc8cf68cdc5","questionId":"5dfe2254-d8c8-5c4c-9627-ef0c7f49de8d","sourceKey":"bank:TAX-CM223:CAP-008","payload":{"prompt":"Under the First Schedule to the Nigeria Tax Act 2025, what annual capital allowance rate applies to furniture and fittings expenditure?","options":["25%","50%","10%","20%"],"correctOption":3,"section":"Capital Allowances","explanation":"Furniture and fittings are in Class 2, which attracts 20% a year on cost. Option C is the Class 1 rate for buildings, and Option A is the Class 3 rate for motor vehicles and software."}},{"itemId":"7f6f6100-e913-59c2-bd9b-a2d9e4d707f5","questionId":"47935707-fcd9-5352-a397-497c94e74453","sourceKey":"bank:TAX-CM223:CAP-009","payload":{"prompt":"Under the First Schedule to the Nigeria Tax Act 2025, intangible asset expenditure attracts capital allowance at:","options":["20% a year","No capital allowance at all","10% a year","25% a year"],"correctOption":2,"section":"Capital Allowances","explanation":"Intangible asset expenditure is listed in Class 1 with buildings, masts and heavy transportation, at 10% a year. Option D is the software rate, which students often confuse with intangibles, and Option B is wrong because intangibles are expressly a qualifying category."}},{"itemId":"f115fa27-1145-5848-8846-a44a39453c5b","questionId":"77243748-bd61-568f-8d26-e97cae504ff7","sourceKey":"bank:TAX-CM223:CAP-010","payload":{"prompt":"How does the First Schedule to the Nigeria Tax Act 2025 treat 'agricultural expenditure' compared with 'agricultural equipment expenditure'?","options":["Both are treated as Class 1 expenditure at 10% a year","Both are treated as Class 2 expenditure at 20% a year","Agricultural expenditure is Class 3 at 25%, while agricultural equipment is Class 1 at 10%","Agricultural expenditure is Class 1 at 10%, while agricultural equipment expenditure is Class 2 at 20%"],"correctOption":3,"section":"Capital Allowances","explanation":"The Act separates agricultural expenditure (Class 1, 10%) from agricultural equipment expenditure (Class 2, 20%). Options A and B merge the two categories, which the Schedule keeps apart."}},{"itemId":"7227ad97-dd99-528a-828a-4ddba36c9cad","questionId":"5f4eeb75-9e8a-598a-b062-3f1b46f7f87e","sourceKey":"bank:TAX-CM223:CAP-011","payload":{"prompt":"Under the First Schedule to the Nigeria Tax Act 2025, mining expenditure attracts capital allowance at:","options":["10% a year on cost","95% in the first year","25% a year on cost","20% a year on cost"],"correctOption":3,"section":"Capital Allowances","explanation":"Mining expenditure is a Class 2 item at 20% of cost each year. Option A is the Class 1 rate, and Option B reflects the kind of large first-year initial allowance that no longer exists."}},{"itemId":"5f7e8655-bfd6-5097-9dfe-40a0530dac4d","questionId":"57d4da1a-817d-50e4-818a-c3341095a884","sourceKey":"bank:TAX-CM223:CAP-012","payload":{"prompt":"Under the Nigeria Tax Act 2025, how is the annual capital allowance on qualifying capital expenditure computed?","options":["As an initial allowance in year one plus annual allowance on the residue","At a fixed class rate on the original cost every year until the cost is fully recovered","At the same rate the company uses for depreciation in its accounts","At a fixed rate on the reducing (written-down) balance each year"],"correctOption":1,"section":"Capital Allowances","explanation":"The Act applies fixed annual rates to the original cost of the asset, the same amount each year, until the full value is recovered. Option D describes reducing balance, and Option A describes the old initial-plus-annual approach."}},{"itemId":"25f390d1-0d86-57a8-9157-e85fcaf49561","questionId":"862f6160-0903-5d4f-8527-bb6e342560ec","sourceKey":"bank:TAX-CM223:CAP-013","payload":{"prompt":"Under the Nigeria Tax Act 2025, what initial allowance is available on qualifying capital expenditure incurred from 1 January 2026?","options":["50% of cost in the first year","None, because the initial allowance has been abolished","An amount equal to the first annual allowance","25% of cost in the first year"],"correctOption":1,"section":"Capital Allowances","explanation":"The Nigeria Tax Act 2025 removed the initial allowance, so the annual allowance is the only capital allowance available. Options A and D describe the type of first-year relief that existed under the old regime."}},{"itemId":"8694cc2d-6141-5cd8-a6e9-265f0172b413","questionId":"1d65a5e2-480e-5e14-8ddc-f7ceca9e9a53","sourceKey":"bank:TAX-CM223:CAP-015","payload":{"prompt":"Ibadan Plastics Ltd bought a machine on which VAT was due but was not paid. Under the Nigeria Tax Act 2025, can it claim capital allowance on the machine?","options":["No, because an asset on which VAT applies and is not paid does not qualify as QCE","Yes, once it pays a penalty equal to the VAT","Yes, in full, because VAT is irrelevant to capital allowances","Yes, but only at half the normal rate"],"correctOption":0,"section":"Capital Allowances","explanation":"An asset on which VAT applies but has not been paid is not qualifying capital expenditure, so no allowance is due. Option C ignores this condition, and Options B and D invent partial or penalty-based relief."}},{"itemId":"be94699c-a5d5-5de9-a698-f34104f08e40","questionId":"1b75a6f7-d2f4-5d0a-aab1-e5afee07eb56","sourceKey":"bank:TAX-CM223:CAP-016","payload":{"prompt":"Kaduna Textiles Ltd imported a loom but has not paid the import duty on it. Under the Nigeria Tax Act 2025, how is the loom treated for capital allowance?","options":["It is not eligible QCE until the import duty is paid","It qualifies at 10% because duty is unpaid","It qualifies, and the unpaid duty is added to its cost","It qualifies at 20% because it is plant"],"correctOption":0,"section":"Capital Allowances","explanation":"An imported asset whose import duties are not paid is not eligible qualifying capital expenditure. Option D gives the normal Class 2 rate without applying the duty condition, and Option C rewards non-payment by inflating the cost."}},{"itemId":"3944eeb9-4d01-5e3d-be94-1590264f84cf","questionId":"abbc87e5-5291-5818-97d5-472c8c4d48bc","sourceKey":"bank:TAX-CM223:CAP-017","payload":{"prompt":"Under the Nigeria Tax Act 2025, how is capital allowance treated on an asset used partly to earn income that is not assessable to tax?","options":["It is always claimed in full, whatever the mix of income","It is disallowed completely for the whole asset","It is prorated only where non-assessable income exceeds 50% of total income","It is prorated to the assessable part, unless non-assessable income is below 10% of total income"],"correctOption":3,"section":"Capital Allowances","explanation":"Where an asset serves both assessable and non-assessable income, the allowance is apportioned, except where the non-assessable income is less than 10% of total income. Option A ignores the proration rule, and Option C uses the wrong threshold."}},{"itemId":"077abeb6-8077-5305-9ca2-887ebb1b1dfc","questionId":"4f9292ee-f52a-5bf2-932a-03ba7ba85046","sourceKey":"bank:TAX-CM223:CAP-018","payload":{"prompt":"Abeokuta Pharma Ltd holds an Economic Development Tax Incentive certificate for a priority product and also runs a non-priority business. Under the Nigeria Tax Act 2025, against which profits can the capital allowance attributable to its priority activities be deducted?","options":["No profits, because incentive companies cannot claim capital allowance at all","Any profits of the company, at its choice","Only the assessable profit of the priority business","Only the profits of the non-priority business"],"correctOption":2,"section":"Capital Allowances","explanation":"Capital allowance attributable to the priority activities of a company enjoying the incentive is deductible only from the assessable profit of the priority business. Options B and D would let the company shelter non-priority profits with priority allowances, which the rule prevents."}},{"itemId":"f2c9304c-6024-5897-8428-dc5e521b196f","questionId":"8678d369-e9ee-5064-98d3-660ac1b5242d","sourceKey":"bank:TAX-CM223:CAP-019","payload":{"prompt":"A company deducted the cost of an item as an allowable business expense in computing its profit. Under the Nigeria Tax Act 2025, can it also treat that cost as QCE?","options":["Yes, but at half the normal capital allowance rate","Yes, a company may claim both a deduction and a capital allowance","Yes, but only if the item costs more than N1 million","No, because expenditure allowed as a deductible expense does not qualify as QCE"],"correctOption":3,"section":"Capital Allowances","explanation":"Expenditure already allowed as a deductible expense cannot also be qualifying capital expenditure, so there is no double relief. Option B would give relief twice for the same cost, and Options A and C invent conditions."}},{"itemId":"ad6ae440-81d8-5c53-ae23-f88db9f7fed7","questionId":"5fa21f0e-fe82-51cb-8cdb-a301b354fb35","sourceKey":"bank:TAX-CM223:CAP-020","payload":{"prompt":"A company bought a foreign machine using foreign exchange obtained at a rate above the official exchange rate. Under the Nigeria Tax Act 2025, how much of the cost is QCE?","options":["The cost at the official rate plus half of the excess","The full naira amount actually paid","Only the cost at the official exchange rate; the excess is excluded","Nothing, because the purchase is disqualified"],"correctOption":2,"section":"Capital Allowances","explanation":"Any amount above the official exchange rate incurred to acquire a capital asset is left out of qualifying capital expenditure. Option B would include the premium, and Option D goes too far because the asset still qualifies at the official rate."}},{"itemId":"b234e1e4-b885-5bab-a18c-1c2d48cdc1e2","questionId":"07d45c71-100f-5723-94d5-3577119ff726","sourceKey":"bank:TAX-CM223:CAP-021","payload":{"prompt":"Under the old Companies Income Tax Act, N10 was retained in the books for each asset until disposal. What is retained under the Nigeria Tax Act 2025?","options":["N10 for each asset, exactly as under the old law","1% of the qualifying capital expenditure, as a notional amount only","10% of the cost, which reduces the allowance claimable","Nothing at all; no amount is retained in the books"],"correctOption":1,"section":"Capital Allowances","explanation":"The Nigeria Tax Act 2025 replaces the N10 retention with 1% of the qualifying capital expenditure, kept as a notional figure until disposal. Option A is the old rule, and Option C confuses the retention with the Class 1 rate and wrongly says it affects claims."}},{"itemId":"37e2f59c-8e87-5d48-8ace-5ac124cc0887","questionId":"af95b989-f05f-512d-86cf-64fb1ab7af09","sourceKey":"bank:TAX-CM223:CAP-022","payload":{"prompt":"Under the old Companies Income Tax Act, capital allowances claimable by many companies were restricted to a fraction of assessable profits. What is the position under the Nigeria Tax Act 2025?","options":["The restriction no longer applies, so the full annual allowance can be claimed","Allowances are now restricted to one-half of assessable profits","Allowances can only be claimed in years with no losses","The two-thirds restriction now applies to all companies, including manufacturers"],"correctOption":0,"section":"Capital Allowances","explanation":"The former two-thirds restriction on capital allowances has been removed, so companies can claim the full allowance. Options B and D impose limits the new Act does not contain."}},{"itemId":"9a490b80-b3ea-5956-9814-47267dac0c33","questionId":"550ca32c-f729-5e65-9492-8ab1d07247f5","sourceKey":"bank:TAX-CM223:CAP-023","payload":{"prompt":"Bello & Partners, a law firm, bought legal research software for its practice. Under the First Schedule to the Nigeria Tax Act 2025, which rate of capital allowance applies?","options":["20%, as other equipment","No allowance, because professional firms cannot claim","25%, as software expenditure","10%, as an intangible asset"],"correctOption":2,"section":"Capital Allowances","explanation":"Software expenditure is a Class 3 item at 25% a year. Option D treats the software as a general intangible asset, but the Schedule lists software separately in Class 3, and Option B is wrong because a firm using the asset for its business can claim."}},{"itemId":"dd6227b6-dec1-5f57-856b-e024fb2e6675","questionId":"e8c0fbd2-b198-578f-aa69-6bcfa861ec95","sourceKey":"bank:TAX-CM223:CAP-024","payload":{"prompt":"Which of the following is NOT a condition or rule for capital allowances under the Nigeria Tax Act 2025?","options":["Import duties on an imported asset must have been paid","Any foreign exchange cost above the official rate is excluded from QCE","An initial allowance must be claimed before any annual allowance","VAT due on the asset must have been paid"],"correctOption":2,"section":"Capital Allowances","explanation":"There is no initial allowance under the Nigeria Tax Act 2025, so it cannot be a condition. Options A, B and D are all genuine rules on what counts as qualifying capital expenditure."}},{"itemId":"0ae86c10-31ae-5db5-b75a-704446ffa874","questionId":"4904caba-d0f0-5384-9638-c7bcd5d422c1","sourceKey":"bank:TAX-CM223:CAP-025","payload":{"prompt":"On 1 January 2026, Ajah Consulting Ltd bought accounting software for N12,000,000 and uses it in its business. Under the First Schedule to the Nigeria Tax Act 2025 (software: 25% a year on cost), what is the annual capital allowance?","options":["N2,250,000","N3,000,000","N1,200,000","N2,400,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Annual allowance = 25% x N12,000,000 = N3,000,000, the same each year. Option D uses the Class 2 rate, and Option A applies 25% to a reduced balance, which the fixed-rate-on-cost method does not do."}},{"itemId":"2737afce-534a-56c8-85a6-f71ea8755088","questionId":"c57911fa-2573-5987-8ff0-f26ffd81f67b","sourceKey":"bank:TAX-CM223:CAP-026","payload":{"prompt":"On 1 January 2026, Ogun Poultry Ltd bought poultry cages for N15,000,000. The cages are classified as agricultural equipment expenditure (Class 2, 20% a year on cost) under the Nigeria Tax Act 2025. What is the annual capital allowance?","options":["N3,000,000","N3,750,000","N1,500,000","N6,000,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Annual allowance = 20% x N15,000,000 = N3,000,000, the same each year until the cost is recovered. Option B applies 25%, the rate for motor vehicles and software, and Option C uses the 10% rate meant for agricultural expenditure such as plantations rather than equipment."}},{"itemId":"c557cca0-dcad-5ecd-9927-bfbcf319ca9a","questionId":"5ad22765-79fc-5b14-943a-858d72acb53d","sourceKey":"bank:TAX-CM223:CAP-027","payload":{"prompt":"On 1 January 2026 a company bought equipment classified as agricultural equipment expenditure (20% a year on cost) under the Nigeria Tax Act 2025, for N8,000,000, expecting to use it for 10 years. Over how many years will the cost be recovered, and in which year is the last allowance claimed?","options":["5 years; the last allowance is claimed for 2031","5 years; the last allowance is claimed for 2030","4 years; the last allowance is claimed for 2029","10 years; the last allowance is claimed for 2035"],"correctOption":1,"section":"Capital Allowances","explanation":"At 20% a year on cost, the allowance is N1,600,000 a year and the cost is recovered in 100/20 = 5 years: 2026, 2027, 2028, 2029 and 2030. Option C uses a 25% rate, and Option D follows the asset's useful life instead of the statutory rate."}},{"itemId":"3594846f-963e-5ab6-950d-c080103f87d7","questionId":"7d9eedd1-a835-5ebd-83c3-a81e2df3193f","sourceKey":"bank:TAX-CM223:CAP-028","payload":{"prompt":"A factory building cost N80,000,000 on 1 January 2026. Under the Nigeria Tax Act 2025 (buildings: 10% a year on cost), what is its tax written-down value after the allowances for 2026, 2027 and 2028?","options":["N72,000,000","N32,000,000","N58,320,000","N56,000,000"],"correctOption":3,"section":"Capital Allowances","explanation":"Allowance = 10% x N80,000,000 = N8,000,000 a year; after 3 years: N80,000,000 - 3 x N8,000,000 = N56,000,000. Option C applies 10% on the reducing balance, and Option A deducts only one year."}},{"itemId":"80aceec5-a991-50ad-8d63-519aeccdf897","questionId":"ffcbc380-8c27-538e-82a7-5095147b3006","sourceKey":"bank:TAX-CM223:CAP-029","payload":{"prompt":"Plant costing N45,000,000 was bought on 1 January 2026. Under the Nigeria Tax Act 2025 (plant: 20% a year on cost), what are the total capital allowances claimed for 2026 and 2027 together?","options":["N16,200,000","N18,000,000","N9,000,000","N22,500,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Each year: 20% x N45,000,000 = N9,000,000; two years = N18,000,000. Option A uses the reducing balance in the second year, and Option D uses the 25% rate."}},{"itemId":"2af4cdf5-512e-5b89-8beb-f8c1e9dce8fe","questionId":"9118add2-6455-5970-9be4-11d1106500ed","sourceKey":"bank:TAX-CM223:CAP-030","payload":{"prompt":"On 1 January 2026 Asaba Foods Ltd acquired: a building N100,000,000, plant N40,000,000, a motor vehicle N16,000,000 and software N8,000,000. Using the Nigeria Tax Act 2025 rates (buildings 10%; plant 20%; motor vehicles and software 25%; all on cost), what is the total capital allowance for 2026?","options":["N24,000,000","N26,000,000","N32,800,000","N22,800,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Building N10,000,000 + plant N8,000,000 + vehicle N4,000,000 + software N2,000,000 = N24,000,000. Option C applies a single 20% rate to everything, and Option D treats software as a 10% intangible."}},{"itemId":"0d460509-cb6a-5956-998f-a7c94613419f","questionId":"01f440ff-4517-5f1d-a2c7-88c0b74e552f","sourceKey":"bank:TAX-CM223:CAP-031","payload":{"prompt":"A company bought a motor vehicle for N20,000,000 (25% a year on cost under the Nigeria Tax Act 2025). It uses the vehicle for both activities, and 30% of the company's total income is not assessable to tax. What capital allowance can it deduct for the year?","options":["N2,800,000","N5,000,000","N3,500,000","N1,500,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Full allowance = 25% x N20,000,000 = N5,000,000; non-assessable income is 30% (not below 10%), so prorate: N5,000,000 x 70% = N3,500,000. Option B ignores proration, and Option D keeps the non-assessable share instead of the assessable share."}},{"itemId":"8a18cf19-fcd1-5ed1-a3d7-3e04389e2fa6","questionId":"d98cc5d9-0fc1-5285-824b-d75dea4e3106","sourceKey":"bank:TAX-CM223:CAP-032","payload":{"prompt":"Jos Mills Ltd has plant costing N30,000,000 (20% a year on cost under the Nigeria Tax Act 2025) used for all its activities. Its total income is N150,000,000, of which N12,000,000 is not assessable. What capital allowance can it claim?","options":["N5,520,000","N7,500,000","N6,000,000","N480,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Non-assessable income = N12,000,000/N150,000,000 = 8%, which is less than 10%, so no proration: allowance = 20% x N30,000,000 = N6,000,000. Option A prorates even though the 10% exception applies."}},{"itemId":"bceedbf9-b1d7-5b2d-bfa0-d36e26a28c22","questionId":"a62ff9be-ddd0-539f-a89c-660fa9a5f03f","sourceKey":"bank:TAX-CM223:CAP-033","payload":{"prompt":"Plant costing N50,000,000 (20% a year on cost under the Nigeria Tax Act 2025) is used for all of a company's activities. Total income is N200,000,000, of which N40,000,000 is not assessable. What capital allowance is deductible?","options":["N9,000,000","N8,000,000","N10,000,000","N2,000,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Non-assessable share = 20%, which is not below 10%, so prorate: 20% x N50,000,000 = N10,000,000, x 80% = N8,000,000. Option C ignores proration, and Option A wrongly cuts the allowance by a flat 10%."}},{"itemId":"26e49efc-c0f9-5873-ba5d-67ab4db7a38b","questionId":"d055ef7c-b29a-51bd-a57b-aeed46dee79e","sourceKey":"bank:TAX-CM223:CAP-034","payload":{"prompt":"A company bought an imported machine for $10,000. It paid N1,700 per dollar, but the official exchange rate was N1,500 per dollar. Under the Nigeria Tax Act 2025 (plant: 20% a year on cost, excess over official rate excluded from QCE), what is the annual capital allowance?","options":["N3,000,000","N3,400,000","N400,000","N3,750,000"],"correctOption":0,"section":"Capital Allowances","explanation":"QCE = $10,000 x N1,500 = N15,000,000 (the excess N2,000,000 is excluded); allowance = 20% x N15,000,000 = N3,000,000. Option B includes the premium paid above the official rate."}},{"itemId":"71021aea-b7b6-5d39-8bc9-70cffbeeffdf","questionId":"bd457ce7-06c2-53f2-950c-3515ba0d2448","sourceKey":"bank:TAX-CM223:CAP-035","payload":{"prompt":"On 1 January 2026 a company bought: plant N24,000,000 (VAT paid), furniture N18,000,000 (VAT due but not paid) and other equipment N6,000,000 (VAT paid). All are Class 2 (20% on cost) under the Nigeria Tax Act 2025. What is the total capital allowance for 2026?","options":["N4,800,000","N6,000,000","N7,500,000","N9,600,000"],"correctOption":1,"section":"Capital Allowances","explanation":"The furniture is not QCE because VAT due on it was not paid; allowance = 20% x (N24,000,000 + N6,000,000) = N6,000,000. Option D includes the furniture, and Option A wrongly drops the other equipment too."}},{"itemId":"497ed9e7-f98a-5032-954d-ee869eee5e9b","questionId":"100ca67b-ad77-5320-b96e-6f745f812c9d","sourceKey":"bank:TAX-CM223:CAP-036","payload":{"prompt":"A company imported two machines (Class 2, 20% on cost under the Nigeria Tax Act 2025): Machine A cost N60,000,000 with import duty paid, and Machine B cost N25,000,000 with import duty unpaid. What capital allowance can it claim for the year?","options":["N5,000,000","N12,000,000","N17,000,000","N7,000,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Only Machine A is eligible QCE: 20% x N60,000,000 = N12,000,000. Machine B is excluded because its import duty is unpaid. Option C includes Machine B, and Option D wrongly nets one cost against the other."}},{"itemId":"e06c6e8a-bb37-5c76-802f-ab4ab65fd749","questionId":"e9b00fa2-089b-58e7-aac8-af0fa7da6efd","sourceKey":"bank:TAX-CM223:CAP-037","payload":{"prompt":"Warri Logistics Ltd (not a small company) has gross income of N400,000,000 and allowable operating expenses of N150,000,000 for 2026. On 1 January 2026 it bought a motor vehicle for N40,000,000 (25% a year on cost under the Nigeria Tax Act 2025). What is its taxable profit after capital allowance?","options":["N250,000,000","N210,000,000","N246,000,000","N240,000,000"],"correctOption":3,"section":"Capital Allowances","explanation":"Adjusted profit = N400,000,000 - N150,000,000 = N250,000,000; capital allowance = 25% x N40,000,000 = N10,000,000; taxable profit = N240,000,000. Option B deducts the full cost of the vehicle, which is a capital expense, and Option C uses 10%."}},{"itemId":"8cfff7b9-d1f0-5e5d-9eec-d3dff118bb17","questionId":"caa26034-cbc8-5849-8b62-8d13d141481c","sourceKey":"bank:TAX-CM223:CAP-038","payload":{"prompt":"Using the Warri Logistics Ltd figures (adjusted profit N250,000,000, capital allowance N10,000,000), what is its companies income tax at 30% under the Nigeria Tax Act 2025?","options":["N60,000,000","N63,000,000","N75,000,000","N72,000,000"],"correctOption":3,"section":"Capital Allowances","explanation":"Taxable profit = N250,000,000 - N10,000,000 = N240,000,000; tax = 30% x N240,000,000 = N72,000,000. Option C ignores the capital allowance, and Option B deducts the full vehicle cost."}},{"itemId":"02e1cf45-08c7-5948-a168-4df7196d89fc","questionId":"e85d2585-fc98-5a06-b232-4e57e3977775","sourceKey":"bank:TAX-CM223:CAP-039","payload":{"prompt":"For 2026 a bank (not a small company) has adjusted profit of N300,000,000 and capital allowance of N25,000,000. It also has N50,000,000 of overpaid tax from 2025 that is available as a credit against its 2026 tax. With companies income tax at 30% under the Nigeria Tax Act 2025, what tax remains payable for 2026?","options":["N82,500,000","N32,500,000","N40,000,000","N67,500,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Taxable profit = N300,000,000 - N25,000,000 = N275,000,000; tax = 30% = N82,500,000; less the N50,000,000 tax credit = N32,500,000. Option D wrongly deducts the overpaid tax from profit before applying 30%; a tax credit reduces tax, not profit."}},{"itemId":"b1231182-b4b5-55e8-bb17-ac170e5a3460","questionId":"d416b733-c5c0-56b3-a95a-f8ac430c767b","sourceKey":"bank:TAX-CM223:CAP-040","payload":{"prompt":"Under the Nigeria Tax Act 2025, a company had been claiming capital allowances on an item of plant under the old Companies Income Tax Act for 3 years. Under the Nigeria Tax Act 2025 plant is written off at 20% a year (5 years). If the transitional rule gives remaining years equal to the new period less the years already claimed, how many more years of allowance remain?","options":["1 year","5 years","3 years","2 years"],"correctOption":3,"section":"Capital Allowances","explanation":"Remaining years = years under the Nigeria Tax Act 2025 (100/20 = 5) - years already claimed (3) = 2 years. Option B ignores the years already claimed, and Option C repeats the years already claimed."}},{"itemId":"3a8679aa-a8c1-59be-af48-657a70d4a869","questionId":"4808b75f-59ad-53f5-a351-bc709a9889c7","sourceKey":"bank:TAX-CM223:CAP-041","payload":{"prompt":"A warehouse was bought on 1 January 2026 and qualifies as building expenditure (10% a year on cost) under the Nigeria Tax Act 2025. If allowances are claimed every year from 2026, for which year is the final allowance claimed?","options":["2036","2030","2029","2035"],"correctOption":3,"section":"Capital Allowances","explanation":"At 10% a year, the cost is recovered over 100/10 = 10 years, from 2026 to 2035 inclusive. Option A counts one year too many, and Option C uses the 20% (5-year) rate."}},{"itemId":"417bb991-4396-5959-b453-ea61b9e237c8","questionId":"4e7f028d-230a-5bdf-9a73-a390c9bb258c","sourceKey":"bank:TAX-CM223:CAP-042","payload":{"prompt":"A company claims an annual capital allowance of N2,400,000 on an asset costing N12,000,000, the same amount each year, under the Nigeria Tax Act 2025. Which class and rate does the asset fall into?","options":["Class 2 at 20%","Class 1 at 10%","Class 2 at 25%","Class 3 at 25%"],"correctOption":0,"section":"Capital Allowances","explanation":"Rate = N2,400,000 / N12,000,000 = 20%, which is the Class 2 rate covering plant, furniture, agricultural equipment, mining and other equipment. Option C attaches the wrong rate to Class 2."}},{"itemId":"d675ebea-6bcd-5dad-9dd5-e5bc3ac41084","questionId":"479cf099-f3c9-5ebb-bbc1-cf07aec8c570","sourceKey":"bank:TAX-CM223:CAP-043","payload":{"prompt":"A telecom company erected a mast for N60,000,000. Under the Nigeria Tax Act 2025 First Schedule (mast expenditure: 10% a year on cost), what is the annual capital allowance?","options":["N6,000,000","N15,000,000","N5,400,000","N12,000,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Annual allowance = 10% x N60,000,000 = N6,000,000. Option D treats the mast as plant at 20%, and Option C applies 10% to a reduced balance."}},{"itemId":"f30c254c-c536-5134-b4e9-9a2ea81904fc","questionId":"8df3efc8-73e3-5cba-95c8-f39e7d2f98b3","sourceKey":"bank:TAX-CM223:CAP-044","payload":{"prompt":"A company acquired a patent (an intangible asset) for N25,000,000. Under the Nigeria Tax Act 2025 (intangible assets: 10% a year on cost), what is the annual capital allowance?","options":["N25,000,000","N5,000,000","N2,500,000","N6,250,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Annual allowance = 10% x N25,000,000 = N2,500,000. Option D uses the 25% software rate, and Option A writes off the whole cost at once, which the Act does not allow."}},{"itemId":"6fca143b-d409-57bd-8ee0-32788b546e43","questionId":"5f3c2c5e-a328-546f-98b3-16ddcac97238","sourceKey":"bank:TAX-CM223:CAP-045","payload":{"prompt":"A hotel bought furniture and fittings for N7,500,000. Under the Nigeria Tax Act 2025 (furniture and fittings: 20% a year on cost), what is the annual capital allowance?","options":["N1,500,000","N1,875,000","N750,000","N1,125,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Annual allowance = 20% x N7,500,000 = N1,500,000. Option B uses the Class 3 rate, and Option C uses the Class 1 rate."}},{"itemId":"6247b136-e21a-5121-9fd8-d93ff8e0d14f","questionId":"e165b57f-e079-5073-8ace-d2b365c519a1","sourceKey":"bank:TAX-CM223:CAP-046","payload":{"prompt":"A shipping company incurred N500,000,000 classified as heavy transportation expenditure under the First Schedule to the Nigeria Tax Act 2025 (10% a year on cost). What is the annual capital allowance?","options":["N50,000,000","N100,000,000","N125,000,000","N45,000,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Annual allowance = 10% x N500,000,000 = N50,000,000. Option C treats it as an ordinary motor vehicle at 25%, but heavy transportation is a Class 1 item."}},{"itemId":"77ab0e5c-c712-5879-af30-f82440dc6cb1","questionId":"a026f66b-6c6a-58e9-a148-f2b79f24b0a8","sourceKey":"bank:TAX-CM223:CAP-047","payload":{"prompt":"A company incurred N4,000,000 classified as 'other capital expenditure' under the First Schedule to the Nigeria Tax Act 2025 (25% a year on cost). What is the annual capital allowance?","options":["N2,000,000","N800,000","N1,000,000","N400,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Other capital expenditure is in Class 3: 25% x N4,000,000 = N1,000,000. Option B confuses it with 'other equipment', which is Class 2 at 20%."}},{"itemId":"93829645-9891-533d-9297-d865c53af41a","questionId":"12210868-2ef4-5dbf-b9fb-babccfcb71bc","sourceKey":"bank:TAX-CM223:CAP-048","payload":{"prompt":"A saloon car (motor vehicle expenditure) cost N30,000,000 on 1 January 2026. Under the Nigeria Tax Act 2025 (25% a year on cost), what is its tax written-down value after the 2026 and 2027 allowances?","options":["N16,875,000","N15,000,000","N18,000,000","N22,500,000"],"correctOption":1,"section":"Capital Allowances","explanation":"Allowance = 25% x N30,000,000 = N7,500,000 a year; after 2 years: N30,000,000 - N15,000,000 = N15,000,000. Option A uses the reducing-balance method."}},{"itemId":"4aa65d56-c47e-5414-bedf-beac6469f864","questionId":"11574ecc-0e59-549e-8406-41adfce316f3","sourceKey":"bank:TAX-CM223:CAP-049","payload":{"prompt":"An asset with qualifying capital expenditure of N50,000,000 is held by a company. Under the Nigeria Tax Act 2025, what amount must be retained in the books as a notional value until disposal?","options":["N10","N500,000","N5,000,000","N12,500,000"],"correctOption":1,"section":"Capital Allowances","explanation":"The retention is 1% of qualifying capital expenditure: 1% x N50,000,000 = N500,000. Option A is the old N10 retention, and Option C confuses the retention with the 10% Class 1 rate."}},{"itemId":"eb426086-eaad-5d23-9544-1116fedc004c","questionId":"55c41d18-0d03-5cb6-b168-5e76cd20491f","sourceKey":"bank:TAX-CM223:CAP-050","payload":{"prompt":"Gold Diggers Ltd bought mining cranes for N36,000,000 on 1 January 2026, classified as mining expenditure (20% a year on cost) under the Nigeria Tax Act 2025. What is the cumulative capital allowance claimed by the end of 2028?","options":["N27,000,000","N14,400,000","N21,600,000","N36,000,000"],"correctOption":2,"section":"Capital Allowances","explanation":"Annual allowance = 20% x N36,000,000 = N7,200,000; for 2026, 2027 and 2028: 3 x N7,200,000 = N21,600,000. Option B counts only two years, and Option D uses 25%."}},{"itemId":"d09160b3-0424-5f33-861b-1735918f0016","questionId":"4388e837-b227-5052-8f4f-af2b0b187294","sourceKey":"bank:TAX-CM223:CAP-051","payload":{"prompt":"Software bought on 1 January 2026 is written off at 25% a year on cost under the Nigeria Tax Act 2025. After the allowances for 2026, 2027 and 2028 have been claimed, how many years of allowance remain?","options":["1 year","2 years","7 years","None"],"correctOption":0,"section":"Capital Allowances","explanation":"At 25% a year, software is recovered over 100/25 = 4 years (2026-2029). After 3 years, 4 - 3 = 1 year remains. Option C assumes a 10-year write-off, and Option D forgets the 2029 claim."}},{"itemId":"96576b6d-dd97-5cfc-84b9-0c3efa391592","questionId":"8ee99a63-d8ef-51ff-9923-b8dd6324f0df","sourceKey":"bank:TAX-CM223:CAP-052","payload":{"prompt":"On 1 January 2026 a company bought plant for N40,000,000 (20% on cost) and a building for N120,000,000 (10% on cost) under the Nigeria Tax Act 2025. What are the total capital allowances claimed on both assets for 2026, 2027 and 2028 combined?","options":["N60,000,000","N96,000,000","N84,000,000","N20,000,000"],"correctOption":0,"section":"Capital Allowances","explanation":"Annual total = 20% x N40,000,000 + 10% x N120,000,000 = N8,000,000 + N12,000,000 = N20,000,000; over 3 years = N60,000,000. Option D is one year only, and Option C swaps the two rates."}},{"itemId":"57a15813-0ac9-5022-8f82-81f3f884ab2d","questionId":"fa5ae9ba-af09-5e25-8a8b-7b5214025e6c","sourceKey":"bank:TAX-CM223:CAP-053","payload":{"prompt":"Ikoyi Chambers LLP bought legal research software on 1 January 2026 for N18,000,000, expecting to use it for 10 years. Under the Nigeria Tax Act 2025 (software: 25% a year on cost), what is the annual capital allowance?","options":["N4,500,000","N3,600,000","N1,800,000","N18,000,000"],"correctOption":0,"section":"Capital Allowances","explanation":"The statutory rate, not the expected life, decides the allowance: 25% x N18,000,000 = N4,500,000 a year for 4 years. Option C spreads the cost over the 10-year expected life (in effect a 10% rate), and Option D writes off the whole cost at once, which the fixed annual rates do not allow."}},{"itemId":"d1d339da-9014-5a5f-83d8-b2b79c18ceee","questionId":"ff5470e6-8411-5a30-af31-2621c39f7abc","sourceKey":"bank:TAX-CM223:PQ-001-a","payload":{"prompt":"Under the Nigeria Tax Act 2025, what does the Economic Development Tax Incentive give a company operating in a designated priority sector?","options":["A tax credit of 5% per annum of its qualifying capital expenditure, for an initial period of five years","An initial allowance of 50% on all its qualifying capital expenditure in the first year","An exemption from charging VAT on all its sales for ten years","A full income tax holiday of three years, extendable by two years"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"The Economic Development Tax Incentive works as a tax credit: a priority-sector company earns a credit of 5% of each qualifying capital expenditure every year for an initial five years and uses it to offset tax on profits from its priority products. Option D describes the old pioneer status tax holiday, which this incentive replaced. Option B is wrong because initial allowances no longer exist under the 2025 framework, and option C is not part of the incentive."}},{"itemId":"cde521a9-ec37-5efe-929d-291c9b852010","questionId":"69d6e827-a80f-56bc-8c41-a9701d449044","sourceKey":"bank:TAX-CM223:PQ-001-b","payload":{"prompt":"The Economic Development Tax Incentive under the Nigeria Tax Act 2025 replaced which earlier incentive for companies in priority industries?","options":["Pioneer status (the income tax holiday for pioneer industries)","Small company relief","Capital gains tax rollover relief","Free trade zone status"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Pioneer status used to give approved companies an income tax holiday; the 2025 reform replaced it with a credit-based Economic Development Tax Incentive tied to qualifying capital expenditure. Option D is a separate regime that still exists for licensed zone entities, and option B is a separate relief for companies under the small company thresholds. Option C has nothing to do with priority-sector incentives."}},{"itemId":"16951e2f-128b-5e5d-a67b-cd43461a38ce","questionId":"dd32b8d1-4e96-5572-94e3-7b701568b242","sourceKey":"bank:TAX-CM223:PQ-001-c","payload":{"prompt":"A company holding an Economic Development Tax Incentive certificate under the Nigeria Tax Act 2025 wants its initial five-year incentive period extended by a further five years. What condition must it meet?","options":["It must reinvest 100% of its profits from the incentive period in expanding the same product(s)","It must employ at least 1,000 Nigerian staff","It must list its shares on the Nigerian Exchange","It must export at least 75% of its output"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"The extension for another five years is a reward for full reinvestment: the company must plough 100% of its profits from the incentive period back into expanding the same products. Option D sounds like the free trade zone sales test, which is a different regime. Options B and C are not conditions for the extension."}},{"itemId":"8706561f-76d5-570c-ad95-276a21c4e489","questionId":"2aec9465-08d0-5b00-af99-42c01e98de70","sourceKey":"bank:TAX-CM223:PQ-001-d","payload":{"prompt":"Under the Nigeria Tax Act 2025, until 31 December 2027 a free trade zone entity keeps its full tax exemption provided that its sales to the Nigerian customs territory do not exceed what share of its total sales?","options":["50%","25%","10%","75%"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"A free zone entity stays fully exempt where its sales come from exports (or inputs for exports) and not more than 25% of its sales go into the Nigerian customs territory; above that, its profits on sales to the customs territory become taxable. Option D mixes this up with the other side of the same test, since at least 75% of sales must be for export. Options C and A are not the statutory threshold."}},{"itemId":"77b825f7-0858-568c-bfd2-53e33d492016","questionId":"30b19b4d-f656-5ac2-adbe-94d66ced3153","sourceKey":"bank:TAX-CM223:PQ-001-e","payload":{"prompt":"Under the Nigeria Tax Act 2025, what changes for free trade zone entities from 1 January 2028, unless the date is extended by Presidential order?","options":["They may sell up to 50% of their output in the customs territory tax-free","They pay a flat 2% levy on turnover instead of income tax","Their profits from exports also become fully taxable","Their profits from sales to the Nigerian customs territory become fully taxable, whatever the percentage of such sales"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"From 1 January 2028 the 25% cushion disappears: any sales into the customs territory are fully taxable, even small ones, although the President may defer this date by order. Option C is wrong because export-related profits keep their exemption. Options A and B are not provisions of the Act."}},{"itemId":"045b2428-5708-5de5-bce6-2516bdc05efa","questionId":"16ca2f43-0c4c-5256-a9f0-6402404ee2af","sourceKey":"bank:TAX-CM223:PQ-001-f","payload":{"prompt":"Under the Nigeria Tax Act 2025, a 'small company' that pays company income tax at 0% is one whose","options":["annual gross turnover is N50,000,000 or less and total fixed assets do not exceed N100,000,000","annual gross turnover is N100,000,000 or less and total fixed assets do not exceed N250,000,000 (professional service providers excluded)","annual gross turnover is N25,000,000 or less, with no fixed asset test","assessable profit is N100,000,000 or less, whatever its turnover"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Small company status under the 2025 Acts uses two tests together: gross turnover of N100,000,000 or less and fixed assets not above N250,000,000, with businesses providing professional services excluded. Such companies pay 0% company income tax and are also outside the development levy. Option C reflects the old, much lower turnover threshold, and option D wrongly uses profit instead of turnover."}},{"itemId":"38e4334f-16c8-52a6-8712-6228d8c1b4fc","questionId":"9cf45024-22cf-5f4d-84e2-5b146c335794","sourceKey":"bank:TAX-CM223:PQ-001-g","payload":{"prompt":"Under the Nigeria Tax Act 2025, companies engaged in primary agricultural businesses such as crop production, livestock or dairy farming enjoy an income tax exemption for","options":["as long as they reinvest all their profits","their first two years of operation","their first five years of operation","their first ten years of operation"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The 2025 Acts give new agricultural businesses in primary production an initial tax-free period of five years to encourage investment in food production. Options B and D give the wrong length of the period. Option A borrows the reinvestment idea from the Economic Development Tax Incentive extension, which is a different incentive."}},{"itemId":"2c2ebd8c-8e42-53cc-a2c6-9d63d1251360","questionId":"616f7a34-b1ad-52f6-87b2-7af936ada1e4","sourceKey":"bank:TAX-CM223:INC-001","payload":{"prompt":"Under the Nigeria Tax Act 2025, the profits of a licensed free trade zone or export processing zone entity are fully exempt from tax where:","options":["Its sales are wholly for export, or not more than 25% of its sales go to the customs territory","It is owned 100% by Nigerian shareholders resident in Nigeria","It sells at least 25% of its output in the Nigerian customs territory","It employs at least 25 Nigerian staff in its zone operations"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Full exemption applies where the entity's sales come from exports, or from inputs into goods or services exclusively meant for export, or where no more than 25% of its total sales go to the customs territory. Option C reverses the test, and Options B and D are not conditions in the Act."}},{"itemId":"834f8338-2133-5a99-8e33-83ef6625c337","questionId":"015b224d-31e7-5c1b-8015-5163e7c37a50","sourceKey":"bank:TAX-CM223:INC-002","payload":{"prompt":"In the free trade zone rules of the Nigeria Tax Act 2025, what does the 'customs territory' refer to?","options":["The fenced area inside a licensed free trade zone","Only the seaports and airports through which goods enter Nigeria","Countries outside Nigeria to which free zone entities export","The part of Nigeria outside the free zones, under normal customs and tax rules"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The customs territory is the rest of Nigeria outside the zones; sales into it are treated as domestic sales. Option C describes export markets, and Option A is the zone itself, where the entity operates."}},{"itemId":"02ebda74-29fb-5db5-aa47-1dfd31df0004","questionId":"31e44351-8d9d-581b-8ec9-af7de904d861","sourceKey":"bank:TAX-CM223:INC-003","payload":{"prompt":"Lekki Zone Manufacturing Ltd, a licensed free zone entity, sells 35% of its output into the Nigerian customs territory in 2026. Under the Nigeria Tax Act 2025, what is the tax effect?","options":["Its profits in respect of sales to the customs territory become taxable in Nigeria","It loses its licence and is wound up","Only 10% of its profits are taxable","It remains fully exempt because it is licensed in a free zone"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Once more than 25% of a free zone entity's sales go to the customs territory, tax accrues on its profits in respect of those customs-territory sales. Option D ignores the 25% limit, and Option B confuses a tax consequence with licensing."}},{"itemId":"854d912c-836d-5d70-9ee3-c2796b3410a7","questionId":"3f77adae-396c-5cc8-9ec9-7b8bd9776ca7","sourceKey":"bank:TAX-CM223:INC-004","payload":{"prompt":"Under the Nigeria Tax Act 2025, from what date will a free zone entity's profits from sales to the customs territory be fully taxable, whatever the percentage of such sales?","options":["26 June 2025, when the Act was signed","1 January 2026, when the Act commenced","1 January 2028, unless extended by Presidential order","1 January 2030, without any order"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"From 1 January 2028, profits from sales to the customs territory become fully taxable regardless of the 25% threshold, unless the date is extended by Presidential order. Option B is the commencement date of the Act, when the 25% rule starts."}},{"itemId":"ad158c8c-8284-5c0b-bc01-e624d9a6cf85","questionId":"6a36046e-1729-5172-b0e2-5207325d31b7","sourceKey":"bank:TAX-CM223:INC-005","payload":{"prompt":"Under the Nigeria Tax Act 2025, the President may extend the 1 January 2028 date for taxing free zone entities' customs-territory sales for up to how long?","options":["Up to 10 years from the commencement of the Nigeria Tax Act 2025","Indefinitely, with no limit","Up to 25 years from the entity's licence date","Up to 2 years from 1 January 2028"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"The President may, by order, extend the date for up to 10 years from the commencement of the Nigeria Tax Act 2025. Option B ignores the statutory limit, and Option C confuses the 25% sales threshold with a time period."}},{"itemId":"cf1c95c2-7758-5246-8900-2d9922e8ba96","questionId":"02826211-1fa7-5b4b-b2e6-0fecc324f492","sourceKey":"bank:TAX-CM223:INC-006","payload":{"prompt":"In 2028, with no Presidential extension in force, a free zone entity sells 10% of its output to the customs territory. Under the Nigeria Tax Act 2025, how are profits from those sales treated?","options":["Only half of those profits are taxable","They are taxable, because from 2028 customs-territory sales are taxable whatever the percentage","They are exempt, because 10% is below the 25% threshold","They are exempt, because free zone entities are never taxed"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"From 1 January 2028, the 25% safe harbour falls away, so profits from any level of sales into the customs territory are taxable. Option C applies the pre-2028 rule."}},{"itemId":"f8f16de2-7a12-5f57-a152-27bb2651ebee","questionId":"bcbfb50c-9a70-54e9-8b5c-2c240ee0b540","sourceKey":"bank:TAX-CM223:INC-007","payload":{"prompt":"In 2026 a licensed free zone entity has total sales of N600,000,000, of which N120,000,000 are to the Nigerian customs territory and the rest are exports. Under the Nigeria Tax Act 2025, what percentage of its sales goes to the customs territory, and is it fully exempt?","options":["25%; taxable on customs-territory sales","20%; fully exempt","20%; taxable on customs-territory sales","80%; fully exempt only if it pays a levy"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Customs-territory share = N120,000,000 / N600,000,000 = 20%, which is not more than 25%, so the entity is fully exempt in 2026. Option A divides by export sales instead of total sales, giving 25%."}},{"itemId":"91b4b5a7-3782-58a1-9035-f12ec5bbf642","questionId":"a9a95dab-b1f9-5f55-8742-d3121641c151","sourceKey":"bank:TAX-CM223:INC-008","payload":{"prompt":"In 2026 a free zone entity has total sales of N800,000,000, including N280,000,000 to the customs territory. Its profit on those customs-territory sales is N60,000,000. With companies income tax at 30% under the Nigeria Tax Act 2025 (the entity is not a small company), what tax is payable?","options":["N6,300,000","N15,000,000","Nil, because the entity is in a free zone","N18,000,000"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"Share = N280,000,000/N800,000,000 = 35%, above 25%, so profits on customs-territory sales are taxable: 30% x N60,000,000 = N18,000,000. Option C ignores the 25% limit, and Option A wrongly scales the profit a second time."}},{"itemId":"d2065d3c-8e93-5295-8e16-c9db7668a72a","questionId":"9ad0c52d-6341-54a7-ba6b-e87c6c70338f","sourceKey":"bank:TAX-CM223:INC-009","payload":{"prompt":"In 2027 a free zone entity sells N100,000,000 to the customs territory out of total sales of N400,000,000. Under the Nigeria Tax Act 2025, what is its position?","options":["75% of sales; fully exempt as an exporter","25% of sales; fully exempt, as the share is not more than 25%","25% of sales; taxable, because the limit is less than 25%","33% of sales; taxable on customs-territory sales"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Share = N100,000,000/N400,000,000 = 25%. The exemption holds where sales to the customs territory are not more than 25%, so exactly 25% is still exempt in 2027. Option D divides by export sales (N300,000,000), and Option A gives the export share instead."}},{"itemId":"ca1332a6-40d2-57ac-932f-5b40f0bc58f3","questionId":"4e2eb220-6bff-52fe-bead-63a55f610c56","sourceKey":"bank:TAX-CM223:INC-010","payload":{"prompt":"In 2026 a free zone entity makes total profit of N200,000,000. 40% of its sales are to the customs territory, and profit is earned evenly across all sales. With companies income tax at 30% under the Nigeria Tax Act 2025, what tax is payable?","options":["N9,000,000","Nil","N24,000,000","N60,000,000"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"40% exceeds 25%, so profits on customs-territory sales are taxable: 40% x N200,000,000 = N80,000,000; tax = 30% = N24,000,000. Option D taxes all profits including exports, and Option A taxes only the excess over 25%."}},{"itemId":"f893b46f-5bec-5a1e-ba93-37b7e124f8c0","questionId":"1187a909-6b2f-52c5-928f-ca04cb4d8d37","sourceKey":"bank:TAX-CM223:INC-011","payload":{"prompt":"In 2028 (no Presidential extension) a free zone entity sells 10% of its output in the customs territory, earning a profit of N20,000,000 on those sales. With companies income tax at 30% under the Nigeria Tax Act 2025, what tax is due on those profits?","options":["N6,000,000","N5,000,000","Nil","N600,000"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"From 1 January 2028, customs-territory sales are taxable regardless of percentage: 30% x N20,000,000 = N6,000,000. Option C applies the pre-2028 25% safe harbour, and Option D multiplies by the 10% share even though N20,000,000 is already the profit on those sales."}},{"itemId":"327a2377-9183-5eb4-8a76-df8908c02891","questionId":"ab96f8a7-faa2-5f8a-8782-435798f09633","sourceKey":"bank:TAX-CM223:INC-012","payload":{"prompt":"Which non-tax privileges continue for free zone entities after the Nigeria Tax Act 2025 removed their blanket tax exemption?","options":["Exemption from filing any tax returns","Privileges such as 100% foreign ownership and repatriation of profits","Freedom to sell any amount in the customs territory tax-free","Exemption from registering with the Nigeria Revenue Service"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"The blanket tax exemption provisions of the zone laws were repealed, but non-fiscal privileges such as 100% foreign ownership and profit repatriation remain. Options A and D are wrong because free zone entities must still register and file returns, and Option C ignores the 25% limit."}},{"itemId":"460ca050-6784-574a-87c2-706cd8edf07d","questionId":"5e9b04ec-548b-5303-af04-e4b6461bc943","sourceKey":"bank:TAX-CM223:INC-013","payload":{"prompt":"Which of the following statements about free zone entities under the Nigeria Tax Act 2025 is NOT correct?","options":["A free zone entity remains fully exempt however much it sells in the customs territory","Profits are fully exempt where sales are wholly exports or inputs for exports","Sales to the customs territory above 25% make the related profits taxable","From 1 January 2028, customs-territory sales become taxable regardless of percentage, unless extended"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"The exemption is limited: above 25% of sales to the customs territory, the related profits are taxable, and from 2028 any such sales are taxable. Options B, C and D correctly describe the rules."}},{"itemId":"77fb9d7a-46c4-5ad2-b1a6-320f96313df7","questionId":"94e932c9-a567-54fb-af4a-c268af39fecf","sourceKey":"bank:TAX-CM223:INC-014","payload":{"prompt":"Under the Nigeria Tax Act 2025, the Economic Development Tax Incentive replaces which earlier incentive?","options":["Free trade zone exemption","Investment allowance","Rural investment allowance","Pioneer Status Incentive"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The Economic Development Tax Incentive replaces the Pioneer Status Incentive, which was granted under the repealed Industrial Development (Income Tax Relief) Act. Option A is a separate regime that continues in a modified form."}},{"itemId":"171d5b5a-3258-5fb2-84bc-ef48176a81ac","questionId":"6ea187fd-f502-5df8-b081-1d2e037a119a","sourceKey":"bank:TAX-CM223:INC-015","payload":{"prompt":"How does the Economic Development Tax Incentive under the Nigeria Tax Act 2025 differ from the old Pioneer Status Incentive?","options":["It gives a tax credit based on qualifying capital expenditure instead of a blanket tax holiday","It exempts all dividends of the company permanently","It applies only to companies outside Nigeria","It gives a longer blanket tax holiday of 10 years"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Pioneer status gave a full tax holiday, whereas the Economic Development Tax Incentive gives an economic development tax credit linked to qualifying capital expenditure. Option D describes a blanket exemption, which the new regime moves away from."}},{"itemId":"3ef4f47b-b6e7-5a52-bf91-e34c0d350194","questionId":"a6a914a2-d02e-5cb4-b46c-ec90b58b1442","sourceKey":"bank:TAX-CM223:INC-016","payload":{"prompt":"Under the Nigeria Tax Act 2025, who may apply for an economic development incentive certificate?","options":["A Nigerian-incorporated company, or promoters of a proposed company, meeting the QCE threshold","Any foreign company exporting goods to Nigeria, whatever its investment","Any individual sole trader operating in a priority sector","Only companies listed on the Nigerian Exchange with a priority product"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Applications may be made by a company incorporated in Nigeria (including promoters of a company not yet incorporated) whose qualifying capital expenditure on or before production day meets the threshold. Options B and C fall outside the eligible applicants, and Option D adds a listing condition that does not exist."}},{"itemId":"c392539e-184d-5b0a-96ee-3f9138202c3e","questionId":"d43c9167-c3a9-58e5-9e79-c512f32d96df","sourceKey":"bank:TAX-CM223:INC-017","payload":{"prompt":"Under the Nigeria Tax Act 2025, where are the minimum qualifying capital expenditure thresholds for each priority sector set out?","options":["In the Second Schedule to the Act","In the Tenth Schedule to the Act","In the Nigeria Customs Service Act 2023","In the First Schedule to the Act"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"The Tenth Schedule lists the priority sectors and the qualifying capital expenditure each must reach on or before production day. Option D contains the capital allowance rules, and Option A contains the free zone rules."}},{"itemId":"74e5739f-2422-58c2-a459-52b7709842b0","questionId":"bbd261f8-2586-55f8-bdc0-21ccb8b2cf8c","sourceKey":"bank:TAX-CM223:INC-018","payload":{"prompt":"To which body is an application for an economic development incentive certificate made under the Nigeria Tax Act 2025, and who finally approves it?","options":["Application to the Nigeria Revenue Service; approval by the Joint Revenue Board","Application to the Nigeria Customs Service; approval by the Minister of Trade","Application to the Nigerian Investment Promotion Commission (NIPC); approval by the President","Application to the Corporate Affairs Commission; approval by the National Assembly"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The application goes to the NIPC, which recommends it through the Minister to the President for approval. Option A names the tax collector and coordinating board, which do not grant the certificate."}},{"itemId":"18194dcf-39b3-50e9-b657-09877728dad1","questionId":"9bf0e09e-1259-56ce-9f16-15cc45537345","sourceKey":"bank:TAX-CM223:INC-019","payload":{"prompt":"Under the Nigeria Tax Act 2025, once the President approves an existing company's application for an economic development incentive certificate, within what time must the NIPC issue the certificate?","options":["Within 6 months after the approval","Within 7 days after the approval","Within 3 months after production day","Within 30 days after the approval"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The NIPC must issue the certificate and notify the applicant within 30 days of the President's approval. Option C confuses this with the three-month period for incorporating a proposed company."}},{"itemId":"d09fee47-0724-5ea6-a7ac-3b624c68e49f","questionId":"24588406-3be5-5648-81a5-cda3aba65c1b","sourceKey":"bank:TAX-CM223:INC-021","payload":{"prompt":"Under the Nigeria Tax Act 2025, how long is the initial economic development incentive period, and when does it start?","options":["Ten years, starting from the date of application","Five years, starting from the company's production day","Three years, starting from the date of incorporation","Five years, starting from 1 January 2026 for all companies"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"The incentive period is five years and commences on the production day of the company. Option C uses the old pioneer-style three-year period and the wrong start date, and Option D wrongly ties every company to the Act's commencement."}},{"itemId":"4c72cd54-f547-5640-8304-a64a0b362f4c","questionId":"c92120fe-3969-5d24-a357-09b9fa97217f","sourceKey":"bank:TAX-CM223:INC-022","payload":{"prompt":"Under the Nigeria Tax Act 2025, on what condition can the initial five-year economic development incentive period be extended for another five years?","options":["If the company pays an extension fee of 0.1% of its turnover","If the company exports at least 25% of its output each year","If the company reinvests 100% of its profits during the incentive period to expand the same product(s)","If the company employs more than 500 Nigerians during the period"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The period may be extended by a further five years where the company reinvests all of its profits to expand the same priority product line. Option A confuses the extension with the application fee, and Option B borrows the free zone 25% figure."}},{"itemId":"a551dc2b-1785-5cf2-94b2-f2c8bd379aa4","questionId":"eb7e10b5-ae75-59dc-bb9f-a9e1efe3998e","sourceKey":"bank:TAX-CM223:INC-023","payload":{"prompt":"Under the Nigeria Tax Act 2025, at what rate is the economic development tax credit earned on qualifying capital expenditure?","options":["5% of qualifying capital expenditure per year for five years","10% of turnover per year","100% of qualifying capital expenditure in year one","30% of qualifying capital expenditure in the first year only"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"The incentive gives an annual tax credit of 5% of qualifying capital expenditure for five years. Option D confuses the credit with the companies income tax rate, and Option B uses turnover instead of capital expenditure."}},{"itemId":"cb4b002a-a560-5b57-8c3c-0357346e3036","questionId":"65e4c93f-cb34-570f-a6e4-1cedd8331088","sourceKey":"bank:TAX-CM223:INC-024","payload":{"prompt":"Kogi Steel Ltd holds an economic development incentive certificate and incurred qualifying capital expenditure of N3,000,000,000. Under the Nigeria Tax Act 2025 (credit of 5% of QCE per year for five years), what is the annual economic development tax credit?","options":["N900,000,000","N30,000,000","N150,000,000","N750,000,000"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"Annual credit = 5% x N3,000,000,000 = N150,000,000. Option D is the total credit over five years, and Option B wrongly spreads the annual figure over five years again."}},{"itemId":"1abc2cf0-7d67-52f9-a276-4147a6f1b15f","questionId":"bac30f54-4e0c-57ac-b8b1-c3576c06a6c6","sourceKey":"bank:TAX-CM223:INC-025","payload":{"prompt":"A priority company incurred qualifying capital expenditure of N3,000,000,000. Under the Nigeria Tax Act 2025 (credit of 5% of QCE per year for five years), what is the total credit earned over the five-year period?","options":["N150,000,000","N1,500,000,000","N3,000,000,000","N750,000,000"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"Total credit = 5% x N3,000,000,000 x 5 = 25% x N3,000,000,000 = N750,000,000. Option A is one year's credit, and Option C assumes the full expenditure is credited."}},{"itemId":"4ab0726a-4580-5454-8d72-2e07fe905d7d","questionId":"49107250-90f8-53f0-b85b-9ee6b5f23a53","sourceKey":"bank:TAX-CM223:INC-026","payload":{"prompt":"In year 1 of its incentive period a priority company earns an economic development tax credit of 5% of its N2,000,000,000 qualifying capital expenditure. Its tax payable on priority profits for the year is N60,000,000. Under the Nigeria Tax Act 2025, how much credit is left unused to carry forward?","options":["N40,000,000","N60,000,000","Nil, because unused credit is lost immediately","N100,000,000"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Credit = 5% x N2,000,000,000 = N100,000,000; used against tax payable N60,000,000; unused = N40,000,000. Option D forgets the credit used, and Option C ignores the carry-forward rule."}},{"itemId":"a5fea030-2c4e-54a3-9dcd-80a9e24e9f60","questionId":"fa5b819a-518e-585b-b437-e96612edfb7d","sourceKey":"bank:TAX-CM223:INC-027","payload":{"prompt":"Under the Nigeria Tax Act 2025, what happens to economic development tax credit that remains unused at the end of the priority period?","options":["It lapses immediately at the end of the priority period","It may be used within five years after the priority period, after which any balance lapses","It is refunded in cash by the Nigeria Revenue Service","It can be carried forward indefinitely"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Unused credit can be utilised within five years of assessment after the priority period ends; anything still unused then lapses. Option C is wrong because the credit is not refundable in cash, and Option D ignores the five-year limit."}},{"itemId":"ce908cf9-1fb6-5687-aa77-1f6e3987b8af","questionId":"c114f97e-fcf8-595c-8c70-3c6b2afb0440","sourceKey":"bank:TAX-CM223:INC-028","payload":{"prompt":"Under the Nigeria Tax Act 2025, which liability can the economic development tax credit NOT be used to offset?","options":["Tax payable in any year within the priority period","Companies income tax on profits from the priority product","Additional tax payable under the minimum effective tax rate rules","Tax on priority profits in the first year of the incentive period"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The credit offsets tax payable during the priority period but cannot reduce the additional (top-up) tax payable under the minimum effective tax rate rules. Options A, B and D are liabilities the credit is designed to offset."}},{"itemId":"8e2c188a-65f3-52d7-b57c-cf1d9561318c","questionId":"f4b5de4f-e6b1-54dd-ab36-00781e35a5ef","sourceKey":"bank:TAX-CM223:INC-029","payload":{"prompt":"Under the Nigeria Tax Act 2025, what record-keeping duty applies to a company enjoying the Economic Development Tax Incentive?","options":["It must file its accounts only with the NIPC and not with the tax authority","It must keep records only for its non-priority business","It need not keep any records during the incentive period","It must keep separate books and records for its priority and non-priority income"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"A priority company must keep separate books for priority products and for other income, so the credit is applied only to priority profits. Option A is wrong because returns of profits are still required under the tax law."}},{"itemId":"832851a0-649f-5eb0-a299-a810f53f0526","questionId":"3c4af779-3d8b-5903-aee1-2410a0c5dc6f","sourceKey":"bank:TAX-CM223:INC-030","payload":{"prompt":"Under the Nigeria Tax Act 2025, can a company enjoying the Economic Development Tax Incentive also claim other tax reliefs for the same activity?","options":["Yes, provided it pays an extra 4% development levy","No, it is excluded from other tax reliefs while it enjoys the incentive","Yes, it can combine the incentive with any other relief","Yes, but only with the free trade zone exemption"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"A company granted the certificate and enjoying the incentive is excluded from simultaneously enjoying other tax reliefs under the Act or any other law. Options C and D allow stacking of reliefs, which the exclusion rule prevents."}},{"itemId":"2e459bd0-b258-5de4-9135-dd0878d3c5bd","questionId":"b877181d-36cb-5c9f-9aa6-3bed67f09df3","sourceKey":"bank:TAX-CM223:INC-031","payload":{"prompt":"Which of the following is listed as a priority sector eligible for the Economic Development Tax Incentive under the Nigeria Tax Act 2025?","options":["Pharmaceuticals and chemicals","Retail trading of imported goods","Lottery and betting operations","Casino and gaming operations"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Priority sectors include aquaculture, crude oil refining, electricity and gas supply, pharmaceuticals and chemicals, automobiles, renewable energy, medical equipment and textiles, among others. Options B, C and D are not among the listed productive priority sectors."}},{"itemId":"a618066b-fa9f-5250-a424-33c4a1d79718","questionId":"70ca4c9c-6c7c-5b78-8794-33046979ac1d","sourceKey":"bank:TAX-CM223:INC-032","payload":{"prompt":"Which of the following is NOT one of the priority sectors listed for the Economic Development Tax Incentive under the Nigeria Tax Act 2025?","options":["Textiles","Automobiles and components","Commercial banking","Renewable energy"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The listed priority sectors are mainly productive and industrial activities such as renewable energy, textiles, automobiles, metal processing and medical equipment. Options A, B and D all appear in the list, while commercial banking does not."}},{"itemId":"df2a8e65-e2e1-59b9-86dc-6a8f62cbd4a9","questionId":"34592e6e-dddb-5f43-83bc-b1dd4e420c71","sourceKey":"bank:TAX-CM223:INC-033","payload":{"prompt":"For an economic development incentive application, the NIPC charges a non-refundable fee of 0.1% of qualifying capital expenditure, capped at N5,000,000. What fee is payable on QCE of N2,000,000,000?","options":["N200,000","N20,000,000","N2,000,000","N5,000,000"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"Fee = 0.1% x N2,000,000,000 = N2,000,000, which is below the N5,000,000 cap. Option D applies the cap although it is not reached, and Option B uses 1% instead of 0.1%."}},{"itemId":"0178f0e4-868c-5609-a039-e42c9df68b5d","questionId":"a249f1e7-a1af-5ccb-8c95-0f656bd3eb43","sourceKey":"bank:TAX-CM223:INC-034","payload":{"prompt":"For an economic development incentive application, the NIPC charges a non-refundable fee of 0.1% of qualifying capital expenditure, capped at N5,000,000. What fee is payable on QCE of N8,000,000,000?","options":["N80,000,000","N8,000,000","N5,000,000","N4,000,000"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"0.1% x N8,000,000,000 = N8,000,000, which exceeds the cap, so the fee is limited to N5,000,000. Option B ignores the cap."}},{"itemId":"4581fd64-fe7b-55c7-81b7-8a83447faea5","questionId":"8b363745-30bf-593b-b79b-1a4667c309fc","sourceKey":"bank:TAX-CM223:INC-035","payload":{"prompt":"What happens to a company that already held a pioneer status certificate when the Nigeria Tax Act 2025 commenced?","options":["It keeps its pioneer relief for the unexpired period of the certificate","Its pioneer period is automatically doubled","It loses the relief immediately on 1 January 2026","It must repay all taxes previously exempted"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Existing pioneer status beneficiaries continue to enjoy the relief for the unexpired part of their period, while new applicants use the Economic Development Tax Incentive. Option C ignores the transition rule, and Option D has no legal basis."}},{"itemId":"8bb53afc-c19c-5690-a3f9-4447ed5985c8","questionId":"bb68c2b8-6cc2-5bb7-af37-7ab4ac47e715","sourceKey":"bank:TAX-CM223:INC-036","payload":{"prompt":"Under the Nigeria Tax Act 2025, for how long is the income of a company engaged in an agricultural business (such as crop production, livestock, aquaculture, forestry or dairy) exempt from tax?","options":["For the first five years from commencement of the business","For ten years from incorporation","For the first three years only","Permanently, as long as it remains in agriculture"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Agricultural businesses enjoy an income tax exemption for the first five years after they start business. Option C is too short, and Option D turns a time-limited relief into a permanent one."}},{"itemId":"8cd0eaf9-77e2-5589-b635-260928c01245","questionId":"51ac35e0-6781-58a7-b862-1ea8d1a779e3","sourceKey":"bank:TAX-CM223:INC-037","payload":{"prompt":"Which of the following businesses is among those listed as enjoying the five-year agricultural tax exemption under the Nigeria Tax Act 2025?","options":["Importing and distributing frozen fish","Running a chain of supermarkets","Providing agricultural consultancy services","Processing of cocoa into cocoa butter, cocoa oil and chocolate"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The agricultural exemption extends to activities such as dairy production, cocoa processing and the manufacture of animal feeds. Options A, B and C are trading or service businesses, not the listed agricultural activities."}},{"itemId":"9ade5aae-eec2-5e53-80be-7b0ed36c5746","questionId":"bec85b19-139f-5111-825e-2160cfb1c9d0","sourceKey":"bank:TAX-CM223:INC-038","payload":{"prompt":"Oyo Dairy Ltd commenced business on 1 January 2026, producing pasteurised milk and cheese. Under the Nigeria Tax Act 2025, how is its 2028 income treated?","options":["Exempt, because 2028 falls within its first five years of business","Taxable at 30%, because dairy is not an agricultural business","Taxable at 30%, because the exemption covers only the first two years","Exempt only if it exports all its products"],"correctOption":0,"section":"Tax Incentives and Free Trade Zones","explanation":"Dairy production is a listed agricultural business, and 2028 is the third year after commencement, inside the five-year exemption window. Option B wrongly excludes dairy, and Option D adds an export condition that the agricultural exemption does not contain."}},{"itemId":"1426aeeb-edc0-58ff-a8d1-38ce2a4547ed","questionId":"049cb09e-680d-5907-9c4c-ad3800e49369","sourceKey":"bank:TAX-CM223:INC-039","payload":{"prompt":"Zaria Feeds Ltd, which manufactures animal feeds, commenced business on 1 January 2026. It is not a small company and has no other relief. Its 2031 taxable profit is N50,000,000. With companies income tax at 30% under the Nigeria Tax Act 2025, what tax is payable for 2031?","options":["N7,500,000","Nil","N12,500,000","N15,000,000"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The five-year exemption covers 2026 to 2030, so 2031 (the sixth year) is taxable: 30% x N50,000,000 = N15,000,000. Option B wrongly treats 2031 as within the exemption period."}},{"itemId":"c971528d-2d22-5d65-8ada-14c55978559a","questionId":"ff12bdc5-0fb6-56a0-93c4-11b2ca26319a","sourceKey":"bank:TAX-CM223:INC-040","payload":{"prompt":"Under the Nigeria Tax Act 2025, the profits of a Nigerian company from goods exported from Nigeria are exempt from income tax on what condition?","options":["The company pays VAT at 7.5% on the exports","The goods are exported to an ECOWAS country only","The export proceeds are repatriated to Nigeria through official channels","The company is located in a free trade zone"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"Export profits are exempt where the proceeds are repatriated through official channels; petroleum operations are excluded from this exemption. Option D is wrong because the exemption is not limited to free zone entities, and Option A contradicts the zero-rating of exports."}},{"itemId":"a270b46e-6b0c-50e2-8440-13c70e3d4f3e","questionId":"dce93748-5910-5e91-8acf-a4d35bad05a1","sourceKey":"bank:TAX-CM223:INC-041","payload":{"prompt":"Ada Ventures, a venture capital fund, sells shares in a labelled startup that it held in Nigeria for 30 months. Under the Nigeria Tax Act 2025, how is the gain treated?","options":["Exempt only if the startup is a manufacturing company in a free zone","Taxable, because the minimum holding period is 36 months","Taxable, because only angel investors qualify","Exempt, because the asset was held for at least 24 months"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"Gains of angel investors, venture capitalists, private equity funds, accelerators and incubators on assets in labelled startups are exempt where the assets were held in Nigeria for at least 24 months. Option C wrongly excludes venture capitalists, and Option B invents a longer holding period."}},{"itemId":"9893274e-d13f-5779-8a23-06e4a4abac62","questionId":"d3c5a854-34b8-5fb0-9548-b1b818674b37","sourceKey":"bank:TAX-CM223:INC-042","payload":{"prompt":"An angel investor sells her shares in a labelled startup after holding them in Nigeria for 18 months. Under the Nigeria Tax Act 2025, does the startup gains exemption apply?","options":["Yes, because all startup gains are exempt","No, because angel investors are excluded from the exemption","Yes, because the minimum holding period is 12 months","No, because the 24-month minimum holding period has not been met"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"The exemption applies only where the startup assets have been held in Nigeria for at least 24 months, and 18 months falls short. Option C uses the wrong period, and Option B is wrong because angel investors are expressly covered."}},{"itemId":"426d9d32-757d-5e17-b6a4-dc6de7faf06b","questionId":"ef57e22f-a970-520e-98d1-157ee56c5e79","sourceKey":"bank:TAX-CM223:INC-043","payload":{"prompt":"Under the Nigeria Tax Act 2025, dividends received from investments in which type of business are exempt from income tax?","options":["Businesses that pay the development levy","Wholly export-oriented businesses","Businesses with turnover above N100 million","Any business located in Lagos"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"The Act exempts dividends received from investments in wholly export-oriented businesses, to encourage investment in exporters. Options A, C and D describe features with no link to this exemption."}},{"itemId":"f4ff1bba-acf4-5479-87fa-2b0b33ec8e49","questionId":"f482eb91-eae3-539e-af5b-b0447189b81d","sourceKey":"bank:TAX-CM223:INC-044","payload":{"prompt":"Enugu Agro Exports Ltd exports processed cashew nuts and brings the proceeds back to Nigeria through its bank via official foreign exchange channels. Under the Nigeria Tax Act 2025, what is the likely tax position of its export profits?","options":["Taxable at 15% under the minimum effective tax rate","Taxable at 30%, because only free zone entities can enjoy export exemptions","Exempt only for the first two years","Exempt from income tax, because the export proceeds were repatriated through official channels"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"Profits from goods exported from Nigeria are exempt where the proceeds are repatriated through official channels, and the business is not a petroleum operation. Option B is wrong because this exemption is separate from the free zone regime."}},{"itemId":"1c287d82-e9b0-5047-b7bc-e1896a761327","questionId":"e02c29cf-6868-5934-ba32-7ffbe3e5ac84","sourceKey":"bank:TAX-CM223:INC-045","payload":{"prompt":"A company holding an economic development incentive certificate also runs a non-priority business. Under the Nigeria Tax Act 2025, the economic development tax credit is based on the tax payable on profits from:","options":["Only the non-priority business","The priority product or service during the priority period","The company's dividends to shareholders","All the company's businesses, priority and non-priority"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"The credit relates to tax on profits from the priority product or service earned in the priority period, which is why separate records must be kept. Option D would extend the incentive to non-priority income, which the Act does not allow."}},{"itemId":"eea44e97-c845-5837-9a59-7cdd864de845","questionId":"51ff376b-e9d2-5abc-b89a-797650f2d74e","sourceKey":"bank:TAX-CM223:INC-046","payload":{"prompt":"A priority company earns an economic development tax credit of 5% of its N1,000,000,000 qualifying capital expenditure each year. Its tax payable on priority profits in years 1, 2 and 3 is N20,000,000, N40,000,000 and N70,000,000. If unused credit is carried forward and used in later years of the priority period, what unused credit remains at the end of year 3?","options":["N150,000,000","N90,000,000","N30,000,000","N20,000,000"],"correctOption":3,"section":"Tax Incentives and Free Trade Zones","explanation":"Each year's credit is N50,000,000, so 3 years = N150,000,000; total tax offset = N130,000,000; unused = N150,000,000 - N130,000,000 = N20,000,000. Option B forgets to use credit against year 3 tax, and Option C looks at year 1 only."}},{"itemId":"b4981954-ef8b-5227-a7be-8bef858db90b","questionId":"ff40b4dd-84f6-5a9d-8aca-c975b3a2512c","sourceKey":"bank:TAX-CM223:INC-047","payload":{"prompt":"Which statement best compares the free trade zone regime with the Economic Development Tax Incentive under the Nigeria Tax Act 2025?","options":["Both depend only on the number of Nigerian employees","Free zone relief turns on where sales go; the incentive turns on QCE in a priority sector","Both are granted and administered by the Nigeria Customs Service","Free zone relief is a 5% tax credit, while the incentive is a full exemption"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Free zone entities are exempt according to how much they sell to the customs territory, while the incentive gives a credit tied to qualifying capital expenditure by an approved priority company. Option D reverses the two mechanisms."}},{"itemId":"cb8fdefb-1e93-51de-89a9-db3394ba5b5b","questionId":"63f03518-1c27-591e-8a82-d15f807589f6","sourceKey":"bank:TAX-CM223:INC-048","payload":{"prompt":"Which condition must a priority company meet regarding its qualifying capital expenditure to be considered for an economic development incentive certificate under the Nigeria Tax Act 2025?","options":["Its capital expenditure must be below N250 million","The qualifying capital expenditure incurred on or before production day must not be below the threshold for its sector","It must have incurred no capital expenditure before production day","Its capital expenditure must be financed only with foreign loans"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"An application is considered only where the qualifying capital expenditure incurred on or before production day is at least the amount set for its sector in the Tenth Schedule. Option A turns a minimum threshold into a maximum."}},{"itemId":"c1b4bac7-ee90-54c8-9a43-00a3d91f8219","questionId":"d72f9d5e-baba-580d-af02-5da42751154e","sourceKey":"bank:TAX-CM223:INC-049","payload":{"prompt":"Apapa Free Zone Packaging Ltd, a licensed free zone entity, pays a Lagos consulting firm for management services. Under the 2025 framework, is the payment automatically free of withholding tax because the payer is in a free zone?","options":["No, and the free zone entity also loses its income tax exemption","Yes, all payments by or to free zone entities are outside withholding tax","No, free zone entities have no general withholding tax exemption, so deduction rules still apply","Yes, but only if the consultant is also in a free zone"],"correctOption":2,"section":"Tax Incentives and Free Trade Zones","explanation":"The 2025 framework gives free zone entities no general withholding tax exemption, so payments such as management or professional fees remain subject to the deduction rules. Option B overstates the free zone privileges, and Option A wrongly links a withholding duty to the entity's own income tax position."}},{"itemId":"8b6ea131-38b9-5d58-aba9-fdba1f17cb51","questionId":"c41eb12a-af52-5ffa-b5e0-99e1ce7f38bf","sourceKey":"bank:TAX-CM223:INC-050","payload":{"prompt":"Ijebu Glass Ltd holds an economic development incentive certificate and its production day is 1 July 2026. Under the Nigeria Tax Act 2025, the initial incentive period is five years from production day, extendable by five more years if 100% of profits are reinvested in the same product(s). If no extension is granted, on what date does the initial incentive period end?","options":["30 June 2030","30 June 2031","31 December 2030","30 June 2036"],"correctOption":1,"section":"Tax Incentives and Free Trade Zones","explanation":"Five years running from 1 July 2026 end on 30 June 2031. Option A counts only four years, Option C wrongly runs the period from 1 January 2026, and Option D assumes the five-year extension was granted."}}]}$official_bank_source$::jsonb;
  v_course uuid := (v_bank->>'courseId')::uuid;
  v_actor uuid := (v_bank->>'actor')::uuid;
  v_seed_actor uuid := (v_bank->>'seedActor')::uuid;
  v_audited jsonb;
  v_final jsonb;
  v_live jsonb;
  v_row jsonb;
  v_id uuid;
  v_item public.managed_content_items%rowtype;
  v_catalogue uuid;
begin
  if p_action is null or p_action not in ('apply', 'rollback') then
    raise exception 'Official bank %: unknown action %', v_bank->>'code', p_action;
  end if;
  -- Every CBT question of the course, locked in one order before anything is read or written.
  perform 1 from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' order by id for update;
  -- A new course, once: its repository identity and the link from its catalogue course, which must already apply at the
  -- official level and semesters. A rerun finds them in place; anything else is refused.
  if p_action = 'apply' then
    insert into public.courses (id, content_key, is_shared)
      values (v_course, v_bank->'shell'->>'contentKey', null) on conflict do nothing;
    if not exists (select 1 from public.courses where id = v_course and content_key = v_bank->'shell'->>'contentKey') then
      raise exception 'Official bank %: the repository identity is not this course''s', v_bank->>'code';
    end if;
    update public.institutional_courses set repository_course_id = v_course
      where course_code = v_bank->>'code' and repository_course_id is null
        and display_title in (select jsonb_array_elements_text(v_bank->'shell'->'titles'));
    select id into v_catalogue from public.institutional_courses
      where course_code = v_bank->>'code' and repository_course_id = v_course;
    if v_catalogue is null or (select count(*) from public.institutional_courses where course_code = v_bank->>'code') <> 1 then
      raise exception 'Official bank %: the catalogue course is not linked exactly once', v_bank->>'code';
    end if;
    -- Which students see the course stays the catalogue's: the import never adds or removes applicability rows.
    -- It refuses a catalogue course that does not already apply at the official level in every official semester.
    if exists (select 1 from jsonb_array_elements_text(v_bank->'shell'->'semesters') s(key)
        where not exists (select 1 from public.course_applicability a
          join public.academic_levels l on l.id = a.academic_level_id
          join public.academic_periods p on p.id = a.academic_period_id
          where a.institutional_course_id = v_catalogue and l.key = v_bank->'shell'->>'level' and p.key = s.key)) then
      raise exception 'Official bank %: the catalogue course does not apply at the official level in every official semester',
        v_bank->>'code';
    end if;
  end if;
  select coalesce(jsonb_object_agg(value, 1), '{}') into v_audited from jsonb_array_elements_text(v_bank->'audited');
  select coalesce(jsonb_object_agg(k.value->>'itemId', case when (k.value->>'revise')::boolean then 2 else 1 end), '{}')
    || coalesce((select jsonb_object_agg(a.value->>'itemId', 1) from jsonb_array_elements(v_bank->'add') a), '{}')
    into v_final from jsonb_array_elements(v_bank->'keep') k;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;

  if p_action = 'apply' then
    if v_live = v_final then
      return 'unchanged';
    end if;
    if v_live <> v_audited then
      raise exception 'Official bank %: the published questions are not the audited set', v_bank->>'code';
    end if;

    -- Kept questions keep their item and question id; a different bank payload becomes the next revision.
    for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
      if v_item.created_by is distinct from v_seed_actor then
        raise exception 'Official bank %: % is not a migration-owned question', v_bank->>'code', v_item.id;
      end if;
      if exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2) then
        if not exists (select 1 from public.managed_content_revisions where item_id = v_item.id and revision = 2
            and payload = v_row->'payload' and authored_by = v_actor) or v_item.current_revision <> 2 then
          raise exception 'Official bank %: % has another revision two', v_bank->>'code', v_item.id;
        end if;
      else
        if v_item.current_revision <> 1 then
          raise exception 'Official bank %: % has an unpublished edit', v_bank->>'code', v_item.id;
        end if;
        perform private.assert_managed_payload('cbt_question', v_row->'payload');
        insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
          values (v_item.id, 2, v_row->'payload', v_actor);
        update public.managed_content_items set current_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      if v_item.approved_revision is distinct from 2 then
        insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
          values (v_item.id, 2, null, 'approved', v_actor, v_item.lock_version + 1);
        update public.managed_content_items set approved_revision = 2, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id returning * into v_item;
      end if;
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
          previous_revision, previous_parent_revision, acted_by)
        values (v_item.id, v_item.lock_version + 1, 'publish', 2, null, v_item.published_revision, null, v_actor);
      update public.managed_content_items set published_revision = 2, lock_version = lock_version + 1,
        updated_at = now() where id = v_item.id;
    end loop;

    -- Retired questions are unpublished, never deleted: past attempts and reports keep their pinned revision.
    for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
      select * into v_item from public.managed_content_items where id = v_id;
      insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
        values (v_id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
      update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
        updated_at = now() where id = v_id;
    end loop;

    -- New questions: created, approved and published at revision one, or republished after a rollback.
    for v_row in select value from jsonb_array_elements(v_bank->'add') loop
      select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid for update;
      if found then
        if v_item.created_by is distinct from v_actor or v_item.course_id is distinct from v_course or
           v_item.kind is distinct from 'cbt_question' or v_item.question_id is distinct from (v_row->>'questionId')::uuid or
           v_item.source_key is distinct from v_row->>'sourceKey' or v_item.approved_revision is distinct from 1 or
           not exists (select 1 from public.managed_content_revisions r where r.item_id = v_item.id and r.revision = 1
             and r.payload = v_row->'payload' and r.authored_by = v_actor) then
          raise exception 'Official bank %: % is not the same migration-owned question', v_bank->>'code', v_item.id;
        end if;
        insert into public.managed_content_publications (item_id, lock_version, action, revision,
            previous_revision, acted_by)
          values (v_item.id, v_item.lock_version + 1, 'publish', 1, v_item.published_revision, v_actor);
        update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
          updated_at = now() where id = v_item.id;
        continue;
      end if;
      perform private.assert_managed_payload('cbt_question', v_row->'payload');
      insert into public.managed_content_items (id, course_id, kind, question_id, source_key, parent_item_id,
          current_revision, approved_revision, published_revision, published_parent_revision, lock_version, created_by)
        values ((v_row->>'itemId')::uuid, v_course, 'cbt_question', (v_row->>'questionId')::uuid,
          v_row->>'sourceKey', null, 1, 1, 1, null, 3, v_actor);
      insert into public.managed_content_revisions (item_id, revision, payload, authored_by)
        values ((v_row->>'itemId')::uuid, 1, v_row->'payload', v_actor);
      insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
        values ((v_row->>'itemId')::uuid, 1, null, 'approved', v_actor, 2);
      insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision, acted_by)
        values ((v_row->>'itemId')::uuid, 3, 'publish', 1, null, v_actor);
    end loop;

    select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
      where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
    if v_live <> v_final or (select count(*) from jsonb_object_keys(v_live)) <> (v_bank->>'bankCount')::integer then
      raise exception 'Official bank %: the final published count is not the bank count', v_bank->>'code';
    end if;
    return 'applied';
  end if;

  -- Rollback: publication is a pointer, so the audited set is republished through the same history.
  if v_live = v_audited then
    return 'unchanged';
  end if;
  if v_live <> v_final then
    raise exception 'Official bank %: the published questions are not the imported set', v_bank->>'code';
  end if;
  for v_row in select value from jsonb_array_elements(v_bank->'keep') where (value->>'revise')::boolean loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_reviews (item_id, revision, parent_revision, decision, reviewed_by, lock_version)
      values (v_item.id, 1, null, 'approved', v_actor, v_item.lock_version + 1);
    insert into public.managed_content_publications (item_id, lock_version, action, revision, parent_revision,
        previous_revision, previous_parent_revision, acted_by)
      values (v_item.id, v_item.lock_version + 2, 'publish', 1, null, v_item.published_revision, null, v_actor);
    update public.managed_content_items set approved_revision = 1, published_revision = 1,
      lock_version = lock_version + 2, updated_at = now() where id = v_item.id;
  end loop;
  for v_id in select value::uuid from jsonb_array_elements_text(v_bank->'retire') loop
    select * into v_item from public.managed_content_items where id = v_id;
    if v_item.approved_revision is distinct from 1 then
      raise exception 'Official bank %: % is no longer approved at revision one', v_bank->>'code', v_id;
    end if;
    insert into public.managed_content_publications (item_id, lock_version, action, revision, acted_by)
      values (v_id, v_item.lock_version + 1, 'publish', 1, v_actor);
    update public.managed_content_items set published_revision = 1, lock_version = lock_version + 1,
      updated_at = now() where id = v_id;
  end loop;
  for v_row in select value from jsonb_array_elements(v_bank->'add') loop
    select * into v_item from public.managed_content_items where id = (v_row->>'itemId')::uuid;
    insert into public.managed_content_publications (item_id, lock_version, action, previous_revision, acted_by)
      values (v_item.id, v_item.lock_version + 1, 'unpublish', v_item.published_revision, v_actor);
    update public.managed_content_items set published_revision = null, lock_version = lock_version + 1,
      updated_at = now() where id = v_item.id;
  end loop;
  select coalesce(jsonb_object_agg(id::text, published_revision), '{}') into v_live from public.managed_content_items
    where course_id = v_course and kind = 'cbt_question' and published_revision is not null;
  if v_live <> v_audited then
    raise exception 'Official bank %: rollback did not restore the audited set', v_bank->>'code';
  end if;
  return 'rolled-back';
end;
$official_bank$;

revoke all on function private.official_bank_tax_cm223(text) from public, anon, authenticated, service_role;
select private.official_bank_tax_cm223('apply');
